/* MathQuest — Français 6e (collège), année scolaire 2026-2027 : 26 chapitres reconstruits (fr6a … fr6z).
   Programme appliqué : programme de français du cycle 3 publié au BO n°16 du 17 avril 2025 (NOR MENE2504620A),
   applicable en 6e depuis la rentrée 2025 — annexe 1 « Programme de français pour le cycle 3 »
   (https://www.education.gouv.fr/sites/default/files/ensel620_annexe1.pdf ; BO : https://www.education.gouv.fr/bo/2025/Hebdo16/MENE2504620A).
   Ressources d'accompagnement : Éduscol, « Exemples pour la mise en œuvre du programme de français en 6e » (2025) ;
   DGESCO, « La grammaire du français du CP à la 6e » (guide fondamental) et « La grammaire du français. Terminologie grammaticale » (2020).
   Vérifié le 7 octobre 2026 sur education.gouv.fr (annexe PDF du BO) et eduscol.education.gouv.fr.
   Textes : extraits écrits pour MathQuest, ou citations courtes et exactes d'œuvres du domaine public (Bible, trad. Segond 1910 ;
   La Fontaine ; Molière ; Racine ; Hugo ; Verlaine ; Rimbaud ; Baudelaire ; Ronsard). */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,txt,order,bank,pairs,sort,seq,mix,pickN,shuffle,nf}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const REF='Français cycle 3 — programme du BO n°16 du 17 avril 2025 (MENE2504620A), applicable en 6e depuis la rentrée 2025';
const EX6='Éduscol — « Exemples pour la mise en œuvre du programme de français en 6e » (2025) : exemples de réussite, propositions d’œuvres littéraires';
const GRAM='Éduscol / DGESCO — « La grammaire du français du CP à la 6e » et « La grammaire du français. Terminologie grammaticale » (2020)';
const say=t=>({t,l:'fr-FR'});
const CHIPS=['é','è','ê','à','â','ç','î','ô','û','’'];
const cap=s=>s.charAt(0).toUpperCase()+s.slice(1);
const VOW=/^[aeiouyéèêàâîïôûh]/i;
// Choix d'un élément selon la difficulté : niveau en position k (défaut 1).
const lvOf=(x,k)=>typeof x[k]==='number'?x[k]:1;
function lvPick(items,d,k){const ok=items.filter(x=>lvOf(x,k)<=d);const ex=ok.filter(x=>lvOf(x,k)===d);return (ex.length&&Math.random()<.6)?P(ex):P(ok.length?ok:items);}
// Phrase avec un groupe repéré entre [[ ]] : affiché en gras.
const mark=s=>s.replace(/\[\[(.+?)\]\]/g,'<b>$1</b>');
const grp=s=>(s.match(/\[\[(.+?)\]\]/)||['',''])[1];
/* Questions « groupe en gras » : items = [phrase avec [[groupe]], bonne réponse, explication propre, niveau].
   all = toutes les réponses possibles ; o.q contient %p (phrase) ; o.e(a,g) = explication générale. */
function tagged(items,all,o){return d=>{const it=lvPick(items,d,3);const [s,a,e]=it;const g=grp(s);
  const bad=pickN(all.filter(x=>x!==a),o.n||3);
  return ch(o.q.replace('%p',mark(s)).replace('%g',g),a,bad,{expl:[o.e?o.e(a,g):'',e||''].filter(Boolean).join(' '),hint:o.hint});};}
/* Questions sur un texte : texts = [[texte, [[question, bonne, [mauvaises], explication, niveau], …]], …] */
function onText(texts,o={}){return d=>{const [t,qs]=P(texts);const [q,a,b,e]=lvPick(qs,d,4);
  return ch(`<div class="trad">${t}</div>${q}`,a,b,{expl:e,hint:o.hint||'Relis le texte et cherche l’indice précis qui justifie ta réponse.',audio:say(t.replace(/<[^>]+>/g,''))});};}
// Conjugaison complémentaire (conditionnel présent, impératif présent).
const ER6=H.ER.filter(v=>v!=='nager');
const futRad=v=>H.futur(v)[0].slice(0,-2);
const condit=(v,i)=>futRad(v)+['ais','ais','ait','ions','iez','aient'][i];
const IMPV={'être':['sois','soyons','soyez'],'avoir':['aie','ayons','ayez'],'aller':['va','allons','allez'],'faire':['fais','faisons','faites'],'dire':['dis','disons','dites'],'venir':['viens','venons','venez'],'voir':['vois','voyons','voyez'],'prendre':['prends','prenons','prenez']};
const imperatif=v=>{if(IMPV[v])return IMPV[v];const p=H.present(v);return [H.IR2.includes(v)?p[1]:p[0],p[3],p[4]];};
const PRON=['je','tu','il','nous','vous','ils'];
const sj=(i,f,lab)=>{const p=lab||PRON[i];return (p==='je'&&VOW.test(f))?'j’':p+' ';};

MQ.add('francais','6',[
/* ===================== LECTURE ===================== */
{id:'fr6a',name:'Lire avec fluidité et expressivité',icon:'📖',domain:'Lecture',
 refs:[REF+' — « Lire avec fluidité » (environ 130 mots par minute en moyenne) et « Lire à voix haute avec expressivité »',EX6],
 tip:'Avant de lire à voix haute, trace de petites barres (/) entre les groupes de sens et entoure la ponctuation : tes pauses tomberont au bon endroit.',
 c:C(`Lire à voix haute devant la classe, ce n’est pas réciter le plus vite possible. Un bon lecteur lit <b>juste</b> (sans erreur), avec un <b>rythme</b> régulier, et il fait <b>entendre le sens</b> : les pauses, les questions, les émotions des personnages. Comment s’y prendre ?`,
  [T('Lire avec fluidité',`<p>La <b>fluidité</b> associe trois choses : l’<b>exactitude</b> (lire chaque mot correctement), la <b>vitesse</b> et la <b>compréhension</b>. En 6e, le programme vise environ <b>130 mots lus correctement par minute</b> en moyenne.</p><p>On lit par <b>groupes de sens</b> (des mots qui vont ensemble, comme « le vieux pêcheur » ou « au bord de la mer ») et non mot par mot. On ne coupe jamais un groupe en deux.</p><p>Pour mesurer sa vitesse : nombre de mots lus correctement ÷ nombre de minutes. Exemple : 260 mots en 2 minutes → 130 mots par minute.</p>`),
   T('Ponctuation et liaisons',`<table class="ptable"><tr><th>Signe</th><th>À l’oral</th></tr><tr><td>virgule</td><td>courte pause</td></tr><tr><td>point</td><td>pause plus longue, la voix descend</td></tr><tr><td>point d’interrogation</td><td>la voix monte (question)</td></tr><tr><td>point d’exclamation</td><td>émotion : surprise, joie, colère, peur</td></tr><tr><td>points de suspension</td><td>la voix reste en suspens : hésitation, suspense</td></tr><tr><td>deux-points</td><td>petite pause qui annonce une explication, une liste ou des paroles</td></tr></table><p>Liaisons <b>obligatoires</b> : entre le déterminant et le nom (les‿amis, un‿arbre), entre le pronom et le verbe (ils‿ont, nous‿avons), entre l’adjectif et le nom qui le suit (un petit‿enfant). Liaisons <b>interdites</b> : après « et » (et / il part), devant un h aspiré (les / héros, les / haricots), après un nom singulier (un enfant / adorable).</p>`),
   T('Lire avec expressivité',`<p>Lire avec expressivité, c’est faire entendre les <b>émotions</b> des personnages et les <b>intentions</b> de l’auteur. On adapte le <b>volume</b> (fort, doux), le <b>débit</b> (plus rapide dans l’action, plus lent dans une description inquiétante), l’<b>intonation</b> et les <b>pauses</b>.</p><p>Dans un dialogue, on change légèrement de voix pour chaque personnage. Le <b>verbe de parole</b> donne un indice : « murmura » → voix basse ; « hurla » → voix forte ; « ricana » → ton moqueur ; « sanglota » → voix brisée. L’incise (« dit-il ») se lit plus neutre et un peu plus bas. En 6e, on vise un texte de 10 à 20 lignes lu avec aisance, en <b>regardant l’auditoire</b>.</p>`)],
  [{q:'Comment lire « Soudain, derrière la porte, un bruit éclata. » ?',s:['Je repère les groupes de sens : « Soudain » / « derrière la porte » / « un bruit éclata ».','Je marque une courte pause à chaque virgule et je fais monter la tension avant « un bruit ».','J’accentue « éclata » sans crier, puis la voix descend au point final.','La lecture expressive sert le sens : elle se prépare, elle ne se joue pas au hasard.']},
   {q:'Yanis lit correctement 195 mots en 1 min 30 s. Atteint-il le repère de 6e ?',s:['1 min 30 s = 1,5 min.','195 ÷ 1,5 = 130 mots par minute.','Il atteint le repère de 6e (environ 130 mots par minute), à condition d’avoir compris ce qu’il a lu.']}],
  ['Je lis d’abord le texte silencieusement pour le comprendre.','Je repère la ponctuation, les groupes de sens et les liaisons ; je prépare les mots difficiles.','Je choisis le ton de chaque passage (récit, dialogue, émotion d’un personnage).','Je m’entraîne, je m’enregistre et je m’écoute pour améliorer mon rythme et mon expression.'],
  ['Lire le plus vite possible : une lecture rapide mais sans pauses ni sens n’est pas fluide.','Lire mot par mot ou couper un groupe de sens (« le vieux / pêcheur »).','Faire une liaison interdite (« et‿il », « les‿héros ») ou oublier une liaison obligatoire (« les / amis »).','Lire l’incise « dit-il » avec la même voix que la réplique du personnage.'],
  ['Fluidité = exactitude + rythme + compréhension ; repère de 6e : environ 130 mots par minute.','La ponctuation et les groupes de sens guident les pauses et l’intonation.','Le verbe de parole et la situation indiquent le ton ; une lecture expressive se prépare et se lit en regardant l’auditoire.']),
 g:mix([d=>{const w=P([90,100,110,120,130,140,150,160]),j=R(2,d===1?4:8),s=30*j,n=w*j/2,mn=s/60;
    const t=s%60?`${Math.floor(mn)} min 30 s`:`${mn} min`;
    return num(`Un élève lit correctement <b>${n} mots</b> en <b>${t}</b>. Quelle est sa vitesse de lecture, en mots par minute ?`,w,{unit:'mots/min',expl:`${s%60?t+' = '+nf(mn)+' min ; ':''}${n} ÷ ${nf(mn)} = <b>${w} mots par minute</b>.${w>=130?' Il atteint le repère de 6e (environ 130 mots par minute).':' Il est encore sous le repère de 6e (environ 130 mots par minute) : l’entraînement régulier l’aidera.'}`,hint:'Divise le nombre de mots par le nombre de minutes (30 s = 0,5 min).'});},2],
  [d=>{const m=P([2,3,4,5]),w=P([110,120,130,140]);return num(`À la vitesse de <b>${w} mots par minute</b>, combien de mots lit-on en <b>${m} minutes</b> ?`,w*m,{unit:'mots',expl:`${w} × ${m} = <b>${w*m} mots</b>.`,hint:'Multiplie la vitesse par le nombre de minutes.'});},1],
  [sort({'liaison obligatoire':['les amis','un arbre','ils ont','nous avons','des oiseaux','mes enfants','un petit animal','on arrive','deux ours','vous êtes'],'liaison interdite':['et il part','les héros','des haricots','un hibou','les hiboux','un enfant adorable','Paul et Anne','les hérissons']},{q:'À voix haute, dans « %s », la liaison est…',e:(x,c)=>c==='liaison obligatoire'?`« ${x} » : liaison obligatoire (déterminant + nom, pronom + verbe ou adjectif + nom).`:`« ${x} » : liaison interdite (après « et », devant un h aspiré ou après un nom singulier).`,hint:'Liaison obligatoire : déterminant + nom, pronom + verbe, adjectif + nom.'}),2],
  [pairs([['murmura','très doucement, presque sans bruit'],['hurla','très fort, en criant'],['ricana','d’un ton moqueur'],['sanglota','en pleurant, la voix brisée'],['bégaya','en butant sur les mots'],['grommela','en marmonnant, de mauvaise humeur'],['ordonna','d’un ton autoritaire'],['soupira','avec lassitude, en expirant longuement'],['s’exclama','avec force et surprise']],{q:'Le texte dit : « Laisse-moi tranquille… », <b>%s</b> le vieil homme. Comment lire sa réplique ?',rq:'Quel verbe de parole indique qu’il faut lire une réplique %s ?',e:(a,b)=>`Le verbe de parole « ${a} » indique qu’il faut lire ${b}.`,hint:'Le verbe de parole donne le ton.'}),2],
  [bank([['Quelle découpe en groupes de sens est la bonne ?','Le vieux pêcheur / regardait la mer / depuis le quai.',['Le vieux / pêcheur regardait / la mer depuis le quai.','Le / vieux pêcheur regardait la / mer depuis le quai.','Le vieux pêcheur regardait / la / mer depuis / le quai.'],'On ne sépare pas les mots d’un même groupe : « le vieux pêcheur » (sujet), « regardait la mer », « depuis le quai ».'],
   ['Quelle découpe en groupes de sens est la bonne ?','Au fond de la forêt, / une petite cabane / attendait les voyageurs.',['Au fond / de la forêt, une petite / cabane attendait les voyageurs.','Au fond de la / forêt, une / petite cabane attendait les voyageurs.','Au / fond de la forêt, une petite cabane attendait / les / voyageurs.'],'Les groupes de sens : le lieu (« au fond de la forêt »), le sujet (« une petite cabane »), le groupe verbal.'],
   ['Quelle découpe en groupes de sens est la bonne ?','Chaque soir, / ma grand-mère / nous racontait / une histoire de loups.',['Chaque / soir, ma grand-mère nous / racontait une histoire / de loups.','Chaque soir, ma / grand-mère nous racontait une / histoire de loups.','Chaque soir, ma grand-mère nous racontait une histoire / de / loups.'],'On garde ensemble « ma grand-mère » et « une histoire de loups ».',2],
   ['À l’oral, que fait la voix devant un point d’interrogation ?','Elle monte.',['Elle descend.','Elle reste muette.','Elle chuchote obligatoirement.'],'Une question se marque par une intonation montante.'],
   ['À l’oral, que signale un point d’exclamation ?','une émotion (surprise, joie, colère, peur)',['une question','une simple pause courte','la fin d’un paragraphe'],'Le point d’exclamation demande de faire entendre une émotion.'],
   ['Que traduisent souvent les points de suspension à l’oral ?','une hésitation ou un suspense : la voix reste en suspens',['une question','une liste','un ordre sec'],'La voix ne descend pas complètement : la phrase semble inachevée.'],
   ['Quel signe demande la pause la plus courte ?','la virgule',['le point','le point-virgule','le point final d’un paragraphe'],'La virgule marque une courte pause à l’intérieur de la phrase.'],
   ['Quel repère de vitesse de lecture le programme fixe-t-il en 6e ?','environ 130 mots par minute en moyenne',['environ 50 mots par minute','environ 300 mots par minute','aucun repère chiffré'],'Le programme de cycle 3 vise 110 mots par minute en CM1, 120 en CM2 et environ 130 en 6e.'],
   ['En 6e, quelle longueur de texte doit-on savoir lire à voix haute avec aisance et expressivité ?','un texte de 10 à 20 lignes',['une seule phrase','un roman entier','trois mots'],'Le programme de 6e indique un texte de 10 à 20 lignes, en regardant l’auditoire.',2],
   ['Dans « “Sauve-toi !” cria Léa », comment lire l’incise « cria Léa » ?','plus neutre et un peu plus bas que la réplique',['plus fort que la réplique','en chantant','en la sautant'],'L’incise n’est pas prononcée par le personnage : on la lit de façon plus neutre.',2],
   ['Pourquoi s’enregistrer en lisant ?','pour s’écouter et repérer ce qu’il faut améliorer (rythme, pauses, ton)',['pour lire plus vite sans comprendre','pour éviter de préparer sa lecture','pour ne plus jamais lire à voix haute'],'S’écouter permet de corriger ses erreurs et ses hésitations.',2],
   ['Une description inquiétante se lit plutôt…','lentement, en ménageant des pauses',['très vite, sans pause','en criant','en riant'],'Le débit s’adapte au sens : la lenteur installe l’inquiétude.',3],
   ['Une scène d’action (poursuite, combat) se lit plutôt…','avec un débit plus rapide et énergique',['très lentement et d’une voix endormie','sans aucune intonation','en chuchotant chaque mot'],'Le rythme de la lecture suit le rythme de l’action.',3],
   ['Laquelle de ces lectures est la plus fluide ?','une lecture juste, par groupes de sens, qui respecte la ponctuation',['une lecture très rapide qui saute des mots','une lecture mot par mot, sans erreur mais hachée','une lecture forte qui ignore les points'],'Fluidité = exactitude + rythme + compréhension.',2]]),3])},

{id:'fr6b',name:'Comprendre l’explicite et l’implicite',icon:'🕵️',domain:'Lecture',
 refs:[REF+' — « Repérer les informations explicites et implicites, les liens logiques, les reprises nominales » ; « Justifier ses interprétations »',EX6],
 tip:'Pour une question d’implicite, cherche au moins deux indices dans le texte, puis écris : « Je pense que… car le texte dit… ».',
 c:C(`Un auteur ne dit pas tout. Si un personnage « referme son parapluie et secoue ses chaussures mouillées », le texte n’écrit pas « il pleut »… et pourtant tu le comprends. Lire, c’est relier les indices pour <b>déduire</b> ce qui n’est pas écrit.`,
  [T('Explicite et implicite',`<p>Une information <b>explicite</b> est écrite directement dans le texte : on peut la souligner.</p><p>Une information <b>implicite</b> n’est pas écrite : on la <b>déduit</b> (on fait une <b>inférence</b>) en reliant plusieurs <b>indices</b> du texte et ses propres connaissances. Exemple : « Les toits étaient blancs et les enfants glissaient sur le trottoir » → il a neigé, il fait froid.</p><p>Une déduction n’est valable que si l’on peut citer les indices qui la prouvent : on ne répond pas avec son imagination.</p>`),
   T('Reprises et liens logiques',`<p>Pour suivre un personnage, on repère les <b>reprises</b> : reprises pronominales (il, elle, le, lui…) et reprises nominales (« un renard » → « l’animal rusé » → « le voleur de poules »).</p><p>Les <b>liens logiques</b> aident à comprendre : <b>cause</b> (car, parce que, à cause de), <b>conséquence</b> (donc, alors, c’est pourquoi), <b>opposition</b> (mais, pourtant, cependant), <b>temps</b> (puis, soudain, quand).</p>`),
   T('Justifier sa réponse',`<p>Une bonne réponse de lecture contient : la <b>réponse</b>, l’<b>indice</b> (une citation courte entre guillemets ou une reformulation précise) et l’<b>explication</b> du lien entre les deux.</p><p>Exemple : « Le facteur a peur, car il recule et ne quitte pas le chien des yeux : il se méfie de l’animal. »</p>`)],
  [{q:'« Lina referma son parapluie en entrant et secoua ses chaussures mouillées. » Quel temps fait-il probablement ?',s:['Le texte ne dit pas « il pleut » : l’information est implicite.','Indices : le parapluie et les chaussures mouillées.','Réponse : « Il pleut probablement, car Lina a un parapluie et ses chaussures sont mouillées. »']}],
  ['Je lis d’abord la question pour savoir ce que je cherche.','Je surligne les indices utiles (mots, gestes, réactions, détails du décor).','Je relie les indices pour formuler ma déduction.','Je justifie en citant l’indice et en expliquant ce qu’il prouve.'],
  ['Répondre avec son imagination sans s’appuyer sur le texte.','Confondre ce qui est écrit (explicite) et ce qu’on déduit (implicite).','Choisir comme antécédent d’un pronom le nom le plus proche sans vérifier le sens.'],
  ['Explicite = écrit ; implicite = déduit grâce aux indices.','Une déduction se justifie toujours par un indice précis du texte.','Reprises et liens logiques permettent de suivre les personnages et les idées.']),
 g:mix([onText([
  ['Malo poussa la porte de la cuisine. Une odeur de pommes chaudes et de cannelle flottait dans la pièce. Sur la table, le plat était vide ; il ne restait que quelques miettes dorées. Sa sœur, assise près de la fenêtre, s’essuyait la bouche avec un air innocent.',[
    ['Qu’a probablement fait la sœur de Malo ?','Elle a mangé le gâteau aux pommes.',['Elle a préparé le dîner.','Elle a ouvert la fenêtre pour aérer.','Elle attendait Malo pour partager.'],'Implicite : le plat vide, les miettes et la bouche qu’elle essuie sont des indices qu’elle a tout mangé.'],
    ['Quelle information est explicite ?','Le plat est vide.',['La sœur est gourmande.','Malo est en colère.','La sœur a menti.'],'« le plat était vide » est écrit dans le texte : c’est explicite.'],
    ['Que suggère l’expression « un air innocent » ?','Elle veut cacher ce qu’elle a fait.',['Elle ne sait vraiment rien.','Elle est malade.','Elle est très jeune.'],'Après les indices qui l’accusent, cet air « innocent » montre qu’elle joue la comédie.',2]]],
  ['Le vieux marin regardait l’horizon. Ses mains tremblaient sur la barre. Depuis trois jours, aucun oiseau n’avait traversé le ciel, et l’eau douce tenait au fond d’un seul tonneau. Il ne dit rien à l’équipage.',[
    ['Pourquoi le marin est-il inquiet ?','La terre semble encore loin et l’eau douce va manquer.',['Il a peur des oiseaux.','Il veut rentrer dîner.','Le bateau est trop rapide.'],'Indices : pas d’oiseau (signe que la côte est loin) et un seul tonneau d’eau douce.'],
    ['Pourquoi ne dit-il rien à l’équipage ?','Il ne veut pas affoler les marins.',['Il a perdu la voix.','Il ne parle pas leur langue.','Les marins dorment tous.'],'On le déduit : il garde son inquiétude pour lui afin d’éviter la panique.',2],
    ['Quelle information est explicite ?','Il ne reste qu’un tonneau d’eau douce.',['Le marin a peur de mourir.','L’équipage va se révolter.','Le marin est le capitaine.'],'Le texte écrit que l’eau douce « tenait au fond d’un seul tonneau ».']]],
  ['Quand la cloche sonna, Inès rangea lentement ses affaires. Elle regarda une dernière fois la cour, les platanes, le préau où elle avait tant joué. Puis elle serra fort la main de sa maîtresse, qui avait les yeux brillants.',[
    ['Que se passe-t-il probablement ?','C’est le dernier jour d’Inès dans cette école.',['Inès arrive dans une nouvelle école.','Inès est punie.','La cour va être détruite.'],'Indices : « une dernière fois », « où elle avait tant joué » : elle quitte l’école.'],
    ['Que ressent la maîtresse ?','une vive émotion, au bord des larmes',['de la colère','de l’indifférence','de la peur'],'« les yeux brillants » suggère des larmes retenues.'],
    ['Pourquoi Inès range-t-elle « lentement » ses affaires ?','Elle n’a pas envie de partir.',['Elle est très fatiguée.','Elle a perdu un objet.','Elle ne sait pas ranger.'],'La lenteur montre qu’elle retarde le moment du départ.',2]]],
  ['Le facteur recula de deux pas. Derrière le portail, un énorme chien montrait les crocs. Le facteur glissa la lettre sous la grille, du bout des doigts, sans quitter l’animal des yeux.',[
    ['Que ressent le facteur ?','de la peur',['de la joie','de l’ennui','de la jalousie'],'Il recule et surveille le chien : ses gestes trahissent sa peur.'],
    ['Pourquoi glisse-t-il la lettre « du bout des doigts » ?','pour éviter d’approcher sa main du chien',['parce que la lettre est sale','parce qu’il a mal à la main','pour faire une blague'],'Il garde ses doigts le plus loin possible des crocs.',2],
    ['Dans le texte, « l’animal » désigne…','le chien',['le facteur','la lettre','le portail'],'C’est une reprise nominale du « énorme chien ».']]],
  ['Ce matin-là, Hugo enfila son écharpe, ses gants et son bonnet. Dehors, les toits étaient blancs et les enfants du quartier glissaient en riant sur le trottoir.',[
    ['En quelle saison se passe probablement la scène ?','en hiver',['en été','au printemps','on ne peut rien déduire'],'Écharpe, gants, bonnet et toits blancs : il fait froid et il a neigé.'],
    ['Pourquoi les toits sont-ils blancs ?','Il a neigé.',['Ils ont été repeints.','Il fait très chaud.','C’est la pleine lune.'],'Information implicite déduite du froid et des enfants qui glissent.'],
    ['Quelle information est explicite ?','Les enfants glissent sur le trottoir.',['Il a neigé pendant la nuit.','Hugo a froid aux mains.','L’école est fermée.'],'Cette action est écrite dans le texte.',2]]],
  ['Un renard s’approcha du poulailler. L’animal rusé tourna longtemps autour du grillage : il cherchait un passage. La fermière, qui l’avait aperçu, attrapa son balai.',[
    ['« L’animal rusé » désigne…','le renard',['la fermière','le poulailler','le grillage'],'C’est une reprise nominale de « un renard ».'],
    ['Dans « qui l’avait aperçu », le pronom « l’ » désigne…','le renard',['la fermière','le balai','le passage'],'La fermière a aperçu le renard.',2],
    ['Que va probablement faire la fermière ?','chasser le renard',['nourrir le renard','balayer la cour','fermer sa maison et dormir'],'Elle l’a vu et prend son balai : elle va le chasser.']]],
  ['Le pont était fermé à cause de la tempête. Les voyageurs durent donc attendre au village. Pourtant, un jeune berger traversa la rivière à gué, son agneau sur les épaules.',[
    ['Quel lien logique exprime « à cause de » ?','la cause',['la conséquence','l’opposition','le temps'],'« à cause de la tempête » explique pourquoi le pont est fermé.'],
    ['Quel lien logique exprime « donc » ?','la conséquence',['la cause','l’opposition','le lieu'],'Les voyageurs attendent : c’est la conséquence de la fermeture du pont.'],
    ['Quel lien logique exprime « Pourtant » ?','l’opposition',['la cause','la conséquence','l’addition'],'Le berger fait le contraire de ce qu’on attend : il traverse malgré tout.',2],
    ['Que peut-on déduire du berger ?','Il connaît bien la rivière et il est courageux.',['Il ne sait pas nager.','Il a peur de l’eau.','Il veut vendre son agneau.'],'Il traverse « à gué » malgré la tempête : il connaît un passage peu profond et ose le prendre.',3]]],
  ['Lucie relut sa copie trois fois avant de la rendre. À la sortie, elle sautillait dans le couloir en chantonnant.',[
    ['Comment Lucie pense-t-elle avoir réussi son contrôle ?','Elle pense l’avoir bien réussi.',['Elle pense l’avoir raté.','Elle n’a pas fait le contrôle.','Elle a oublié sa copie.'],'Indices : elle sautille et chantonne, signes de joie et de satisfaction.'],
    ['Que montre le fait qu’elle relise sa copie trois fois ?','qu’elle est sérieuse et appliquée',['qu’elle ne sait pas lire','qu’elle triche','qu’elle s’ennuie'],'Relire plusieurs fois montre le souci de bien faire.',2]]]]),5],
  [d=>{const I=[['Le facteur recula de deux pas.','Le facteur recule.','explicite'],['Le facteur recula de deux pas devant le chien qui grognait.','Le facteur a peur du chien.','implicite'],['Lina referma son parapluie mouillé.','Il pleut dehors.','implicite'],['Lina referma son parapluie mouillé.','Lina a un parapluie.','explicite'],['Tom bâilla trois fois pendant le film.','Tom s’ennuie ou il est fatigué.','implicite'],['Tom bâilla trois fois pendant le film.','Tom regarde un film.','explicite'],['Le gâteau sortit du four tout noir.','Le gâteau a trop cuit.','implicite'],['Le gâteau sortit du four tout noir.','Le gâteau est noir.','explicite'],['Mila serra son bulletin contre elle en souriant.','Mila est contente de ses résultats.','implicite'],['Le chien remuait la queue en voyant son maître.','Le chien est heureux de voir son maître.','implicite'],['Le chien remuait la queue en voyant son maître.','Le chien voit son maître.','explicite'],['Les rues étaient désertes et les volets fermés.','Les volets sont fermés.','explicite']];const [t,i,a]=P(I);
    const OK={explicite:'explicite : elle est écrite dans le texte',implicite:'implicite : on la déduit grâce aux indices'};
    return ch(`Texte : « ${t} »<br>L’information « ${i} » est…`,OK[a],[OK[a==='explicite'?'implicite':'explicite'],'fausse : le texte dit le contraire'],{expl:a==='explicite'?`« ${i} » reprend ce qui est écrit : information <b>explicite</b>.`:`Le texte ne le dit pas directement ; on le déduit des indices : information <b>implicite</b>.`,hint:'Peux-tu souligner cette information dans le texte ?'});},2],
  [bank([['Une information implicite est…','une information que l’on déduit grâce à des indices',['une information écrite en gras','une faute d’orthographe','le titre du texte'],'L’implicite n’est pas écrit : on le déduit en reliant des indices.'],
   ['Une information explicite est…','une information écrite directement dans le texte',['une information que l’on invente','une information cachée dans les images seulement','une information toujours fausse'],'Explicite = on peut la souligner dans le texte.'],
   ['Faire une inférence, c’est…','déduire une information non écrite à partir d’indices',['recopier une phrase du texte','compter les mots','résumer le titre'],'L’inférence relie les indices et ses connaissances.',2],
   ['« Il ouvrit son parapluie. » Quelle déduction est justifiée ?','Il pleut probablement.',['Il fait très chaud.','Il est malade.','Il a perdu son chapeau.'],'Le parapluie est l’indice d’une pluie.'],
   ['Laquelle de ces réponses est correctement justifiée ?','Le garçon a peur, car il « se cache sous sa couverture en tremblant ».',['Le garçon a peur, je le sens.','Le garçon a peur.','Le garçon a peur parce que j’aurais peur aussi.'],'Seule cette réponse s’appuie sur un indice précis du texte.',2]]),1])},

{id:'fr6c',name:'Lire documents, images et sources',icon:'📰',domain:'Lecture',
 refs:[REF+' — « Lire et comprendre des textes, des documents et des images pour apprendre dans toutes les disciplines » (identifier la nature et la source, documents composites, image fixe)',EX6],
 tip:'Avant d’interpréter un document, réponds à trois questions : qu’est-ce que c’est (nature) ? qui l’a produit et quand (source) ? que montre-t-il exactement ?',
 c:C(`Un article, une affiche, un graphique, une photographie : chaque jour, tu lis des documents très différents. Pour bien les comprendre, il faut savoir <b>d’où ils viennent</b>, <b>comment ils sont construits</b> et <b>relier</b> leurs différentes parties.`,
  [T('Nature et source',`<p>La <b>nature</b> d’un document, c’est son type : article de presse, affiche, photographie, carte, tableau, graphique, schéma, gravure, peinture, caricature…</p><p>La <b>source</b> indique d’où il vient : <b>auteur</b>, <b>date</b>, <b>lieu de publication</b> (journal, site, livre, musée). Elle permet de juger la fiabilité et de comprendre l’<b>intention</b> du document : informer, convaincre, faire rire, expliquer.</p>`),
   T('Lire un document composite',`<p>Un document <b>composite</b> associe plusieurs éléments : texte, image, tableau, légende. On lit dans l’ordre : <b>titre</b>, <b>chapeau</b> (court texte en gras sous le titre qui résume l’article), <b>intertitres</b>, <b>légendes</b> des images, <b>sources</b> des graphiques et <b>unités</b> des tableaux.</p><p>Il faut ensuite <b>relier</b> les informations : l’image illustre-t-elle le texte ? le tableau apporte-t-il une précision ? Deux documents peuvent être <b>convergents</b> (ils disent la même chose), <b>complémentaires</b> (l’un ajoute une information) ou <b>contradictoires</b>.</p>`),
   T('Lire une image fixe',`<p>On va de <b>ce qui est vu</b> à <b>ce qui est dit</b> par l’image. On décrit d’abord : le <b>premier plan</b> (le plus proche du spectateur), l’<b>arrière-plan</b>, les personnages, les couleurs, la lumière, le cadrage. Puis on interprète : quelle émotion ? quel message ?</p><p>La <b>légende</b> et le <b>crédit</b> (nom du photographe ou de l’agence) font partie du document : sans eux, on risque un contresens.</p>`)],
  [{q:'Une affiche comporte un slogan, une photographie et la mention « Ville de Lyon, mai 2024 ». Comment l’étudier ?',s:['Je l’identifie : c’est une affiche (nature).','Je relève la source : la Ville de Lyon, en mai 2024.','J’observe le lien entre le slogan et l’image.','J’en déduis l’intention : convaincre ou informer le public, puis j’interprète le message.']}],
  ['J’identifie la nature et la source du document (auteur, date, lieu de publication).','J’observe le titre, la légende, les unités et la construction de la page.','Je relève les informations utiles pour répondre à la question.','Je relie les éléments entre eux (texte, image, tableau) avant d’interpréter.'],
  ['Interpréter une image sans lire sa légende ni sa source.','Lire chaque élément séparément sans les relier.','Oublier les unités d’un tableau ou d’un graphique.'],
  ['Nature + source + date avant toute interprétation.','Un document composite se lit dans son ensemble : titre, chapeau, légendes, sources.','Comparer deux documents : convergents, complémentaires ou contradictoires.']),
 g:mix([d=>{const TH=P([['Nombre de livres empruntés au CDI du collège','livres',['septembre','octobre','novembre','décembre','janvier'],'CDI du collège, année 2025-2026'],['Nombre de visiteurs de l’exposition « Monstres et merveilles »','visiteurs',['lundi','mardi','mercredi','jeudi','vendredi'],'service culturel de la mairie, mars 2026'],['Nombre de repas végétariens servis à la cantine','repas',['semaine 1','semaine 2','semaine 3','semaine 4','semaine 5'],'service de restauration du collège, 2026']]);
    const [title,u,M,src]=TH;const v=pickN(Array.from({length:76},(_,k)=>k+20),5);
    const tab=`<table class="ptable"><tr><th colspan="5">${title}</th></tr><tr>${M.map(m=>`<th>${m}</th>`).join('')}</tr><tr>${v.map(x=>`<td>${x}</td>`).join('')}</tr></table><small>Source : ${src}.</small>`;
    const r=Math.random();
    if(r<.3){const mx=v.indexOf(Math.max(...v));return ch(`${tab}<br>Quel est le moment où le nombre de ${u} est le plus élevé ?`,M[mx],M.filter((_,k)=>k!==mx),{expl:`On compare les valeurs : le maximum est ${v[mx]} ${u}, en <b>${M[mx]}</b>.`,hint:'Cherche la plus grande valeur du tableau.'});}
    if(r<.55)return ch(`${tab}<br>Quelle est la source de ce tableau ?`,src,['un élève anonyme sur un réseau social','le titre du tableau','aucune source n’est indiquée'],{expl:`La source est écrite sous le tableau : <b>${src}</b>. Elle indique qui a produit les données.`,hint:'Regarde la petite ligne sous le tableau.'});
    const [a,b]=pickN([0,1,2,3,4],2);const hi=v[a]>v[b]?a:b,lo=hi===a?b:a;
    if(r<.85||d===1)return num(`${tab}<br>Combien de ${u} de plus en <b>${M[hi]}</b> qu’en <b>${M[lo]}</b> ?`,v[hi]-v[lo],{unit:u,expl:`${v[hi]} − ${v[lo]} = <b>${v[hi]-v[lo]} ${u}</b>.`,hint:'Fais une soustraction.'});
    const s=v.reduce((x,y)=>x+y,0);return num(`${tab}<br>Quel est le nombre total de ${u} sur les cinq périodes ?`,s,{unit:u,expl:`${v.join(' + ')} = <b>${s} ${u}</b>.`,hint:'Additionne toutes les valeurs.'});},3],
  [pairs([['un article de presse','un texte signé, publié dans un journal, avec un titre et souvent un chapeau'],['une caricature','un dessin qui exagère les traits d’une personne pour s’en moquer ou la critiquer'],['un schéma','un dessin simplifié avec des flèches et des légendes qui explique un fonctionnement'],['une carte','une représentation réduite d’un territoire, avec une légende et une échelle'],['un tableau de données','des informations chiffrées rangées en lignes et en colonnes'],['une affiche','une image imprimée avec un slogan, faite pour être placardée et vue de loin'],['une gravure','une image obtenue en creusant une plaque de bois ou de métal, puis imprimée'],['un graphique','un dessin (courbe, barres, secteurs) qui représente des données chiffrées']],{q:'Que désigne %s ?',rq:'Quelle est la nature de ce document : %s ?',hint:'Pense à la forme du document.'}),2],
  [pairs([['le titre','la phrase courte, en gros caractères, qui annonce le sujet'],['le chapeau','le court texte en gras sous le titre, qui résume l’article'],['la légende','le texte qui accompagne une image et explique ce qu’elle montre'],['la source','l’indication de l’origine du document : auteur, date, lieu de publication'],['le crédit photographique','le nom du photographe ou de l’agence qui a pris la photo'],['l’intertitre','un petit titre qui découpe un long article en parties'],['le premier plan','la partie de l’image la plus proche du spectateur'],['l’arrière-plan','la partie de l’image la plus éloignée du spectateur']],{q:'Dans un document, qu’appelle-t-on %s ?',rq:'Comment appelle-t-on %s ?'}),2],
  [bank([['Deux documents donnent la même information. Ils sont…','convergents',['contradictoires','complémentaires','illisibles'],'Convergents : ils vont dans le même sens.'],
   ['Un document ajoute une information absente de l’autre. Ils sont…','complémentaires',['contradictoires','identiques','convergents en tout point'],'Complémentaires : l’un complète l’autre.'],
   ['Deux témoignages affirment le contraire l’un de l’autre. Ils sont…','contradictoires',['convergents','complémentaires','identiques'],'Contradictoires : il faut alors vérifier les sources.',2],
   ['Une photographie sans légende montre une foule. Quel risque y a-t-il à l’interpréter ?','faire un contresens, car on ignore le lieu, la date et la raison du rassemblement',['aucun risque : une image dit toujours la vérité','la photo devient automatiquement un tableau','on ne peut jamais regarder une photo'],'La légende et la source donnent le contexte indispensable.',2],
   ['Pour savoir si un document est fiable, que faut-il regarder d’abord ?','sa source (auteur, date, média) et la croiser avec d’autres documents',['sa couleur','le nombre d’images','sa longueur'],'La source permet de juger le sérieux et l’intention du document.'],
   ['Une affiche de la mairie dit « Tous à vélo ! » avec la photo d’un enfant casqué. Quelle est son intention principale ?','convaincre les habitants d’utiliser le vélo',['raconter une histoire inventée','vendre des casques au plus offrant','expliquer le fonctionnement d’un moteur'],'Le slogan à l’impératif et l’image positive cherchent à convaincre.',2],
   ['Dans un graphique, pourquoi faut-il lire les unités ?','pour savoir ce que représentent les nombres (euros, kilomètres, élèves…)',['parce qu’elles sont décoratives','pour connaître la couleur des barres','pour trouver l’auteur'],'Sans unité, un nombre n’a pas de sens précis.'],
   ['Analyser une image, c’est aller…','de ce qui est vu à ce qui est dit (décrire, puis interpréter)',['directement à son avis personnel','du message à la description sans regarder','du titre au prix de l’image'],'On décrit avant d’interpréter.',3]]),2])},

/* ===================== CULTURE LITTÉRAIRE ET ARTISTIQUE ===================== */
{id:'fr6d',name:'Récits des origines : créer et recréer le monde',icon:'🌍',domain:'Culture littéraire et artistique',
 refs:[REF+' — entrée de 6e « Créer, recréer le monde : récits des origines (récit, fiction) »',EX6+' : La Genèse, L’Épopée de Gilgamesh, Ovide, Métamorphoses'],
 tip:'Pour un récit des origines, pose-toi deux questions : « Qu’est-ce que ce récit explique ? » et « Quelle valeur ou quelle leçon transmet-il ? »',
 c:C(`Pourquoi l’araignée tisse-t-elle sans cesse ? Pourquoi les hommes parlent-ils des langues différentes ? Bien avant la science, les peuples ont inventé des <b>récits des origines</b> pour donner un sens au monde. Ils se transmettent depuis des millénaires.`,
  [T('Mythes et textes fondateurs',`<p>Un <b>mythe</b> est un récit traditionnel, d’abord transmis oralement, qui met en scène des dieux, des héros ou des êtres surnaturels. Un récit qui raconte la <b>naissance du monde</b> s’appelle une <b>cosmogonie</b> ; un récit qui explique l’origine d’une chose (un animal, une plante, un phénomène) est un récit <b>étiologique</b> (du grec <i>aitia</i>, « la cause »).</p><p>Un <b>texte fondateur</b> transmet les croyances et les valeurs d’un peuple. Ces récits ne sont pas des explications scientifiques : ils parlent par <b>symboles</b> et par images.</p>`),
   T('Trois grands textes',`<ul class="lst"><li><b>La Genèse</b>, premier livre de la Bible : Dieu crée le monde en six jours et se repose le septième ; Adam et Ève vivent dans le jardin d’Éden ; Noé construit une arche pour échapper au déluge ; la colombe revient avec un rameau d’olivier ; l’arc-en-ciel est le signe de l’alliance ; la tour de Babel explique la diversité des langues. « Au commencement, Dieu créa les cieux et la terre. » (trad. Louis Segond, 1910)</li><li><b>L’Épopée de Gilgamesh</b> (Mésopotamie) : l’un des plus anciens récits écrits, sur des tablettes d’argile en écriture cunéiforme. Gilgamesh, roi d’Uruk, perd son ami Enkidu et part en quête de l’immortalité ; Utanapishti lui raconte un déluge.</li><li><b>Les Métamorphoses</b> d’<b>Ovide</b>, poète latin (début du Ier siècle) : quinze livres de récits de transformations, de la création du monde à l’époque d’Ovide.</li></ul>`),
   T('Les métamorphoses d’Ovide',`<table class="ptable"><tr><th>Personnage</th><th>Devient</th><th>Pourquoi</th></tr><tr><td>Daphné</td><td>un laurier</td><td>elle fuit Apollon</td></tr><tr><td>Arachné</td><td>une araignée</td><td>elle a défié Minerve au tissage</td></tr><tr><td>Narcisse</td><td>une fleur</td><td>il est tombé amoureux de son reflet</td></tr><tr><td>Écho</td><td>une simple voix</td><td>elle ne peut que répéter les derniers mots</td></tr><tr><td>Lycaon</td><td>un loup</td><td>roi cruel puni par Jupiter</td></tr><tr><td>Philémon et Baucis</td><td>un chêne et un tilleul</td><td>vieux couple hospitalier récompensé</td></tr></table><p>Après le déluge, <b>Deucalion et Pyrrha</b> jettent des pierres derrière eux : elles deviennent des hommes et des femmes. Dans la mythologie grecque, <b>Prométhée</b> vole le feu aux dieux pour le donner aux hommes ; il est puni, enchaîné sur un rocher.</p>`)],
  [{q:'Comparer le déluge de la Genèse et celui d’Ovide (Deucalion et Pyrrha).',s:['Point commun : une divinité punit les hommes par une immense inondation.','Point commun : un couple ou une famille de justes est épargné (Noé et les siens ; Deucalion et Pyrrha).','Différence : Noé construit une arche et sauve les animaux ; Deucalion et Pyrrha recréent l’humanité avec des pierres.','Conclusion : ces récits transmettent une même idée, la renaissance d’un monde purifié.']}],
  ['Je repère ce que le récit explique (le monde, les humains, un animal, un phénomène).','J’identifie les personnages ou les forces créatrices (dieux, héros, éléments).','Je relève les symboles (lumière, eau, arbre, transformation) et je les interprète.','Je compare avec d’autres récits : ressemblances, différences, valeurs transmises.'],
  ['Confondre un récit fondateur avec une explication scientifique moderne.','Croire qu’un mythe appartient à une seule culture : on trouve des récits de déluge en Mésopotamie, dans la Bible et chez Ovide.','Oublier qu’Ovide écrit en latin : ses dieux portent des noms latins (Jupiter, Minerve).'],
  ['Mythe des origines = récit symbolique qui donne du sens au monde.','Récit étiologique = récit qui explique l’origine d’une chose.','Genèse, Gilgamesh, Métamorphoses d’Ovide : des textes à comparer.']),
 g:mix([pairs([['Daphné','un laurier'],['Arachné','une araignée'],['Narcisse','une fleur'],['Lycaon','un loup'],['Écho','une simple voix qui répète'],['Philémon et Baucis','un chêne et un tilleul']],{q:'Dans <i>Les Métamorphoses</i> d’Ovide, en quoi est transformé(e) %s ?',rq:'Dans <i>Les Métamorphoses</i> d’Ovide, qui (ou quoi) est transformé en %s ?',e:(a,b)=>`Chez Ovide, ${a} → ${b}. Le récit explique l’origine de cette chose : c’est un récit étiologique.`}),3],
  [seq(['la lumière, séparée des ténèbres','le ciel (le firmament), qui sépare les eaux','la terre sèche, les mers et les plantes','le soleil, la lune et les étoiles','les poissons et les oiseaux','les animaux terrestres et les humains','le repos'],{nq:'Dans le récit de la création de la Genèse, qu’est-ce qui vient juste après « %s » ?',pq:'Dans le récit de la création de la Genèse, qu’est-ce qui vient juste avant « %s » ?',oq:'Remets dans l’ordre ces étapes de la création selon la Genèse :'}),2],
  [bank([['Un récit qui explique l’origine d’une chose (un animal, une plante, un phénomène) est un récit…','étiologique',['policier','autobiographique','documentaire'],'Du grec aitia, « la cause » : le récit explique pourquoi une chose existe.'],
   ['Comment appelle-t-on un récit qui raconte la naissance du monde ?','une cosmogonie',['une fable','une biographie','une tirade'],'Cosmogonie : du grec kosmos (« monde ») et gonos (« naissance »).',2],
   ['La Genèse est…','le premier livre de la Bible',['un poème d’Ovide','une épopée mésopotamienne','une pièce de Molière'],'La Genèse ouvre la Bible ; elle raconte la création du monde et les premiers temps de l’humanité.'],
   ['Dans la Genèse, qui construit une arche pour échapper au déluge ?','Noé',['Adam','Gilgamesh','Prométhée'],'Noé embarque sa famille et un couple de chaque espèce animale.'],
   ['Dans la Genèse, que rapporte la colombe à Noé ?','un rameau d’olivier',['une pomme','une pierre','une plume d’aigle'],'Le rameau montre que les eaux ont baissé : la terre redevient habitable.'],
   ['Dans la Genèse, quel est le signe de l’alliance entre Dieu et les hommes après le déluge ?','l’arc-en-ciel',['une étoile filante','un volcan','une tour'],'L’arc-en-ciel est le signe de la promesse de ne plus détruire la terre par un déluge.'],
   ['Que cherche à expliquer le récit de la tour de Babel ?','la diversité des langues humaines',['la naissance des étoiles','l’origine du feu','la couleur des oiseaux'],'Les hommes ne se comprennent plus et se dispersent sur la terre.',2],
   ['Que fait Dieu le septième jour, selon la Genèse ?','il se repose',['il crée les humains','il crée la lumière','il provoque le déluge'],'Les humains sont créés le sixième jour ; le septième est un jour de repos.'],
   ['De quel pays ancien vient L’Épopée de Gilgamesh ?','la Mésopotamie',['la Grèce','l’Égypte','la Gaule'],'La Mésopotamie (actuel Irak) : le récit est gravé sur des tablettes d’argile.'],
   ['Sur quel support L’Épopée de Gilgamesh a-t-elle été retrouvée ?','des tablettes d’argile en écriture cunéiforme',['des rouleaux de papier imprimé','des parchemins enluminés','des murs de cathédrale'],'L’écriture cunéiforme est formée de petits traits en forme de clous.',2],
   ['Que cherche Gilgamesh après la mort de son ami Enkidu ?','l’immortalité',['un trésor caché','une épouse','un royaume perdu'],'Bouleversé par la mort d’Enkidu, il veut échapper à la mort.',2],
   ['Ovide était…','un poète latin du début du Ier siècle',['un roi de Mésopotamie','un auteur grec de théâtre','un conteur français du XVIIe siècle'],'Ovide (43 av. J.-C. – vers 17 apr. J.-C.) a écrit Les Métamorphoses en latin.'],
   ['Chez Ovide, après le déluge, que deviennent les pierres jetées par Deucalion et Pyrrha ?','des hommes et des femmes',['des arbres','des oiseaux','des montagnes'],'Le récit explique la naissance d’une nouvelle humanité.',2],
   ['Dans la mythologie grecque, que vole Prométhée pour le donner aux hommes ?','le feu',['l’eau','la parole','la lumière du soleil'],'Il est puni par Zeus : enchaîné sur un rocher, un aigle lui dévore le foie.'],
   ['Pourquoi Arachné est-elle changée en araignée ?','Elle a défié la déesse Minerve dans un concours de tissage.',['Elle a volé le feu.','Elle a fui Apollon.','Elle aimait son reflet.'],'Sa punition explique pourquoi l’araignée tisse sans fin.',2],
   ['Pourquoi Philémon et Baucis sont-ils récompensés ?','Ils ont accueilli des dieux déguisés en voyageurs alors que les autres les chassaient.',['Ils ont gagné une course.','Ils ont tué un monstre.','Ils ont bâti une tour.'],'Le récit valorise l’hospitalité : leur maison devient un temple et ils deviennent deux arbres.',3],
   ['Dans un récit des origines, la lumière qui sort des ténèbres symbolise souvent…','le passage du désordre à l’ordre, du néant à la vie',['une panne d’électricité','une saison précise','la fin du monde'],'Le récit parle par symboles, pas par explications scientifiques.',3],
   ['Pourquoi trouve-t-on des récits de déluge dans plusieurs cultures (Mésopotamie, Bible, Ovide) ?','Ces récits partagent des thèmes universels : la punition, la survie des justes, la renaissance du monde.',['C’est une seule et même histoire écrite par Ovide.','Ce sont des comptes rendus scientifiques.','Ils ont tous été écrits au XXe siècle.'],'Comparer les récits fait apparaître des ressemblances et des valeurs communes.',3],
   ['Un mythe est-il une explication scientifique du monde ?','Non, c’est un récit symbolique qui donne un sens au monde.',['Oui, il remplace la science.','Oui, s’il est très ancien.','Non, c’est un mode d’emploi.'],'Le mythe transmet des croyances et des valeurs, il ne démontre pas.']]),3])},

{id:'fr6e',name:'Poésie : chanter et enchanter le monde',icon:'🎵',domain:'Culture littéraire et artistique',
 refs:[REF+' — entrée de 6e « Chanter et enchanter le monde : mots et merveilles (poésie) »',EX6],
 tip:'Pour une figure de style, cherche l’outil de comparaison (comme, tel, pareil à…) : s’il y en a un, c’est une comparaison ; sinon, c’est peut-être une métaphore.',
 c:C(`« Il pleure dans mon cœur / Comme il pleut sur la ville » : en deux vers, Verlaine fait entendre la pluie et la tristesse. La poésie joue avec les <b>sons</b>, le <b>rythme</b> et les <b>images</b> pour nous faire voir le monde autrement.`,
  [T('La forme du poème',`<p>Un poème est souvent écrit en <b>vers</b> (une ligne du poème), regroupés en <b>strophes</b> : distique (2 vers), tercet (3), quatrain (4). Les vers se mesurent en <b>syllabes</b> : l’<b>alexandrin</b> a 12 syllabes, le <b>décasyllabe</b> 10, l’<b>octosyllabe</b> 8. Le « e » en fin de mot ne se prononce pas devant une voyelle ni en fin de vers.</p><p>La <b>rime</b> est le retour d’un même son en fin de vers. Disposition : rimes <b>suivies</b> (AABB), <b>croisées</b> (ABAB), <b>embrassées</b> (ABBA). Il existe aussi des poèmes en <b>vers libres</b>, en <b>prose</b>, des <b>calligrammes</b> (Apollinaire) et des <b>haïkus</b> japonais (trois vers brefs, Bashō au XVIIe siècle).</p>`),
   T('Les jeux de sons',`<p>L’<b>allitération</b> répète une consonne : « Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine, <i>Andromaque</i>) — on entend le sifflement des serpents.</p><p>L’<b>assonance</b> répète une voyelle : « Les sanglots longs / Des violons / De l’automne » (Verlaine) — le son « on » donne une impression de plainte.</p><p>L’<b>anaphore</b> répète un mot ou un groupe en début de vers ou de phrase ; le <b>refrain</b> répète un vers entier.</p>`),
   T('Les images poétiques',`<ul class="lst"><li><b>Comparaison</b> : deux éléments rapprochés par un <b>outil</b> (comme, tel, pareil à, semblable à, ressembler à). « Le Poète est semblable au prince des nuées » (Baudelaire).</li><li><b>Métaphore</b> : rapprochement <b>sans outil</b>. « La lune est une lampe suspendue au ciel. »</li><li><b>Personnification</b> : une chose ou un animal reçoit des traits humains. « C’est un trou de verdure où chante une rivière » (Rimbaud).</li><li><b>Énumération</b> : une liste de mots qui crée un effet d’abondance.</li></ul><p>Repérer une figure ne suffit pas : il faut dire <b>quel effet</b> elle produit.</p>`)],
  [{q:'Analyse : « Il pleure dans mon cœur / Comme il pleut sur la ville » (Verlaine, Romances sans paroles, 1874).',s:['Chaque vers compte 6 syllabes : Il / pleu / re / dans / mon / cœur.','« Comme » est un outil de comparaison : la tristesse du poète est comparée à la pluie.','Les sons « pleure » / « pleut » se répondent : on entend la pluie dans les mots.','Effet : la mélancolie paraît aussi grise et continue qu’une pluie sur la ville.']}],
  ['Je lis le poème à voix haute pour entendre les sons et le rythme.','J’observe la forme : vers, strophes, mesure, rimes.','Je repère les images (comparaison, métaphore, personnification) et les jeux de sons.','J’explique l’effet produit : quelle émotion, quelle vision du monde ?'],
  ['Prendre une comparaison pour une métaphore : s’il y a « comme », c’est une comparaison.','Compter le « e » final d’un mot placé devant une voyelle (« l’aube, à » se lit « l’au-bà »).','Se contenter de nommer une figure sans expliquer son effet.'],
  ['Poésie = sons + rythme + images.','Rimes suivies AABB, croisées ABAB, embrassées ABBA ; alexandrin = 12 syllabes.','Comparaison (avec outil), métaphore (sans outil), personnification (traits humains).']),
 g:mix([d=>{const F={'age':['nuage','voyage','rivage','plage','visage','orage'],'oir':['soir','miroir','espoir','noir','savoir'],'eau':['oiseau','ruisseau','roseau','bateau','château'],'on':['chanson','maison','buisson','frisson','saison'],'ière':['rivière','lumière','prière','clairière','bruyère'],'eur':['fleur','couleur','douceur','chaleur','bonheur']};
    const [a,b]=pickN(Object.keys(F),2);const A=pickN(F[a],2),B=pickN(F[b],2);
    const S=P([['rimes suivies','AABB',[A[0],A[1],B[0],B[1]]],['rimes croisées','ABAB',[A[0],B[0],A[1],B[1]]],['rimes embrassées','ABBA',[A[0],B[0],B[1],A[1]]]]);
    return ch(`Voici les mots placés à la fin des quatre vers d’un quatrain : « ${S[2].join(' / ')} ». Comment sont disposées les rimes ?`,S[0],['rimes suivies','rimes croisées','rimes embrassées','vers sans rimes'].filter(x=>x!==S[0]),{expl:`Les sons se répondent selon le schéma <b>${S[1]}</b> : ce sont des <b>${S[0]}</b>.`,hint:'Donne la lettre A au premier son, B au second, puis lis le schéma.'});},3],
  [bank([['« Pour qui sont ces serpents qui sifflent sur vos têtes ? » (Racine). Quel procédé reconnais-tu ?','une allitération en « s »',['une assonance en « i »','une comparaison','une personnification'],'La consonne « s » est répétée : on entend le sifflement des serpents.'],
   ['« Les sanglots longs / Des violons / De l’automne » (Verlaine). Quel son domine ?','le son « on » (assonance)',['le son « r » (allitération)','le son « i »','aucun son ne se répète'],'Sanglots, longs, violons : l’assonance en « on » imite une plainte.',2],
   ['« Le Poète est semblable au prince des nuées » (Baudelaire). Quelle figure de style ?','une comparaison',['une métaphore','une allitération','une énumération'],'« semblable à » est un outil de comparaison.'],
   ['« C’est un trou de verdure où chante une rivière » (Rimbaud). Quelle figure de style ?','une personnification',['une comparaison','une allitération','une énumération'],'La rivière « chante » comme une personne.'],
   ['« La lune est une lampe suspendue au ciel. » Quelle figure de style ?','une métaphore',['une comparaison','une personnification','une allitération'],'La lune est assimilée à une lampe sans outil de comparaison.'],
   ['« Ses yeux brillaient comme deux étoiles. » Quelle figure de style ?','une comparaison',['une métaphore','une personnification','une anaphore'],'L’outil « comme » relie les yeux et les étoiles.'],
   ['« Le vent hurle et frappe aux volets. » Quelle figure de style ?','une personnification',['une comparaison','une assonance','une énumération'],'Le vent agit comme un être humain en colère.'],
   ['« La mer est un miroir immense. » Quelle figure de style ?','une métaphore',['une comparaison','une personnification','une allitération'],'Pas d’outil de comparaison : c’est une métaphore.'],
   ['« Tes cheveux, tel un fleuve noir, coulent sur tes épaules. » Quel est l’outil de comparaison ?','tel',['tes','coulent','sur'],'« tel » est un outil de comparaison, comme « comme » ou « pareil à ».',2],
   ['« Il y avait des roses, des lilas, des iris, des tulipes et des jonquilles. » Quel procédé ?','une énumération',['une métaphore','une personnification','une comparaison'],'La liste crée une impression d’abondance.'],
   ['« Le soleil s’endort derrière la colline. » Quelle figure de style ?','une personnification',['une comparaison','une énumération','une allitération'],'Le soleil « s’endort » comme une personne.'],
   ['Dans « Ô forêt, je t’aime ! Ô forêt, tu me consoles ! », la répétition de « Ô forêt » en début de phrase est…','une anaphore',['une rime','une métaphore','une comparaison'],'L’anaphore répète un mot ou un groupe en tête de phrase ou de vers.',2],
   ['« Demain, dès l’aube, à l’heure où blanchit la campagne » (Hugo). Combien de syllabes compte ce vers ?','12',['10','11','13'],'De/main/dès/l’au/b(e)‿à/l’heu/r(e)‿où/blan/chit/la/cam/pagne : 12 syllabes, c’est un alexandrin (les « e » devant voyelle et en fin de vers ne comptent pas).',3],
   ['« Maître Corbeau, sur un arbre perché, » (La Fontaine). Combien de syllabes compte ce vers ?','10',['8','12','9'],'Maî/tre/Cor/beau/sur/un/ar/bre/per/ché : 10 syllabes (le « e » de « arbre » se prononce devant une consonne).',3],
   ['« Il pleure dans mon cœur » (Verlaine). Combien de syllabes ?','6',['5','7','8'],'Il/pleu/re/dans/mon/cœur : le « e » de « pleure » se prononce devant la consonne « d ».',3],
   ['Une strophe de quatre vers s’appelle…','un quatrain',['un tercet','un distique','un sizain'],'Quatrain = 4 vers ; tercet = 3 ; distique = 2.'],
   ['Un vers de douze syllabes s’appelle…','un alexandrin',['un octosyllabe','un décasyllabe','un haïku'],'L’alexandrin est le vers le plus célèbre de la poésie française.'],
   ['Un poème dont les vers dessinent la forme de ce dont il parle est…','un calligramme',['un haïku','un sonnet','une fable'],'Apollinaire a publié un recueil intitulé Calligrammes (1918).',2],
   ['Un haïku est…','un très court poème japonais de trois vers, souvent tourné vers la nature et l’instant',['une longue épopée grecque','une pièce de théâtre comique','un conte de fées'],'Bashō (XVIIe siècle) est le maître le plus célèbre du haïku.',2],
   ['Quel effet produit l’allitération en « s » dans le vers de Racine sur les serpents ?','elle fait entendre le sifflement des serpents et rend la scène inquiétante',['elle rend le vers comique','elle supprime le rythme','elle n’a aucun effet'],'Le son imite ce qui est décrit : c’est une harmonie imitative.',3]]),4],
  [pairs([['Victor Hugo','Les Contemplations'],['Paul Verlaine','Romances sans paroles'],['Charles Baudelaire','Les Fleurs du mal'],['Jean de La Fontaine','Fables'],['Guillaume Apollinaire','Calligrammes'],['Jacques Prévert','Paroles'],['Robert Desnos','Chantefables et Chantefleurs'],['Arthur Rimbaud','Le Dormeur du val']],{q:'Quelle œuvre poétique a été écrite par %s ?',rq:'Qui est l’auteur de l’œuvre poétique intitulée « %s » ?'}),2])},

{id:'fr6f',name:'Théâtre : ruses, jeu et mise en scène',icon:'🎭',domain:'Culture littéraire et artistique',
 refs:[REF+' — entrée de 6e « Se masquer, jouer, déjouer : ruses en action (théâtre) »',EX6+' : Molière, Le Médecin malgré lui, Le Médecin volant'],
 tip:'Au théâtre, demande-toi toujours : « Qui parle ? À qui ? Et que sait le public que le personnage ignore ? »',
 c:C(`Un valet se déguise en médecin, un mari battu se venge, un jeune homme cache une pendule cassée… Au théâtre, la <b>ruse</b> fait avancer l’action et fait rire. Mais un texte de théâtre est d’abord écrit pour être <b>joué</b> devant un public.`,
  [T('Le texte de théâtre',`<p>Le texte se compose de <b>répliques</b> (les paroles des personnages, précédées de leur nom) et de <b>didascalies</b> (indications de jeu, souvent en italique : gestes, ton, décor, entrées et sorties), qui ne sont pas prononcées.</p><p>La pièce est découpée en <b>actes</b> et en <b>scènes</b> : une nouvelle scène commence quand un personnage entre ou sort. Une <b>tirade</b> est une longue réplique ; un <b>monologue</b> est prononcé par un personnage seul en scène ; un <b>aparté</b> est dit « à part » : le public l’entend, mais pas les autres personnages.</p><p>C’est la <b>double énonciation</b> : un personnage parle à un autre, mais toujours aussi au public.</p>`),
   T('La ruse et le comique',`<p>La ruse repose sur le décalage entre l’<b>être</b> et le <b>paraître</b> : déguisement, mensonge, fausse identité. Elle provoque souvent un <b>quiproquo</b> (un personnage prend une chose ou une personne pour une autre) et des <b>coups de théâtre</b>.</p><p>Les formes du comique : comique de <b>gestes</b> (coups de bâton, chutes), de <b>mots</b> (jeux de mots, faux latin), de <b>situation</b> (quiproquo, personnage caché), de <b>caractère</b> (un avare, un vantard), de <b>répétition</b>.</p>`),
   T('Molière et ses farces',`<p><b>Molière</b> (Jean-Baptiste Poquelin, 1622-1673) est auteur, comédien et chef de troupe.</p><ul class="lst"><li><i>Le Médecin malgré lui</i> (1666) : pour se venger de son mari Sganarelle, un bûcheron, Martine fait croire qu’il est un grand médecin… qui n’avoue son talent qu’après des coups de bâton. Sganarelle « soigne » Lucinde, qui fait semblant d’être muette, et lance : « Et voilà justement ce qui fait que votre fille est muette. »</li><li><i>Le Médecin volant</i> : le valet Sganarelle se déguise en médecin pour aider son maître.</li><li><i>Les Fourberies de Scapin</i> (1671) : le valet Scapin trompe Géronte, qui répète « Que diable allait-il faire dans cette galère ? », puis le fait cacher dans un sac pour le bastonner.</li></ul><p>La <b>mise en scène</b> (décor, costumes, lumières, jeu des comédiens) est choisie par le <b>metteur en scène</b>. Vu de la salle, le <b>côté jardin</b> est à gauche et le <b>côté cour</b> à droite.</p>`)],
  [{q:'LÉON, <i>à part</i> : Si mon oncle découvre la pendule cassée, je suis perdu… L’ONCLE, <i>entrant</i> : Léon ! Quel est ce bruit ? LÉON, <i>se plaçant devant la pendule</i> : Quel bruit, mon oncle ? Je répétais ma leçon… de musique ! Analyse la ruse.',s:['« à part » signale un aparté : seul le public entend que la pendule est cassée.','La didascalie « se plaçant devant la pendule » montre la ruse par le geste : Léon cache l’objet.','Léon invente une excuse (une leçon de musique) : il ment pour se tirer d’affaire.','Le public en sait plus que l’oncle : ce décalage crée le comique de situation.']}],
  ['Je repère qui parle et à qui (noms des personnages, apartés).','Je lis les didascalies : elles guident les gestes, le ton et les déplacements.','Je cherche ce que le public sait et que certains personnages ignorent.','J’identifie le type de comique et l’effet de la ruse sur l’action.'],
  ['Lire les didascalies comme si un personnage les prononçait.','Confondre monologue (personnage seul en scène) et tirade (longue réplique devant d’autres personnages).','Oublier que le texte de théâtre est écrit pour être joué : il faut imaginer la scène.'],
  ['Répliques = paroles ; didascalies = indications de jeu.','Aparté : entendu du public seulement ; quiproquo : malentendu.','La ruse joue sur l’être et le paraître ; Molière en a fait le cœur de ses farces.']),
 g:mix([pairs([['une réplique','les paroles prononcées par un personnage'],['une didascalie','une indication de jeu, de décor ou de ton qui n’est pas prononcée'],['une tirade','une longue réplique dite devant d’autres personnages'],['un monologue','les paroles d’un personnage seul en scène'],['un aparté','une réplique que le public entend mais pas les autres personnages'],['un quiproquo','un malentendu : un personnage prend une chose ou une personne pour une autre'],['un coup de théâtre','un événement inattendu qui change brusquement la situation'],['une scène','une partie de la pièce délimitée par l’entrée ou la sortie d’un personnage'],['le dénouement','la fin de la pièce, où les problèmes sont résolus'],['le metteur en scène','la personne qui dirige les comédiens et choisit décor, costumes et lumières']],{q:'Au théâtre, que désigne %s ?',rq:'Au théâtre, comment appelle-t-on %s ?'}),3],
  [sort({'comique de gestes':['des coups de bâton','une chute dans l’escalier','une course-poursuite autour de la table'],'comique de mots':['un faux latin inventé par un faux médecin','un jeu de mots sur un nom','une insulte absurde et inventée'],'comique de situation':['un personnage caché dans un sac','un quiproquo sur l’identité d’un médecin','un valet déguisé en son maître'],'comique de répétition':['une même réplique répétée plusieurs fois','un personnage qui pose sans cesse la même question']},{q:'« %s » relève surtout du…',e:(x,c)=>`« ${x} » : ${c}.`}),2],
  [bank([['Qui a écrit Le Médecin malgré lui ?','Molière',['Jean de La Fontaine','Charles Perrault','Victor Hugo'],'Molière, en 1666.'],
   ['Quel est le vrai métier de Sganarelle dans Le Médecin malgré lui ?','bûcheron (fagotier)',['médecin','valet de chambre','marchand'],'Il coupe du bois ; on le fait passer pour médecin.'],
   ['Dans Le Médecin malgré lui, pourquoi Martine fait-elle passer son mari pour un médecin ?','pour se venger de lui, car il l’a battue',['pour qu’il devienne riche','parce qu’il est vraiment médecin','pour sauver un enfant malade'],'Sa vengeance lance toute l’intrigue.',2],
   ['Selon Martine, comment obliger Sganarelle à avouer qu’il est médecin ?','en lui donnant des coups de bâton',['en lui offrant de l’argent','en le suppliant','en l’enfermant'],'Retournement comique : celui qui battait sa femme est battu à son tour.',2],
   ['Dans Le Médecin malgré lui, Lucinde fait semblant…','d’être muette',['d’être aveugle','d’être morte','d’être un homme'],'Elle feint d’être muette pour ne pas épouser l’homme choisi par son père.',2],
   ['« Que diable allait-il faire dans cette galère ? » est une réplique célèbre de…','Les Fourberies de Scapin',['Le Médecin malgré lui','Le Petit Chaperon rouge','L’Odyssée'],'Géronte la répète plusieurs fois : comique de répétition.',2],
   ['Dans Les Fourberies de Scapin, où Scapin fait-il cacher Géronte pour le bastonner ?','dans un sac',['dans une armoire','sous un lit','dans un tonneau'],'La scène du sac est un célèbre comique de gestes et de situation.',3],
   ['Molière s’appelait en réalité…','Jean-Baptiste Poquelin',['Jean de La Fontaine','Pierre Corneille','Charles Perrault'],'Molière est son nom de théâtre.'],
   ['Vu depuis la salle, le côté cour est…','à droite de la scène',['à gauche de la scène','au fond de la scène','sous la scène'],'Vu de la salle : jardin à gauche, cour à droite.',3],
   ['Comment reconnaît-on une didascalie dans un texte de théâtre ?','Elle est souvent en italique et n’est pas prononcée par les comédiens.',['Elle est toujours en majuscules et chantée.','Elle se trouve uniquement à la fin de la pièce.','Elle est dite par le souffleur.'],'Les didascalies guident le jeu et la mise en scène.'],
   ['Qu’est-ce que la double énonciation ?','Le personnage parle aux autres personnages et, en même temps, au public.',['Deux personnages parlent en même temps.','Un comédien joue deux rôles.','Le texte est écrit deux fois.'],'Le public reçoit toujours les paroles, même celles qui ne lui sont pas adressées.',3]]),3],
  [onText([['LÉON, <i>à part</i>. — Si mon oncle découvre la pendule cassée, je suis perdu…<br>L’ONCLE, <i>entrant</i>. — Léon ! Quel est ce bruit ?<br>LÉON, <i>se plaçant devant la pendule</i>. — Quel bruit, mon oncle ? Je répétais ma leçon… de musique !<br>L’ONCLE. — De musique ? Toi qui chantes comme une casserole ?',[
    ['Quel passage est une didascalie ?','« se plaçant devant la pendule »',['« Quel bruit, mon oncle ? »','« Léon ! »','« Toi qui chantes comme une casserole ? »'],'Ce passage en italique indique un geste ; il n’est pas prononcé.'],
    ['Que signifie l’indication « à part » ?','La réplique est un aparté : l’oncle ne l’entend pas, seul le public l’entend.',['Léon parle à son oncle.','Léon sort de scène.','Léon chante.'],'L’aparté met le public dans la confidence.'],
    ['Quelle est la ruse de Léon ?','Il cache la pendule et invente une excuse.',['Il avoue tout à son oncle.','Il répare la pendule.','Il s’enfuit par la fenêtre.'],'Il ment (« ma leçon de musique ») et se place devant l’objet cassé.',2],
    ['« Toi qui chantes comme une casserole ? » relève surtout du…','comique de mots',['comique de gestes','tragique','comique de répétition'],'La comparaison moqueuse fait rire par les mots.',2],
    ['Pourquoi le public rit-il de cette scène ?','Il sait que la pendule est cassée alors que l’oncle l’ignore.',['Parce que l’oncle tombe.','Parce que la pièce est triste.','Parce que Léon chante très bien.'],'Le décalage entre ce que sait le public et ce que sait le personnage crée le comique de situation.',3]]]]),2])},

{id:'fr6g',name:'Partir à l’aventure : récit et héros',icon:'🧭',domain:'Culture littéraire et artistique',
 refs:[REF+' — entrée de 6e « Partir à l’aventure ! (récit, fiction) »',EX6+' : Stevenson, L’Île au trésor ; Jack London ; Michel Tournier…'],
 tip:'Pour analyser un récit d’aventure, repère trois moments : le départ (pourquoi part-on ?), l’épreuve (quel obstacle ?) et le retour (qu’est-ce qui a changé chez le héros ?).',
 c:C(`Une carte au trésor trouvée dans un vieux coffre, un naufrage sur une île déserte, un pari fou pour faire le tour du monde : l’aventure commence quand le héros <b>quitte son monde familier</b>. Mais qu’est-ce qui fait un vrai récit d’aventure ?`,
  [T('Les ingrédients de l’aventure',`<p>Le récit d’aventure raconte un <b>départ</b> vers l’inconnu (mer, île, jungle, désert, Grand Nord), une suite d’<b>épreuves</b> et de dangers, des rencontres avec des <b>alliés</b> (adjuvants) et des <b>ennemis</b> (opposants), puis souvent un <b>retour</b>. Le héros ou l’héroïne en sort <b>transformé</b> : plus courageux, plus sage, plus libre.</p><p>Le suspense naît de l’incertitude : le héros va-t-il réussir ?</p>`),
   T('Le schéma narratif et le rythme',`<p><b>Schéma narratif</b> : situation initiale → élément perturbateur (ou déclencheur) → péripéties → élément de résolution → situation finale.</p><p>Le <b>rythme</b> varie : une <b>scène</b> (dialogue, action détaillée) ralentit le récit ; un <b>sommaire</b> résume beaucoup de temps en peu de mots (« Pendant des semaines, ils naviguèrent ») ; une <b>ellipse</b> saute une période (« Trois ans plus tard… ») ; une <b>pause</b> descriptive arrête l’action.</p>`),
   T('Des œuvres à connaître',`<ul class="lst"><li>Robert Louis Stevenson, <i>L’Île au trésor</i> (1883) : Jim Hawkins, le pirate Long John Silver, la carte du capitaine Flint.</li><li>Jules Verne, <i>Le Tour du monde en quatre-vingts jours</i> (1872 ; Phileas Fogg et Passepartout) et <i>Vingt mille lieues sous les mers</i> (le capitaine Nemo et le Nautilus).</li><li>Daniel Defoe, <i>Robinson Crusoé</i> (1719) ; Michel Tournier, <i>Vendredi ou la vie sauvage</i> (1971).</li><li>Jack London, <i>L’Appel de la forêt</i> (1903 : le chien Buck dans le Grand Nord) ; Mark Twain, <i>Les Aventures de Tom Sawyer</i> (1876) ; Joseph Kessel, <i>Le Lion</i> (1958).</li><li>Les voyages de Sindbad le marin, dans <i>Les Mille et Une Nuits</i>.</li></ul>`)],
  [{q:'Place les étapes : Tom vit chez sa tante au bord de la mer ; il trouve une vieille carte ; il affronte une tempête ; une jeune pêcheuse l’aide à trouver le coffre ; de retour, il rêve d’un nouveau voyage.',s:['Situation initiale : Tom vit tranquillement chez sa tante.','Élément perturbateur : la découverte de la carte lance l’aventure.','Péripéties : la tempête et les dangers du voyage.','Élément de résolution : grâce à la pêcheuse, il trouve le coffre ; situation finale : Tom a changé, il rêve d’un nouveau voyage.']}],
  ['Je repère la situation de départ et la raison du départ.','J’identifie les épreuves, les alliés et les ennemis du héros.','J’observe le rythme (scènes, sommaires, ellipses) et les moments de suspense.','J’explique ce qui a changé chez le héros à la fin.'],
  ['Résumer seulement les événements sans dire ce qu’ils changent pour le personnage.','Confondre élément perturbateur (qui lance l’histoire) et péripétie (épreuve en cours de route).','Croire que l’aventure se limite à l’action : les descriptions et les doutes du héros comptent aussi.'],
  ['Aventure = départ + épreuves + transformation du héros.','Schéma narratif en cinq étapes.','Le rythme (scène, sommaire, ellipse, pause) crée le suspense.']),
 g:mix([seq(['la situation initiale','l’élément perturbateur','les péripéties','l’élément de résolution','la situation finale'],{nq:'Dans le schéma narratif, quelle étape vient juste après « %s » ?',pq:'Dans le schéma narratif, quelle étape vient juste avant « %s » ?',oq:'Remets dans l’ordre les étapes du schéma narratif :'}),1],
  [tagged([['Tom vit tranquillement chez sa tante, dans un village de pêcheurs. [[Un matin, il découvre dans le grenier une vieille carte marquée d’une croix rouge.]]','l’élément perturbateur'],['[[Depuis des années, Lise gardait les chèvres de son oncle dans la montagne.]] Un jour, une lettre mystérieuse arriva.','la situation initiale'],['Le navire quitta le port. [[Une tempête brisa le mât, puis des pirates attaquèrent l’équipage.]]','les péripéties'],['Perdus dans la jungle, les explorateurs désespéraient. [[Soudain, un jeune guide leur montra le chemin du fleuve.]] Ils furent sauvés.','l’élément de résolution',null,2],['[[De retour au village, Tom n’était plus le même : il rêvait déjà d’un nouveau voyage.]]','la situation finale'],['Le royaume vivait en paix. [[Un soir, le dragon enleva la fille du roi.]]','l’élément perturbateur'],['[[Pendant le voyage, Sindbad échoua sur une île qui était en réalité une baleine, puis affronta un oiseau géant.]]','les péripéties',null,2],['[[Grâce à la carte retrouvée, Jim découvrit enfin la cachette du trésor.]]','l’élément de résolution',null,2]],['la situation initiale','l’élément perturbateur','les péripéties','l’élément de résolution','la situation finale'],{q:'À quelle étape du schéma narratif correspond le passage en gras ?<br>« %p »',e:a=>`Étape du schéma narratif : <b>${a}</b>.`,hint:'Demande-toi si le passage lance, complique, résout ou termine l’histoire.'}),2],
  [pairs([['L’Île au trésor','Robert Louis Stevenson'],['Le Tour du monde en quatre-vingts jours','Jules Verne'],['Robinson Crusoé','Daniel Defoe'],['Vendredi ou la vie sauvage','Michel Tournier'],['L’Appel de la forêt','Jack London'],['Les Aventures de Tom Sawyer','Mark Twain'],['Le Lion','Joseph Kessel'],['Alice au pays des merveilles','Lewis Carroll']],{q:'Qui a écrit <i>%s</i> ?',rq:'Quel roman d’aventure a écrit %s ?'}),2],
  [pairs([['Jim Hawkins','L’Île au trésor'],['le capitaine Nemo','Vingt mille lieues sous les mers'],['Phileas Fogg','Le Tour du monde en quatre-vingts jours'],['Buck, un chien','L’Appel de la forêt'],['Sindbad le marin','Les Mille et Une Nuits'],['Ulysse','L’Odyssée'],['Patricia et le lion King','Le Lion']],{q:'Dans quelle œuvre trouve-t-on %s ?',rq:'Quel personnage est un héros de « %s » ?'}),2],
  [tagged([['[[« Lâche cette corde ! » hurla le capitaine. « Jamais ! » répondit Jim en serrant les dents.]]','une scène'],['[[Pendant six semaines, ils naviguèrent vers le sud sans voir la terre.]]','un sommaire'],['Ils quittèrent l’île au printemps. [[Trois ans plus tard,]] Jim revint seul au port.','une ellipse',null,2],['[[La forêt était immense, sombre, couverte de lianes ; des fleurs rouges pendaient des arbres géants.]]','une pause descriptive',null,2]],['une scène','un sommaire','une ellipse','une pause descriptive'],{q:'Quel procédé de rythme reconnais-tu dans le passage en gras ?<br>« %p »',e:a=>`C’est <b>${a}</b>.`,hint:'Le temps du récit va-t-il vite, lentement, ou s’arrête-t-il ?'}),2],
  [bank([['Dans un récit d’aventure, un adjuvant est…','un personnage qui aide le héros',['un personnage qui s’oppose au héros','le lieu de l’aventure','la dernière phrase du récit'],'Adjuvant : allié ; opposant : ennemi.'],
   ['Dans L’Île au trésor, le pirate Long John Silver est surtout…','un opposant rusé et ambigu',['un adjuvant toujours fidèle','le narrateur','le père de Jim'],'Il gagne la confiance de Jim mais veut le trésor pour lui.',2],
   ['Que signifie l’adjectif « intrépide » ?','qui ne connaît pas la peur',['qui est très lent','qui a peur de tout','qui ne voyage jamais'],'Un héros intrépide affronte les dangers sans trembler.'],
   ['Qu’est-ce qu’une péripétie ?','un événement imprévu qui complique ou relance l’action',['la fin heureuse du récit','le titre d’un chapitre','la description d’un personnage'],'Les péripéties forment le cœur de l’aventure.'],
   ['Pourquoi une tempête peut-elle être plus qu’un décor dans un récit d’aventure ?','Elle devient un obstacle qui oblige le héros à agir et révèle son caractère.',['Elle ne sert qu’à faire joli.','Elle termine toujours le récit.','Elle remplace les personnages.'],'Le décor peut devenir une épreuve.',2],
   ['À la fin d’un récit d’aventure, le héros est souvent…','transformé par ce qu’il a vécu',['exactement le même qu’au début','oublié par le narrateur','remplacé par un autre héros'],'L’aventure fait grandir le personnage.',2],
   ['Que crée le narrateur quand il interrompt un chapitre au moment où le héros est en danger ?','du suspense',['une ellipse comique','une description','un dénouement'],'Le lecteur veut savoir ce qui va arriver.',3]]),2])},

{id:'fr6h',name:'Rencontrer des monstres : peur et altérité',icon:'🐉',domain:'Culture littéraire et artistique',
 refs:[REF+' — entrée de 6e « Rencontrer des monstres : expérience de l’autre, expérience de soi (récit, fiction) »',EX6+' : Homère, L’Odyssée ; Perrault ; Leprince de Beaumont, La Belle et la Bête'],
 tip:'Face à un monstre du texte, sépare trois choses : son apparence, ses actes, et le regard que les autres personnages portent sur lui.',
 c:C(`Un géant à un seul œil qui dévore des marins, une femme aux cheveux de serpents qui change les hommes en pierre, une Bête qui vit seule dans un château… Les monstres font peur, mais ils nous obligent aussi à nous demander <b>qui est vraiment monstrueux</b>.`,
  [T('Qu’est-ce qu’un monstre ?',`<p>Le mot vient du latin <i>monstrum</i>, « prodige, signe envoyé par les dieux ». Le monstre se reconnaît à des traits <b>hors norme</b> : il est <b>hybride</b> (mélange d’humain et d’animal ou de plusieurs animaux), <b>gigantesque</b>, <b>difforme</b>, doté de pouvoirs effrayants, souvent <b>sauvage</b> et cruel.</p><p>Dans les récits, il sert d’<b>épreuve</b> : en l’affrontant, le héros révèle son courage ou sa ruse. Mais certains monstres ont une part d’<b>humanité</b> : ils inspirent la peur et aussi la pitié.</p>`),
   T('Les monstres de la mythologie',`<ul class="lst"><li><b>Polyphème</b>, le Cyclope de l’<i>Odyssée</i> d’Homère : géant à un seul œil, fils de Poséidon. Ulysse lui dit s’appeler « Personne », l’enivre puis l’aveugle avec un pieu ; quand Polyphème appelle à l’aide en criant que « Personne » l’attaque, les autres Cyclopes ne viennent pas. Ulysse et ses compagnons s’échappent accrochés sous le ventre des béliers.</li><li><b>Les sirènes</b> attirent les marins par leur chant : Ulysse bouche avec de la cire les oreilles de ses compagnons et se fait attacher au mât.</li><li><b>Méduse</b>, la Gorgone aux cheveux de serpents, change en pierre ceux qui la regardent : Persée la vainc grâce à un bouclier-miroir.</li><li>Le <b>Minotaure</b>, mi-homme mi-taureau, vit dans le labyrinthe de Crète : Thésée le tue et ressort grâce au fil d’Ariane.</li><li>L’<b>Hydre de Lerne</b>, dont les têtes repoussent, est vaincue par Héraclès (Hercule) ; le <b>Sphinx</b> pose une énigme à Œdipe.</li></ul>`),
   T('Les monstres des contes',`<p>Charles <b>Perrault</b> publie en 1697 <i>Histoires ou contes du temps passé</i> : l’ogre du <i>Petit Poucet</i> (et ses bottes de sept lieues), l’ogre du <i>Chat botté</i> qui se change en lion puis en souris, <i>La Barbe bleue</i>. Chaque conte se termine par une <b>moralité</b>.</p><p>Dans <i>La Belle et la Bête</i> de Jeanne-Marie <b>Leprince de Beaumont</b> (1757), la Belle apprend à aimer la Bête pour sa bonté : la Bête redevient prince. Le conte montre que l’apparence ne dit pas tout. Les frères <b>Grimm</b> (sorcière de <i>Hänsel et Gretel</i>) et George Sand (<i>La Reine Coax</i>) ont aussi écrit des contes à monstres.</p>`)],
  [{q:'Comment Ulysse échappe-t-il au Cyclope Polyphème ?',s:['Ruse du nom : il dit s’appeler « Personne ».','Il enivre le Cyclope, puis l’aveugle avec un pieu durci au feu.','Polyphème crie que « Personne » le tue : les autres Cyclopes croient qu’il délire et ne viennent pas.','Ulysse et ses compagnons sortent de la grotte cachés sous le ventre des béliers : la ruse (la mètis) triomphe de la force.']}],
  ['Je décris le monstre précisément (apparence, pouvoirs, lieu où il vit).','Je repère la réaction des personnages et les mots de la peur.','J’observe comment le héros le vainc : force, ruse, bonté ?','Je me demande ce que la créature représente et si elle a une part d’humanité.'],
  ['Décider qu’un personnage est mauvais uniquement parce qu’il est différent.','Confondre le Cyclope Polyphème (Odyssée) et le Minotaure (labyrinthe de Crète).','Oublier la moralité des contes de Perrault, qui donne la leçon du récit.'],
  ['Le monstre est hors norme : hybride, gigantesque, difforme, cruel.','Il met le héros à l’épreuve : courage, ruse, bonté.','Apparence et morale ne se confondent pas : le monstre interroge notre rapport à l’autre.']),
 g:mix([pairs([['Polyphème','Ulysse'],['Méduse','Persée'],['le Minotaure','Thésée'],['l’Hydre de Lerne','Héraclès (Hercule)'],['le Sphinx','Œdipe'],['la Chimère','Bellérophon']],{q:'Quel héros a affronté %s ?',rq:'Quel monstre %s a-t-il affronté ?',e:(a,b)=>`Dans la mythologie grecque, ${b} affronte ${a}.`}),2],
  [pairs([['Polyphème','un Cyclope géant à un seul œil, fils de Poséidon'],['Méduse','une Gorgone aux cheveux de serpents dont le regard change en pierre'],['le Minotaure','un être à corps d’homme et à tête de taureau, enfermé dans un labyrinthe'],['l’Hydre de Lerne','un serpent à plusieurs têtes qui repoussent quand on les coupe'],['le Sphinx','un lion ailé à tête de femme qui pose une énigme'],['les sirènes','des créatures dont le chant attire les marins vers la mort'],['Cerbère','un chien à trois têtes qui garde les Enfers'],['la Chimère','un monstre à tête de lion, corps de chèvre et queue de serpent, qui crache du feu']],{q:'Qui est %s ?',rq:'Quel monstre est %s ?'}),3],
  [bank([['Comment Ulysse se présente-t-il au Cyclope ?','Il dit s’appeler « Personne ».',['Il dit s’appeler « Zeus ».','Il donne son vrai nom.','Il ne parle pas.'],'Ainsi, quand Polyphème crie que « Personne » l’attaque, personne ne vient l’aider.'],
   ['Comment Ulysse et ses compagnons sortent-ils de la grotte du Cyclope ?','accrochés sous le ventre des béliers',['en creusant un tunnel','en volant sur un aigle','déguisés en Cyclopes'],'Le Cyclope aveugle tâte le dos des bêtes mais pas leur ventre.',2],
   ['Que fait Ulysse pour entendre le chant des sirènes sans mourir ?','Il se fait attacher au mât et bouche avec de la cire les oreilles de ses compagnons.',['Il chante plus fort qu’elles.','Il les tue avec son arc.','Il dort pendant tout le passage.'],'Il entend le chant mais ne peut pas se jeter vers les sirènes.',2],
   ['L’Odyssée est attribuée à…','Homère',['Ovide','Perrault','Molière'],'Homère, poète grec de l’Antiquité (vers le VIIIe siècle avant J.-C.).'],
   ['De quelle île Ulysse est-il le roi ?','Ithaque',['la Crète','Troie','la Sicile'],'L’Odyssée raconte son long retour vers Ithaque après la guerre de Troie.'],
   ['Comment Persée peut-il approcher Méduse sans être changé en pierre ?','Il la regarde à travers le reflet de son bouclier.',['Il ferme les yeux et devine.','Il lui bande les yeux.','Il porte des lunettes magiques.'],'Le bouclier-miroir lui évite le regard direct de la Gorgone.',2],
   ['Grâce à quoi Thésée sort-il du labyrinthe ?','le fil que lui a donné Ariane',['une carte dessinée par Minos','les ailes de Dédale','un chien guide'],'Il déroule le fil en entrant et le suit pour ressortir.'],
   ['Qui a écrit Le Petit Poucet et Le Chat botté ?','Charles Perrault',['les frères Grimm','Jean de La Fontaine','Homère'],'Perrault les publie en 1697 dans Histoires ou contes du temps passé.'],
   ['Dans Le Chat botté, comment le chat vient-il à bout de l’ogre ?','Il le pousse à se changer en souris, puis il le mange.',['Il le tue avec une épée.','Il l’enferme dans une cage.','Il le fait tomber dans un puits.'],'La ruse triomphe de la force.',2],
   ['Que vole le Petit Poucet à l’ogre ?','ses bottes de sept lieues',['son épée','son château','sa couronne'],'Ces bottes magiques permettent de faire des pas immenses.',2],
   ['Qui a écrit la version la plus connue de La Belle et la Bête (1757) ?','Jeanne-Marie Leprince de Beaumont',['Charles Perrault','George Sand','Jean Cocteau'],'Jean Cocteau en a tiré un film en 1946.',2],
   ['Que montre le conte La Belle et la Bête ?','qu’il faut juger les êtres sur leur bonté plutôt que sur leur apparence',['qu’il faut fuir tout ce qui est laid','que les monstres sont toujours méchants','que la richesse rend heureux'],'La Belle aime la Bête pour sa bonté : la Bête redevient prince.'],
   ['À quoi sert la moralité à la fin d’un conte de Perrault ?','à donner la leçon du récit',['à décrire le monstre','à présenter les personnages','à raconter une autre histoire'],'La moralité tire l’enseignement du conte.'],
   ['Le mot « monstre » vient du latin monstrum, qui signifiait…','un prodige, un signe envoyé par les dieux',['un animal domestique','un chevalier','une forêt'],'Le monstre est d’abord un être extraordinaire, un avertissement.',3],
   ['Un monstre « hybride » est…','composé de parties de plusieurs êtres différents',['très petit','invisible','immortel'],'Le Minotaure (homme et taureau) ou la Chimère sont hybrides.'],
   ['Un monstre qui protège son territoire et n’attaque que s’il est menacé est-il forcément méchant ?','Non : il faut distinguer son apparence, ses actes et le point de vue du narrateur.',['Oui, car il est laid.','Oui, car tous les monstres sont mauvais.','On ne peut rien en dire.'],'Le récit invite à nuancer son jugement.',3]]),4],
  [sort({'traits physiques':['hideux','difforme','gigantesque','velu','griffu'],'traits moraux':['cruel','impitoyable','sournois','généreux','compatissant']},{q:'L’adjectif « %s » décrit plutôt…',e:(x,c)=>`« ${x} » décrit des ${c} : ${c==='traits physiques'?'l’apparence du personnage':'son caractère et sa conduite'}.`}),1])},

/* ===================== GRAMMAIRE ===================== */
{id:'fr6i',name:'Types, formes de phrases et ponctuation',icon:'❗',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Identifier les constituants d’une phrase simple » ; transformation à la forme négative (temps composés)',GRAM+' : types déclaratif, interrogatif, impératif ; formes négative et exclamative'],
 tip:'Le type dépend de l’intention (informer, questionner, ordonner) ; la forme se reconnaît à « ne… pas » (négative) ou au point d’exclamation (exclamative). Une phrase a toujours un type ET une forme.',
 c:C(`« Tu fermes la porte. » « Fermes-tu la porte ? » « Ferme la porte ! » « Ne ferme pas la porte. » Avec les mêmes mots, on peut informer, questionner, ordonner, s’exclamer ou nier. Chaque phrase a un <b>type</b> et une <b>forme</b>.`,
  [T('Trois types de phrases',`<table class="ptable"><tr><th>Type</th><th>Intention</th><th>Exemple</th></tr><tr><td>déclaratif</td><td>informer, raconter</td><td>Tu fermes la porte.</td></tr><tr><td>interrogatif</td><td>poser une question</td><td>Fermes-tu la porte ? / Est-ce que tu fermes la porte ?</td></tr><tr><td>impératif (ou injonctif)</td><td>ordonner, conseiller, interdire</td><td>Ferme la porte.</td></tr></table><p>La question se construit par l’<b>inversion du sujet</b> (Fermes-tu… ?, avec un trait d’union), par <b>« est-ce que »</b> ou par la seule intonation à l’oral.</p>`),
   T('Les formes : négative et exclamative',`<p>Chaque type peut prendre la <b>forme négative</b> (ne… pas, ne… jamais, ne… plus, ne… rien, ne… personne) et/ou la <b>forme exclamative</b> (point d’exclamation, émotion). L’exclamation n’est <b>pas un type</b> : « Tu fermes la porte ! » est de type déclaratif, à la forme exclamative.</p><p>Aux temps composés, la négation encadre l’<b>auxiliaire</b> : « Elle <b>n’</b>a <b>pas</b> terminé. » « Nous <b>n’</b>avions <b>jamais</b> vu la mer. » Devant une voyelle, « ne » devient « n’ ».</p>`),
   T('La ponctuation',`<ul class="lst"><li><b>point</b> (.) : fin d’une phrase déclarative ou impérative ;</li><li><b>point d’interrogation</b> (?) et <b>point d’exclamation</b> (!) ;</li><li><b>points de suspension</b> (…) : phrase inachevée, hésitation ;</li><li><b>virgule</b> : sépare les éléments d’une énumération, isole un complément déplacé ou une apostrophe (« Léa, viens ! ») ;</li><li><b>deux-points</b> : annoncent une explication, une énumération ou des paroles ;</li><li><b>guillemets</b> et <b>tirets</b> : encadrent un dialogue ; le tiret marque le changement d’interlocuteur.</li></ul>`)],
  [{q:'Transforme « Tu fermes la porte. » en phrase interrogative, impérative, puis impérative négative.',s:['Interrogative par inversion : « Fermes-tu la porte ? » (trait d’union entre le verbe et le sujet).','Impérative : « Ferme la porte. » (pas de sujet exprimé, pas de « s » pour un verbe en -er).','Impérative négative : « Ne ferme pas la porte. »','La ponctuation et la construction changent avec le type et la forme.']}],
  ['Je cherche l’intention de la phrase : informer, questionner ou ordonner (le type).','Je regarde la négation (ne… pas, jamais, plus…) et la ponctuation finale (la forme).','Je vérifie en transformant la phrase.'],
  ['Dire qu’une phrase est « exclamative » comme type : l’exclamation est une forme.','Oublier le « ne » de la négation à l’écrit (« Tu fermes pas » est familier et incorrect à l’écrit).','Placer « pas » après le participe passé : on écrit « Il n’a pas fini », non « Il n’a fini pas ».'],
  ['Types : déclaratif, interrogatif, impératif.','Formes : affirmative ou négative ; exclamative ou non.','Aux temps composés, la négation encadre l’auxiliaire.']),
 g:(()=>{
  const KER=[['fermes','Fermes-tu','Ferme','la porte'],['ranges','Ranges-tu','Range','ta chambre'],['finis','Finis-tu','Finis','ton exercice'],['prends','Prends-tu','Prends','le bus'],['écoutes','Écoutes-tu','Écoute','la radio'],['fais','Fais-tu','Fais','tes devoirs'],['lis','Lis-tu','Lis','ce roman'],['ouvres','Ouvres-tu','Ouvre','la fenêtre'],['choisis','Choisis-tu','Choisis','un livre'],['appelles','Appelles-tu','Appelle','ton frère']];
  const neg=v=>(VOW.test(v)?'n’':'ne ')+v;const Neg=v=>(VOW.test(v)?'N’':'Ne ')+v.charAt(0).toLowerCase()+v.slice(1);
  const forms=k=>{const [pr,inv,imp,c]=k;return [[`Tu ${pr} ${c}.`,'déclaratif','affirmative'],[`Tu ${neg(pr)} pas ${c}.`,'déclaratif','négative'],[`Tu ${pr} ${c} !`,'déclaratif','affirmative et exclamative'],[`Tu ${neg(pr)} pas ${c} !`,'déclaratif','négative et exclamative'],[`${inv} ${c} ?`,'interrogatif','affirmative'],[`Est-ce que tu ${pr} ${c} ?`,'interrogatif','affirmative'],[`${Neg(inv)} pas ${c} ?`,'interrogatif','négative'],[`${imp} ${c}.`,'impératif','affirmative'],[`${imp} ${c} !`,'impératif','affirmative et exclamative'],[`${Neg(imp)} pas ${c}.`,'impératif','négative'],[`${Neg(imp)} pas ${c} !`,'impératif','négative et exclamative']];};
  const TY={'déclaratif':'elle informe, elle raconte','interrogatif':'elle pose une question','impératif':'elle donne un ordre ou un conseil, sans sujet exprimé'};
  const gType=d=>{const [s,t]=P(forms(P(KER)));return ch(`Quel est le <b>type</b> de la phrase « ${s} » ?`,'type '+t,['type déclaratif','type interrogatif','type impératif','type exclamatif'].filter(x=>x!=='type '+t),{expl:`Type <b>${t}</b> : ${TY[t]}. L’exclamation n’est jamais un type, c’est une forme.`,hint:'Quelle est l’intention : informer, questionner ou ordonner ?'});};
  const gForm=d=>{const [s,,f]=P(forms(P(KER)));return ch(`Quelle est la <b>forme</b> de la phrase « ${s} » ?`,f,['affirmative','négative','affirmative et exclamative','négative et exclamative'].filter(x=>x!==f),{expl:`Négation ${/négative/.test(f)?'présente (ne… pas)':'absente'} ; point d’exclamation ${/exclamative/.test(f)?'présent':'absent'} : forme <b>${f}</b>.`,hint:'Cherche « ne… pas » et le point d’exclamation.'});};
  const gNeg=d=>{const [pr,inv,imp,c]=P(KER);if(Math.random()<.5){const g=`Tu ${neg(pr)} pas ${c}.`;return ch(`Mets à la forme négative : « Tu ${pr} ${c}. »`,g,[`Tu ${pr} pas ${c}.`,`Tu ${neg(pr)} ${c}.`,`Tu ne pas ${pr} ${c}.`],{expl:`La négation encadre le verbe conjugué : <b>${g}</b> (« ne » devient « n’ » devant une voyelle).`,hint:'Ne… pas encadre le verbe.'});}
    const g=`${Neg(imp)} pas ${c}.`;return ch(`Mets à la forme négative : « ${imp} ${c}. »`,g,[`${imp} pas ${c}.`,`${Neg(imp)} ${c}.`,`Ne pas ${imp.toLowerCase()} ${c}.`],{expl:`À l’impératif aussi, la négation encadre le verbe : <b>${g}</b>`,hint:'Il faut les deux mots de la négation.'});};
  const gInv=d=>{const [pr,inv,imp,c]=P(KER);const g=`${inv} ${c} ?`;return ch(`Transforme en phrase interrogative par inversion du sujet : « Tu ${pr} ${c}. »`,g,[`${inv.replace('-',' ')} ${c} ?`,`Tu ${pr}-tu ${c} ?`,`${inv} ${c}.`],{expl:`On place le sujet après le verbe, relié par un trait d’union, et on termine par un point d’interrogation : <b>${g}</b>`,hint:'Trait d’union et point d’interrogation.'});};
  const gImp=d=>{const [pr,inv,imp,c]=P(KER);const g=`${imp} ${c}.`;return ch(`Transforme en phrase impérative : « Tu ${pr} ${c}. »`,g,[`Tu ${imp.toLowerCase()} ${c}.`,`${cap(pr)} ${c}.`,`${imp}-tu ${c}.`],{expl:`À l’impératif, il n’y a pas de sujet exprimé${pr.endsWith('es')?' et les verbes en -er n’ont pas de « s » à la 2e personne du singulier':''} : <b>${g}</b>`,hint:'Supprime le sujet « tu ».'});};
  const PC=[['fermer','la porte'],['finir','l’exercice'],['prendre','le bus'],['écouter','la radio'],['faire','les devoirs'],['choisir','un livre'],['regarder','le film'],['trouver','la solution']];
  const gPC=d=>{const [v,c]=P(PC);const i=R(0,5);const a=H.IRR['avoir'].pr[i],pp=H.participe(v);const S=cap(i===0?'je':i===2?P(['il','elle']):PRON[i]);const aff=i===0?`J’${a} ${pp} ${c}.`:`${S} ${a} ${pp} ${c}.`;const g=`${S} n’${a} pas ${pp} ${c}.`;
    return ch(`Mets à la forme négative : « ${aff} »`,g,[`${S} n’${a} ${pp} pas ${c}.`,i===0?`J’${a} pas ${pp} ${c}.`:`${S} ${a} pas ${pp} ${c}.`,`${S} ne ${a} pas ${pp} ${c}.`],{expl:`Au passé composé, « ne… pas » encadre l’auxiliaire : <b>${g}</b>`,hint:'La négation entoure l’auxiliaire « avoir ».'});};
  const B=bank([['Quel signe annonce une explication ou une énumération ?','les deux-points',['le point-virgule','les points de suspension','le point d’interrogation'],'« Il avait tout prévu : une corde, une lampe et des biscuits. »'],
   ['Dans un dialogue, que marque le tiret en début de ligne ?','le changement de personnage qui parle',['la fin du texte','une question','une énumération'],'Chaque nouvelle réplique commence par un tiret.'],
   ['Dans « Léa, viens ici ! », pourquoi y a-t-il une virgule après « Léa » ?','elle isole le nom de la personne à qui l’on parle (l’apostrophe)',['elle sépare le sujet du verbe','elle marque une question','elle est inutile'],'On isole par une virgule le nom de la personne interpellée.',2],
   ['« Elle ne mange jamais de viande. » Quels mots forment la négation ?','ne… jamais',['mange… de','elle… viande','jamais… viande'],'La négation peut être ne… pas, ne… jamais, ne… plus, ne… rien, ne… personne.'],
   ['Quelle phrase est correcte à l’écrit ?','Je ne sais pas.',['Je sais pas.','Je ne sais.','Je ne pas sais.'],'À l’écrit, la négation comporte toujours « ne ».'],
   ['« Nous n’avions rien vu. » Quelle est la forme de la phrase ?','négative',['affirmative','exclamative','interrogative'],'« ne… rien » est une négation.',2],
   ['« Quelle belle journée ! » Quel est le type de cette phrase ?','type déclaratif, forme exclamative',['type exclamatif','type interrogatif','type impératif'],'Elle exprime un constat avec émotion : type déclaratif, forme exclamative.',3],
   ['Quelle phrase est de type impératif ?','Range ta chambre avant le dîner.',['Tu ranges ta chambre avant le dîner.','Ranges-tu ta chambre avant le dîner ?','Tu as rangé ta chambre !'],'Pas de sujet exprimé, verbe à l’impératif : type impératif.']]);
  return mix([gType,3],[gForm,2],[gNeg,2],[gInv,1],[gImp,1],[gPC,2],[B,2]);})()},

{id:'fr6j',name:'Nature et fonction : classes de mots',icon:'🧱',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Identifier les mots, un groupe de mots selon leur nature »',GRAM+' : classes de mots ; conjonctions de coordination (mais, ou, et, or, ni, car)'],
 tip:'Pour trouver la classe d’un mot, regarde son entourage : un mot placé devant un nom et qui varie avec lui est un déterminant ; le même mot placé devant un verbe (« je la vois ») est un pronom.',
 c:C(`« Je <b>la</b> vois » et « <b>la</b> porte » : le même petit mot n’a pas la même <b>nature</b>. Connaître la classe d’un mot, c’est savoir ce qu’il est ; connaître sa <b>fonction</b>, c’est savoir quel rôle il joue dans la phrase.`,
  [T('Les classes de mots variables',`<ul class="lst"><li><b>Nom</b> : désigne un être, une chose, une idée (commun : « chat » ; propre : « Paris », avec une majuscule).</li><li><b>Déterminant</b> : se place devant le nom et en indique le genre et le nombre — articles définis (le, la, les) et indéfinis (un, une, des), possessifs (mon, ta, leurs…), démonstratifs (ce, cet, cette, ces).</li><li><b>Adjectif</b> : précise le nom et s’accorde avec lui.</li><li><b>Pronom</b> : remplace ou désigne un nom ou un groupe nominal (je, tu, il, nous, le, la, les, lui, leur…).</li><li><b>Verbe</b> : se conjugue ; il exprime une action ou un état.</li></ul>`),
   T('Les classes de mots invariables',`<ul class="lst"><li><b>Adverbe</b> : modifie le sens d’un verbe, d’un adjectif ou d’un autre adverbe (vite, très, souvent, hier, lentement).</li><li><b>Préposition</b> : introduit un complément (à, de, dans, par, pour, sans, sur, avec, chez, pendant…).</li><li><b>Conjonction de coordination</b> : relie deux éléments de même fonction. La terminologie officielle en retient <b>six</b> : mais, ou, et, or, ni, car (« donc » est un adverbe).</li><li><b>Conjonction de subordination</b> : introduit une proposition subordonnée (quand, lorsque, parce que, puisque, si, que…).</li></ul>`),
   T('Nature et fonction',`<p>La <b>nature</b> (ou classe) est l’identité du mot : elle ne change pas selon la phrase (sauf mots à plusieurs classes comme « le » ou « fort »). La <b>fonction</b> est son rôle dans une phrase précise : sujet, COD, COI, attribut, complément circonstanciel, épithète, complément du nom.</p><p>« <b>Le chat</b> observe la souris » : nature = groupe nominal ; fonction = sujet. « La souris observe <b>le chat</b> » : même nature, fonction COD.</p>`)],
  [{q:'Dans « Léa regarde les étoiles et elle les compte », quelle est la nature de chaque « les » ?',s:['Le premier « les » est placé devant le nom « étoiles » : c’est un déterminant (article défini).','Le second « les » est placé devant le verbe « compte » et remplace « les étoiles » : c’est un pronom personnel.','Même forme, deux natures différentes : on regarde toujours l’entourage du mot.']}],
  ['J’identifie le mot ou le groupe de mots à analyser.','Je regarde ce qui l’entoure (devant un nom ? devant un verbe ?) et s’il varie.','Je nomme sa classe, puis seulement ensuite sa fonction si on me la demande.'],
  ['Répondre « sujet » quand on demande la nature : sujet est une fonction.','Confondre « le, la, les » déterminants (devant un nom) et pronoms (devant un verbe).','Classer « donc » parmi les conjonctions de coordination : la terminologie officielle en fait un adverbe.'],
  ['Nature = ce qu’est le mot ; fonction = son rôle dans la phrase.','Neuf classes : nom, déterminant, adjectif, pronom, verbe, adverbe, préposition, conjonctions de coordination et de subordination.','Conjonctions de coordination : mais, ou, et, or, ni, car.']),
 g:(()=>{
  const S=[[['Le','déterminant'],['petit','adjectif'],['chat','nom'],['dort','verbe'],['tranquillement','adverbe'],['sur','préposition'],['le','déterminant'],['canapé','nom']],
   [['Ma','déterminant'],['sœur','nom'],['lit','verbe'],['un','déterminant'],['roman','nom'],['passionnant','adjectif']],
   [['Nous','pronom'],['partirons','verbe'],['demain','adverbe'],['avec','préposition'],['nos','déterminant'],['cousins','nom']],
   [['Le','déterminant'],['vent','nom'],['souffle','verbe'],['fort','adverbe','Ici, « fort » modifie le verbe « souffle » et ne s’accorde pas : c’est un adverbe.'],[',',''],['mais','conjonction de coordination'],['la','déterminant'],['mer','nom'],['reste','verbe'],['calme','adjectif']],
   [['Léa','nom','C’est un nom propre.'],['regarde','verbe'],['les','déterminant','Placé devant le nom « étoiles ».'],['étoiles','nom'],['et','conjonction de coordination'],['elle','pronom'],['les','pronom','Placé devant le verbe, il remplace « les étoiles ».'],['compte','verbe']],
   [['Quand','conjonction de subordination'],['il','pronom'],['pleut','verbe'],[',',''],['les','déterminant'],['enfants','nom'],['jouent','verbe'],['dans','préposition'],['le','déterminant'],['grenier','nom']],
   [['Cette','déterminant'],['vieille','adjectif'],['maison','nom'],['de','préposition'],['pierre','nom'],['appartient','verbe'],['à','préposition'],['mon','déterminant'],['oncle','nom']],
   [['Ils','pronom'],['marchent','verbe'],['très','adverbe'],['lentement','adverbe'],['car','conjonction de coordination'],['le','déterminant'],['chemin','nom'],['est','verbe'],['raide','adjectif']],
   [['Le','déterminant'],['professeur','nom'],['nous','pronom'],['explique','verbe'],['la','déterminant'],['leçon','nom']],
   [['Je','pronom'],['la','pronom','Placé devant le verbe « vois », il remplace un nom féminin : pronom personnel.'],['vois','verbe'],['souvent','adverbe'],['dans','préposition'],['ce','déterminant'],['parc','nom']],
   [['Paris','nom','C’est un nom propre.'],['est','verbe'],['une','déterminant'],['ville','nom'],['immense','adjectif']],
   [['Ce','déterminant'],['courageux','adjectif'],['chevalier','nom'],['attaque','verbe'],['le','déterminant'],['dragon','nom'],['sans','préposition'],['hésiter','verbe','C’est un verbe à l’infinitif.']],
   [['Mon','déterminant'],['frère','nom'],['ne','adverbe','« ne… pas » est un adverbe de négation.'],['mange','verbe'],['ni','conjonction de coordination'],['fromage','nom'],['ni','conjonction de coordination'],['dessert','nom']],
   [['Les','déterminant'],['élèves','nom'],['sortent','verbe'],['parce que','conjonction de subordination','« parce que » est une locution conjonctive de subordination.'],['la','déterminant'],['cloche','nom'],['sonne','verbe']]];
  const EX={'nom':'Il désigne un être, une chose ou une idée.','déterminant':'Il se place devant le nom et indique son genre et son nombre.','adjectif':'Il précise une qualité du nom et s’accorde avec lui.','pronom':'Il remplace ou désigne un nom ou un groupe nominal.','verbe':'Il se conjugue (ou se met à l’infinitif) et exprime une action ou un état.','adverbe':'Mot invariable qui modifie le sens d’un verbe, d’un adjectif ou d’un autre adverbe.','préposition':'Mot invariable qui introduit un complément (à, de, dans, sur, avec, sans…).','conjonction de coordination':'Elle relie deux éléments de même fonction : mais, ou, et, or, ni, car.','conjonction de subordination':'Elle introduit une proposition subordonnée (quand, parce que, si…).'};
  const PL={'nom':['adjectif','verbe','pronom'],'déterminant':['pronom','adjectif','préposition'],'adjectif':['adverbe','nom','verbe'],'pronom':['déterminant','nom','préposition'],'verbe':['nom','adjectif','adverbe'],'adverbe':['adjectif','préposition','conjonction de coordination'],'préposition':['adverbe','déterminant','conjonction de subordination'],'conjonction de coordination':['préposition','adverbe','conjonction de subordination'],'conjonction de subordination':['conjonction de coordination','préposition','adverbe']};
  const gWord=d=>{const s=P(S);const idx=s.map((t,k)=>t[1]?k:-1).filter(k=>k>=0);const k=P(idx);const [w,c,note]=s[k];
    const ph=s.map((t,j)=>j===k?`<b>${t[0]}</b>`:t[0]).join(' ').replace(/ ,/g,',')+'.';
    return ch(`Quelle est la classe (nature) du mot en gras ?<br>« ${ph} »`,c,PL[c],{expl:`« ${w} » : <b>${c}</b>. ${note||EX[c]}`,hint:'Regarde ce qui entoure le mot : un nom ? un verbe ?'});};
  const B=bank([['Dans « Le chat observe la souris », quelle est la nature de « le chat » ?','un groupe nominal',['sujet','un verbe','un COD'],'« sujet » est une fonction ; la nature est groupe nominal (déterminant + nom).'],
   ['Dans « Le chat observe la souris », quelle est la fonction de « le chat » ?','sujet',['groupe nominal','COD','déterminant'],'Il commande l’accord du verbe : c’est le sujet.'],
   ['Dans « La souris observe le chat », quelle est la fonction de « le chat » ?','COD',['sujet','groupe nominal','attribut du sujet'],'Même nature (groupe nominal), fonction différente : COD du verbe « observe ».',2],
   ['Combien y a-t-il de conjonctions de coordination selon la terminologie grammaticale officielle ?','six : mais, ou, et, or, ni, car',['sept : mais, ou, et, donc, or, ni, car','trois : et, ou, mais','une seule : et'],'La terminologie de 2020 range « donc » parmi les adverbes.',2],
   ['« ces » dans « ces livres » est un déterminant…','démonstratif',['possessif','article défini','article indéfini'],'ce, cet, cette, ces : déterminants démonstratifs.'],
   ['« leurs » dans « leurs livres » est un déterminant…','possessif',['démonstratif','article défini','article indéfini'],'mon, ton, son, notre, votre, leur(s)… : déterminants possessifs.'],
   ['« des » dans « des livres » est…','un article indéfini',['un article défini','un déterminant possessif','un pronom'],'un, une, des : articles indéfinis.'],
   ['« les » dans « les livres » est…','un article défini',['un article indéfini','un pronom personnel','un déterminant démonstratif'],'le, la, l’, les : articles définis.'],
   ['Dans « Il court vite », « vite » est…','un adverbe',['un adjectif','un verbe','une préposition'],'Il modifie le verbe « court » et ne varie pas.'],
   ['Dans « Je pense qu’il viendra », « qu’ » (que) est…','une conjonction de subordination',['un pronom','une conjonction de coordination','une préposition'],'Il introduit la proposition subordonnée « qu’il viendra ».',3]]);
  const W=sort({'nom':['maison','courage','Marseille','idée'],'adjectif':['courageux','immense','fragile'],'verbe':['courir','grandir','apercevoir'],'adverbe':['souvent','jamais','lentement','hier'],'préposition':['avec','sans','pendant','chez'],'conjonction de coordination':['mais','car','ni'],'conjonction de subordination':['lorsque','parce que','puisque']},{q:'Le mot « %s » est…',e:(x,c)=>`« ${x} » : ${c}. ${EX[c]}`});
  return mix([gWord,6],[B,2],[W,2]);})()},

{id:'fr6k',name:'Sujet, COD, COI, attribut et compléments',icon:'🎯',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Analyser une phrase simple » : opposer attribut du sujet et COD, manipulations syntaxiques, construction du verbe',GRAM+' : groupe sujet, groupe verbal (COD, COI, attribut du sujet), groupe circonstanciel'],
 tip:'Teste chaque groupe : le sujet s’encadre par « c’est… qui » ; le complément circonstanciel se déplace et se supprime ; après être, sembler, devenir, rester, paraître, le groupe est un attribut du sujet.',
 c:C(`« Léa <b>devient</b> une excellente nageuse » et « Léa <b>rencontre</b> une excellente nageuse » : le même groupe n’a pas la même fonction ! Dans le premier cas, Léa et la nageuse sont la même personne. Pour analyser une phrase, il faut regarder le <b>verbe</b> et faire des <b>manipulations</b>.`,
  [T('Le sujet et le groupe verbal',`<p>La phrase de base = <b>groupe sujet</b> + <b>groupe verbal</b> (+ groupe circonstanciel facultatif).</p><p>Le <b>sujet</b> commande l’accord du verbe ; on le trouve avec « c’est… qui » ou « qui est-ce qui ? ». Il peut être <b>inversé</b> (« Au fond du jardin pousse <b>un cerisier</b> ») ou être un pronom, un infinitif (« <b>Nager</b> détend »).</p><p>Dans le groupe verbal : le <b>COD</b> complète le verbe sans préposition (« Le chat attrape <b>une souris</b> ») ; le <b>COI</b> est introduit par une préposition, souvent à ou de (« Il obéit <b>à ses parents</b> », « Tu te souviens <b>de cette histoire</b> ») ; les pronoms « le, la, les » sont COD, « lui, leur » sont COI.</p>`),
   T('Attribut du sujet ou COD ?',`<p>Après un <b>verbe attributif</b> (être, sembler, paraître, devenir, rester, demeurer, avoir l’air), le groupe qui suit est un <b>attribut du sujet</b> : il caractérise le sujet et désigne la même réalité. Il s’accorde avec le sujet : « Ma sœur semble fatigué<b>e</b>. »</p><p>Le <b>COD</b> désigne une autre réalité que le sujet : « Léa rencontre une nageuse » (deux personnes différentes). L’attribut ne se supprime pas : « *Ma sœur semble » est incomplet.</p>`),
   T('Les compléments circonstanciels',`<p>Le <b>complément circonstanciel</b> (CC) apporte une information facultative sur l’ensemble de la phrase : on peut le <b>déplacer</b> et le <b>supprimer</b>. Au cycle 3, on distingue :</p><ul class="lst"><li>CC de <b>temps</b> (quand ?) : <b>Chaque matin</b>, je promène le chien.</li><li>CC de <b>lieu</b> (où ?) : Le chat dort <b>sous la table</b>.</li><li>CC de <b>cause</b> (pourquoi ?) : <b>À cause de la pluie</b>, le match est reporté.</li></ul><p>Attention : avec un verbe comme « aller » (« Paul va à Paris »), « à Paris » est nécessaire au verbe ; ce n’est pas un CC.</p>`)],
  [{q:'Analyse « Ce matin, Léa semble heureuse et parle à son frère. »',s:['« Ce matin » : déplaçable et supprimable → complément circonstanciel de temps.','« Léa » : c’est Léa qui semble et qui parle → sujet.','« heureuse » : après le verbe attributif « semble », il caractérise Léa → attribut du sujet (accordé au féminin).','« à son frère » : introduit par « à », il complète « parle » → COI.']}],
  ['Je repère le verbe conjugué, puis le sujet (c’est… qui).','Je regarde si le verbe est attributif (être, sembler, devenir…).','Je teste le déplacement et la suppression pour repérer les compléments circonstanciels.','Je distingue COD (sans préposition) et COI (avec préposition) ; je peux remplacer par le/la/les ou lui/leur.'],
  ['Croire que tout groupe placé après le verbe est un COD.','Prendre l’attribut du sujet pour un COD après « devenir » ou « sembler ».','Prendre le nom placé juste avant le verbe pour le sujet (« Le chat les regarde » : le sujet est « le chat »).'],
  ['Le sujet commande l’accord du verbe.','COD sans préposition ; COI avec préposition ; attribut après un verbe attributif.','Le complément circonstanciel se déplace et se supprime : temps, lieu, cause.']),
 g:(()=>{
  const ALL=['sujet','COD','COI','attribut du sujet','complément circonstanciel'];
  const E={'sujet':'Le groupe commande l’accord du verbe ; on peut l’encadrer par « c’est… qui ».','COD':'Le groupe complète le verbe sans préposition et désigne autre chose que le sujet.','COI':'Le groupe complète le verbe et il est introduit par une préposition (à, de) ou remplacé par lui/leur.','attribut du sujet':'Le verbe est attributif (être, sembler, devenir, rester, paraître, avoir l’air) : le groupe caractérise le sujet.','complément circonstanciel':'On peut le déplacer et le supprimer : il précise une circonstance (temps, lieu, cause).'};
  const I=[['[[Les élèves]] préparent un exposé.','sujet'],['Au fond du jardin pousse [[un vieux cerisier]].','sujet','Le sujet est inversé : c’est un vieux cerisier qui pousse.',2],['[[Mon frère et ma cousine]] adorent les énigmes.','sujet','Deux noms coordonnés forment le sujet (verbe au pluriel).',2],['Dans la cour résonnent [[les cris des enfants]].','sujet','Sujet inversé : ce sont les cris qui résonnent.',3],['[[Nager]] détend les muscles.','sujet','Un verbe à l’infinitif peut être sujet.',3],
   ['Le chat attrape [[une souris]].','COD'],['Nous admirons [[ce paysage]].','COD'],['Léa rencontre [[une excellente nageuse]].','COD','« rencontrer » n’est pas attributif : Léa et la nageuse sont deux personnes.',2],['Ma grand-mère prépare [[une tarte aux pommes]].','COD'],['Tom lit [[un roman d’aventures]] chaque soir.','COD'],['Ma mère [[les]] appelle pour le dîner.','COD','« les » est un pronom personnel COD placé devant le verbe.',3],
   ['Ils obéissent [[à leurs parents]].','COI'],['Tu te souviens [[de cette histoire]].','COI',null,2],['Je téléphone [[à ma grand-mère]].','COI'],['Le professeur [[lui]] répond.','COI','« lui » remplace « à quelqu’un » : pronom COI.',3],['Ce livre appartient [[à ma sœur]].','COI'],['Nous parlons [[de nos projets]].','COI',null,2],
   ['Le ciel devient [[gris]].','attribut du sujet'],['Ma sœur semble [[fatiguée]].','attribut du sujet'],['Léa devient [[une excellente nageuse]].','attribut du sujet','Léa et la nageuse sont la même personne : attribut, pas COD.',2],['Mon oncle est [[médecin]].','attribut du sujet'],['Ces fruits paraissent [[mûrs]].','attribut du sujet'],['Les feuilles restent [[vertes]] tout l’hiver.','attribut du sujet',null,2],['Zoé a l’air [[heureuse]].','attribut du sujet','« avoir l’air » est ici attributif : « heureuse » s’accorde avec Zoé.',3],
   ['[[Chaque matin]], je promène le chien.','complément circonstanciel'],['Le chat dort [[sous la table]].','complément circonstanciel'],['[[À cause de la pluie]], le match est reporté.','complément circonstanciel'],['Nous avons pique-niqué [[au bord de la rivière]].','complément circonstanciel',null,2],['Il est absent [[parce qu’il est malade]].','complément circonstanciel','Une proposition peut être complément circonstanciel.',3],['[[Depuis trois jours]], il neige.','complément circonstanciel'],['Les promeneurs cueillent des champignons [[dans la forêt]].','complément circonstanciel',null,2]];
  const gF=tagged(I,ALL,{q:'Quelle est la fonction du groupe en gras ?<br>« %p »',e:a=>`<b>${a}</b> : ${E[a]}`,hint:'Fais les tests : c’est… qui ; déplacement ; verbe attributif ; préposition.'});
  const CC=[['[[Chaque matin]], je promène le chien.','CC de temps'],['[[Depuis trois jours]], il neige.','CC de temps'],['Le train part [[à huit heures]].','CC de temps'],['[[Quand la cloche sonne]], les élèves rentrent.','CC de temps',null,2],['[[Pendant les vacances]], nous lisons beaucoup.','CC de temps'],
   ['Le chat dort [[sous la table]].','CC de lieu'],['Nous avons pique-niqué [[au bord de la rivière]].','CC de lieu'],['[[En Bretagne]], il pleut souvent.','CC de lieu'],['[[Dans la forêt]], les promeneurs cueillent des champignons.','CC de lieu'],['Les hirondelles construisent leur nid [[sous le toit]].','CC de lieu',null,2],
   ['[[À cause de la pluie]], le match est reporté.','CC de cause'],['Il est absent [[parce qu’il est malade]].','CC de cause',null,2],['[[Grâce à son travail]], elle a réussi.','CC de cause',null,2],['Il tremble [[de froid]].','CC de cause',null,3],['[[Comme il faisait nuit]], nous avons allumé une lampe.','CC de cause',null,3]];
  const Q={'CC de temps':'quand ?','CC de lieu':'où ?','CC de cause':'pourquoi ?'};
  const gCC=tagged(CC,['CC de temps','CC de lieu','CC de cause'],{q:'Quel est le type du complément circonstanciel en gras ?<br>« %p »',e:a=>`Il répond à la question « ${Q[a]} » : <b>${a}</b>.`,hint:'Pose les questions quand ? où ? pourquoi ?'});
  const B=bank([['Quel test permet de reconnaître un complément circonstanciel ?','On peut le déplacer et le supprimer.',['On peut le remplacer par « il ».','Il est toujours placé avant le verbe.','Il commande l’accord du verbe.'],'Le CC est mobile et facultatif.'],
   ['Quel verbe est attributif ?','sembler',['manger','regarder','téléphoner'],'Verbes attributifs : être, sembler, paraître, devenir, rester, demeurer, avoir l’air.'],
   ['Dans « Le chat les regarde », quel est le sujet ?','le chat',['les','regarde','on ne sait pas'],'« les » est un pronom COD placé devant le verbe ; c’est le chat qui regarde.',2],
   ['Dans « Paul va à Paris », « à Paris » est-il un complément circonstanciel ?','Non, car il est nécessaire au verbe « aller » : on ne peut pas le supprimer.',['Oui, car il répond à « où ? ».','Oui, car il commence par « à ».','Non, c’est le sujet.'],'La terminologie officielle met en garde : avec les verbes de mouvement, ce complément dépend du verbe.',3],
   ['Par quel pronom remplace-t-on un COI introduit par « à » désignant une personne ?','lui ou leur',['le, la ou les','en','qui'],'« Je parle à Paul » → « Je lui parle ».',2]]);
  return mix([gF,6],[gCC,3],[B,1]);})()},

{id:'fr6l',name:'Le groupe nominal et ses expansions',icon:'🌳',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Identifier le groupe nominal, quelle que soit sa fonction ; analyser le groupe nominal ; différencier adjectif épithète et groupe nominal prépositionnel complément du nom »',GRAM],
 tip:'Pour trouver le nom noyau, supprime tout ce qui peut l’être : il reste le déterminant et le nom noyau (« la vieille maison de pierre » → « la maison »).',
 c:C(`« Une maison » ou « la vieille maison de pierre au bord du lac » ? Le second groupe nominal donne bien plus d’informations. Les mots ajoutés autour du nom s’appellent des <b>expansions</b>.`,
  [T('La structure du groupe nominal',`<p>Le <b>groupe nominal</b> (GN) s’organise autour d’un <b>nom noyau</b>, généralement précédé d’un <b>déterminant</b> : « la maison ». Le noyau donne au groupe son genre et son nombre et commande les accords.</p><p>On l’enrichit avec des <b>expansions</b>, qu’on peut supprimer sans détruire le groupe : « la (vieille) maison (de pierre) ». Le GN peut occuper toutes les fonctions : sujet, COD, COI, attribut, complément circonstanciel.</p>`),
   T('Épithète et complément du nom',`<p>L’<b>adjectif épithète</b> (ou groupe adjectival) est placé à côté du nom, avant ou après lui, et s’accorde avec lui : « une <b>vieille</b> maison <b>abandonnée</b> ».</p><p>Le <b>complément du nom</b> est le plus souvent un <b>groupe nominal prépositionnel</b> : préposition (de, à, en, sans…) + GN : « une maison <b>de pierre</b> », « une robe <b>à fleurs</b> », « un chalet <b>en bois</b> ».</p><p>Ne pas confondre l’épithète (dans le GN : « ces <b>petits</b> chiens ») et l’attribut du sujet (après un verbe attributif : « ces chiens sont <b>petits</b> »).</p>`)],
  [{q:'Dans « la grande maison de pierre », quel est le noyau et quelles sont les expansions ?',s:['Je supprime ce qui peut l’être : il reste « la maison ».','Noyau : « maison » ; déterminant : « la ».','« grande » : adjectif épithète ; « de pierre » : groupe nominal prépositionnel complément du nom.','Attention : « pierre » est un nom, mais il appartient à l’expansion ; ce n’est pas le noyau.']}],
  ['Je trouve le nom noyau en supprimant les expansions.','Je repère le déterminant.','Je nomme chaque expansion : adjectif épithète ou complément du nom (préposition + GN).'],
  ['Prendre le dernier nom du groupe pour le noyau (« pierre » dans « la maison de pierre »).','Confondre adjectif épithète et attribut du sujet.','Oublier d’accorder l’épithète avec le nom noyau.'],
  ['Noyau = nom principal ; il commande les accords.','Adjectif épithète et complément du nom sont des expansions supprimables.','Complément du nom = préposition + groupe nominal.']),
 g:(()=>{
  const GN=[{n:'maison',g:'f',pre:['petite','grande','vieille','belle'],post:['abandonnée','blanche','ancienne','mystérieuse'],cdn:[['de pierre','pierre'],['de mon grand-père','grand-père'],['en bois','bois'],['au toit rouge','toit']]},
   {n:'château',g:'m',pre:['vieux','grand','beau','petit'],post:['abandonné','immense','hanté','médiéval'],cdn:[['du roi','roi'],['de sable','sable'],['aux tours pointues','tours'],['en ruine','ruine']]},
   {n:'robe',g:'f',pre:['jolie','longue','belle','petite'],post:['bleue','élégante','légère'],cdn:[['de soirée','soirée'],['en soie','soie'],['à fleurs','fleurs'],['de ma tante','tante']]},
   {n:'chien',g:'m',pre:['gros','petit','vieux'],post:['noir','fidèle','joueur'],cdn:[['de berger','berger'],['du voisin','voisin'],['à poils longs','poils']]},
   {n:'bateau',g:'m',pre:['petit','vieux','grand'],post:['rapide','blanc','solide'],cdn:[['de pêche','pêche'],['à voiles','voiles'],['du capitaine','capitaine']]},
   {n:'forêt',g:'f',pre:['grande','vieille'],post:['sombre','profonde','enchantée'],cdn:[['de sapins','sapins'],['du conte','conte'],['de Brocéliande','Brocéliande']]},
   {n:'livre',g:'m',pre:['gros','petit','beau'],post:['passionnant','ancien','illustré'],cdn:[['de contes','contes'],['de cuisine','cuisine'],['à la couverture rouge','couverture']]},
   {n:'jardin',g:'m',pre:['petit','grand','joli'],post:['fleuri','secret','ombragé'],cdn:[['de ma grand-mère','grand-mère'],['aux roses','roses'],['du château','château']]}];
  const build=d=>{const N=P(GN);const det=N.g==='f'?P(['la','une','cette']):P(['le','un','ce']);const nb=d===1?1:d===2?R(1,2):R(2,3);const k=pickN(['pre','post','cdn'],nb);
    const pre=k.includes('pre')?P(N.pre):null,post=k.includes('post')?P(N.post):null,cdn=k.includes('cdn')?P(N.cdn):null;
    return {N,det,pre,post,cdn,nb,gn:[det,pre,N.n,post,cdn&&cdn[0]].filter(Boolean).join(' ')};};
  const gNoy=d=>{const x=build(d);return ch(`Quel est le nom noyau du groupe nominal « ${x.gn} » ?`,x.N.n,[x.cdn?x.cdn[1]:null,x.pre||x.post,x.det,x.post&&x.pre?x.post:null].filter(Boolean),{expl:`En supprimant les expansions, il reste « ${x.det} ${x.N.n} » : le noyau est <b>${x.N.n}</b>.`,hint:'Supprime ce qui peut l’être.'});};
  const FN=['adjectif épithète','complément du nom','attribut du sujet','noyau du groupe nominal'];
  const gFn=d=>{const x=build(Math.max(d,2));const opts=[x.pre&&[x.pre,'adjectif épithète'],x.post&&[x.post,'adjectif épithète'],x.cdn&&[x.cdn[0],'complément du nom']].filter(Boolean);const [w,a]=P(opts);
    return ch(`Dans le groupe nominal « ${x.gn} », quelle est la fonction de « ${w} » ?`,a,FN.filter(y=>y!==a),{expl:a==='adjectif épithète'?`« ${w} » est un adjectif placé à côté du nom « ${x.N.n} » et accordé avec lui : <b>adjectif épithète</b>.`:`« ${w} » commence par une préposition et complète le nom « ${x.N.n} » : <b>complément du nom</b> (groupe nominal prépositionnel).`,hint:'Adjectif collé au nom, ou préposition + nom ?'});};
  const gNb=d=>{const x=build(d);return num(`Combien d’expansions du nom (adjectifs épithètes et compléments du nom) compte le groupe nominal « ${x.gn} » ?`,x.nb,{expl:`Expansions : ${[x.pre,x.post,x.cdn&&x.cdn[0]].filter(Boolean).map(s=>'« '+s+' »').join(', ')} → <b>${x.nb}</b>. Le déterminant n’est pas une expansion.`,hint:'Ne compte ni le déterminant ni le noyau.'});};
  const gRed=d=>{const x=build(Math.max(d,2));const g=`${x.det} ${x.N.n}`;return ch(`Réduis le groupe nominal à son minimum (déterminant + nom noyau) : « ${x.gn} »`,g,[x.cdn?`${x.det} ${x.cdn[1]}`:`${x.det} ${x.N.g==='f'?'jolie':'grand'} ${x.N.n}`,x.N.n,x.pre?`${x.det} ${x.pre} ${x.N.n}`:`${x.det} ${x.N.n} ${x.post||P(x.N.post)}`],{expl:`On supprime toutes les expansions : <b>${g}</b>`,hint:'Garde le déterminant et le nom principal.'});};
  const B=bank([['Dans « Ces petits chiens sont mignons », quelle est la fonction de « petits » ?','adjectif épithète',['attribut du sujet','complément du nom','COD'],'« petits » est dans le groupe nominal, à côté du nom.'],
   ['Dans « Ces petits chiens sont mignons », quelle est la fonction de « mignons » ?','attribut du sujet',['adjectif épithète','complément du nom','COD'],'« mignons » est relié au sujet par le verbe attributif « sont ».',2],
   ['Quelle est la nature de « de pierre » dans « un mur de pierre » ?','un groupe nominal prépositionnel',['un adjectif','un adverbe','un verbe'],'Préposition « de » + nom « pierre ».',2],
   ['Quel groupe contient un complément du nom ?','une tasse à café',['une tasse brisée','une grande tasse','cette tasse'],'« à café » : préposition + nom.'],
   ['Quel groupe contient un adjectif épithète ?','un ciel orageux',['un ciel de traîne','le ciel','ce ciel d’été'],'« orageux » est un adjectif placé à côté du nom.'],
   ['Dans « la porte du garage », quel est le noyau ?','porte',['garage','la','du'],'« du garage » complète « porte » : c’est un complément du nom.'],
   ['Dans « Le ciel devient gris », « gris » est…','attribut du sujet',['adjectif épithète','complément du nom','COD'],'Après le verbe attributif « devient ».',3]]);
  return mix([gNoy,3],[gFn,3],[gNb,1],[gRed,1],[B,2]);})()},

{id:'fr6m',name:'Pronoms personnels et antécédents',icon:'🔁',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Identifier aisément les pronoms personnels et préciser leur fonction ; mettre en relation un pronom personnel avec son antécédent »',GRAM],
 tip:'Pour trouver l’antécédent, remplace le pronom par le nom que tu proposes : si la phrase garde son sens (et le bon genre, le bon nombre), tu as trouvé.',
 c:C(`« Les filles voient Tom. Elles le saluent. » Qui salue qui ? Les petits mots « elles » et « le » renvoient à des personnages déjà nommés : ce sont des <b>pronoms</b>. Bien les comprendre évite de mal lire… et de mal écrire.`,
  [T('Le pronom et son antécédent',`<p>Le <b>pronom</b> remplace ou reprend un nom ou un groupe nominal pour éviter une répétition. Le mot ou le groupe repris s’appelle l’<b>antécédent</b>.</p><p>« Mon père a acheté <b>une voiture</b>. Il <b>la</b> conduit prudemment. » → « la » a pour antécédent « une voiture » ; « Il » a pour antécédent « mon père ». Le pronom prend en général le <b>genre</b> et le <b>nombre</b> de son antécédent.</p><p>Les pronoms « je, tu, nous, vous » désignent les personnes qui parlent ou à qui l’on parle : ils n’ont pas d’antécédent dans le texte.</p>`),
   T('Formes et fonctions des pronoms personnels',`<table class="ptable"><tr><th>Fonction</th><th>Pronoms</th><th>Exemple</th></tr><tr><td>sujet</td><td>je, tu, il, elle, on, nous, vous, ils, elles</td><td><b>Elles</b> chantent.</td></tr><tr><td>COD</td><td>me, te, le, la, les, nous, vous</td><td>Je <b>les</b> regarde.</td></tr><tr><td>COI</td><td>me, te, lui, nous, vous, leur</td><td>Je <b>lui</b> parle. Je <b>leur</b> écris.</td></tr></table><p>Le pronom complément se place <b>devant le verbe</b> : « Je regarde les oiseaux » → « Je <b>les</b> regarde ». « leur » pronom (devant un verbe) est <b>invariable</b> : « Je leur parle ».</p>`)],
  [{q:'« Tom a prêté ses feutres à Léa. Elle les lui rendra demain. » Que reprennent « Elle », « les » et « lui » ?',s:['« Elle » est sujet et féminin singulier : il reprend « Léa ».','« les » est COD et pluriel : il reprend « ses feutres ».','« lui » est COI (rendre à quelqu’un) : il reprend « Tom », le propriétaire des feutres.','Vérification : « Léa rendra les feutres à Tom demain » garde le sens.']}],
  ['Je repère le pronom et sa fonction (sujet, COD, COI).','Je cherche dans les phrases précédentes un nom ou un groupe de même genre et de même nombre.','Je remplace le pronom par l’antécédent proposé pour vérifier que le sens est cohérent.'],
  ['Choisir comme antécédent le nom le plus proche sans vérifier le sens.','Écrire « leurs » devant un verbe : le pronom « leur » est invariable.','Confondre « le, la, les » pronoms (devant un verbe) et déterminants (devant un nom).'],
  ['Pronom = mot de reprise ; antécédent = élément repris.','le, la, les : COD ; lui, leur : COI.','Genre, nombre et sens permettent de vérifier l’antécédent.']),
 g:(()=>{
  const A=onText([
   ['Les filles voient Tom. Elles le saluent.',[['Que reprend « Elles » ?','les filles',['Tom','les saluts','on ne sait pas'],'« Elles » est féminin pluriel, comme « les filles ».'],['Que reprend « le » ?','Tom',['les filles','le salut','un inconnu'],'« le » est masculin singulier et COD : il reprend Tom.']]],
   ['Mon père a acheté une voiture. Il la conduit prudemment.',[['Que reprend « la » ?','une voiture',['mon père','la route','la prudence'],'« la » est féminin singulier et COD du verbe « conduit ».'],['Que reprend « Il » ?','mon père',['une voiture','le garage','le vendeur'],'C’est le père qui conduit.']]],
   ['Le loup aperçut l’agneau. Il s’approcha de lui en silence.',[['Que reprend « lui » ?','l’agneau',['le loup','le silence','le berger'],'Le loup s’approche de l’agneau.'],['Que reprend « Il » ?','le loup',['l’agneau','le silence','le ruisseau'],'C’est le loup qui s’approche.',2]]],
   ['Les enfants ont écrit à leur grand-mère. Ils lui racontent leurs vacances.',[['Que reprend « lui » ?','leur grand-mère',['les enfants','les vacances','la lettre'],'On raconte quelque chose à quelqu’un : « lui » = à leur grand-mère.',2],['Que reprend « Ils » ?','les enfants',['les vacances','leur grand-mère','les parents'],'« Ils » est masculin pluriel et sujet.']]],
   ['Le chat de ma voisine a disparu. Elle le cherche partout.',[['Que reprend « Elle » ?','ma voisine',['le chat','la maison','on ne sait pas'],'Seule « ma voisine » est féminin singulier et peut chercher.',2],['Que reprend « le » ?','le chat',['ma voisine','le quartier','le chien'],'On cherche le chat disparu : le nom le plus proche (« voisine ») n’est pas le bon.',2]]],
   ['Le capitaine appela les marins et leur donna ses ordres.',[['Que reprend « leur » ?','les marins',['le capitaine','les ordres','le navire'],'Il donne ses ordres aux marins : « leur » = à eux.',2]]],
   ['Julie a invité Paul et Sami. Elle les attend avec impatience.',[['Que reprend « les » ?','Paul et Sami',['Julie','l’impatience','les invitations'],'« les » est COD pluriel : il reprend les deux garçons invités.']]],
   ['Quand Inès a vu son frère sur le quai, elle a couru vers lui.',[['Que reprend « lui » ?','son frère',['Inès','le quai','le train'],'Inès court vers son frère.',3],['Que reprend « elle » ?','Inès',['son frère','la gare','la foule'],'C’est Inès qui court.']]],
   ['Les hirondelles reviennent au printemps. Nous les observons depuis la fenêtre.',[['Que reprend « les » ?','les hirondelles',['nous','le printemps','les fenêtres'],'On observe les hirondelles.'],['« Nous » a-t-il un antécédent dans le texte ?','Non : il désigne la personne qui parle et d’autres personnes.',['Oui : les hirondelles.','Oui : le printemps.','Oui : la fenêtre.'],'Les pronoms de 1re et 2e personne désignent les interlocuteurs.',3]]]],{hint:'Remplace le pronom par le nom proposé et vérifie le sens.'});
  const F=tagged([['Je [[le]] vois tous les jours.','COD'],['Je [[lui]] parle souvent.','COI'],['Elle [[les]] écoute attentivement.','COD'],['Nous [[leur]] écrivons une lettre.','COI'],['Il [[me]] regarde en souriant.','COD',null,2],['Tu [[nous]] téléphones ce soir.','COI','On téléphone à quelqu’un : « nous » est COI.',3],['[[Ils]] chantent sous la pluie.','sujet'],['Le chef [[les]] félicite.','COD'],['Cette histoire [[lui]] plaît.','COI','Quelque chose plaît à quelqu’un : COI.',2],['[[Elle]] range ses affaires.','sujet'],['Le professeur [[la]] corrige.','COD']],['sujet','COD','COI'],{q:'Quelle est la fonction du pronom en gras ?<br>« %p »',e:a=>a==='sujet'?'Le pronom commande l’accord du verbe : <b>sujet</b>.':a==='COD'?'Le pronom complète le verbe sans préposition (on regarde quelqu’un / quelque chose) : <b>COD</b>.':'Le pronom remplace un complément introduit par « à » : <b>COI</b>.',hint:'Le verbe se construit-il avec « à » ?'});
  const RP=bank([['Remplace le groupe en gras par un pronom : « Je regarde <b>les oiseaux</b>. »','Je les regarde.',['Je leur regarde.','Je regarde les.','Je lui regarde.'],'COD pluriel → « les », placé devant le verbe.'],
   ['Remplace le groupe en gras par un pronom : « Nous parlons <b>à notre professeur</b>. »','Nous lui parlons.',['Nous le parlons.','Nous leur parlons.','Nous parlons lui.'],'COI singulier introduit par « à » → « lui ».'],
   ['Remplace le groupe en gras par un pronom : « Elle appelle <b>sa sœur</b>. »','Elle l’appelle.',['Elle lui appelle.','Elle la appelle.','Elle appelle la.'],'COD féminin singulier → « la », qui devient « l’ » devant une voyelle.'],
   ['Remplace le groupe en gras par un pronom : « Tu écris <b>à tes cousins</b>. »','Tu leur écris.',['Tu leurs écris.','Tu les écris.','Tu lui écris.'],'COI pluriel → « leur », invariable devant un verbe.',2],
   ['Remplace le groupe en gras par un pronom : « <b>Mes parents</b> préparent le repas. »','Ils préparent le repas.',['Eux préparent le repas.','Les préparent le repas.','Leur préparent le repas.'],'Sujet masculin pluriel → « ils ».'],
   ['Remplace le groupe en gras par un pronom : « Le guide montre la grotte <b>aux visiteurs</b>. »','Le guide leur montre la grotte.',['Le guide les montre la grotte.','Le guide lui montre la grotte.','Le guide leurs montre la grotte.'],'COI pluriel → « leur ».',3],
   ['Dans « Je leur donne du pain », « leur » est…','un pronom personnel, invariable',['un déterminant possessif','un nom','un adjectif'],'Placé devant le verbe, « leur » est un pronom et ne prend jamais de « s ».',2]]);
  return mix([A,5],[F,3],[RP,2]);})()},

{id:'fr6n',name:'Phrase simple, phrase complexe et propositions',icon:'🔗',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Se repérer dans la phrase complexe » : notion de proposition, phrase simple et phrase complexe',GRAM+' : la phrase et la proposition'],
 tip:'Souligne les verbes conjugués (pas les infinitifs ni les participes seuls) : autant de verbes conjugués, autant de propositions.',
 c:C(`« Le chat dort. » « Le chat dort pendant que les souris dansent. » La seconde phrase raconte deux actions avec deux verbes conjugués. Pour savoir si une phrase est <b>simple</b> ou <b>complexe</b>, on compte ses <b>propositions</b>.`,
  [T('Proposition, phrase simple, phrase complexe',`<p>Une <b>proposition</b> est un ensemble de mots organisé autour d’un <b>verbe conjugué</b> (avec, en général, son sujet).</p><p>Une <b>phrase simple</b> contient <b>une seule</b> proposition : « Les feuilles tombent en automne. » Une <b>phrase complexe</b> en contient <b>plusieurs</b> : « Les feuilles tombent et le vent les emporte. »</p><p>Un temps composé (« nous <b>avons visité</b> ») compte pour <b>un seul</b> verbe conjugué : auxiliaire + participe passé.</p>`),
   T('Ce qui n’est pas un verbe conjugué',`<p>Les <b>infinitifs</b> (« apprendre à <b>nager</b> », « <b>Lire</b> fait rêver ») et les <b>participes</b> employés seuls (« Le randonneur, <b>épuisé</b> par la montée, s’assoit ») ne forment pas de proposition.</p><p>Exemple : « Je voudrais apprendre à nager. » → un seul verbe conjugué (« voudrais ») : phrase simple.</p>`)],
  [{q:'« Quand le soleil se couche, les chauves-souris sortent et chassent. » Simple ou complexe ?',s:['Je souligne les verbes conjugués : « se couche », « sortent », « chassent ».','Trois verbes conjugués = trois propositions.','C’est une phrase complexe.']}],
  ['J’encadre les verbes conjugués (je vérifie qu’ils ont un sujet et varient avec le temps).','Je compte les noyaux verbaux, sans les infinitifs ni les participes seuls.','J’en déduis le nombre de propositions et je délimite chacune d’elles.'],
  ['Compter les infinitifs comme des verbes conjugués.','Compter deux verbes pour un temps composé (« a trouvé » = un seul verbe conjugué).','Croire qu’une phrase longue est forcément complexe.'],
  ['1 verbe conjugué = 1 proposition.','Phrase simple = 1 proposition ; phrase complexe = plusieurs.','Infinitifs et participes seuls ne comptent pas.']),
 g:(()=>{
  const L=[['Le chat dort sur le canapé.',['dort']],['Il pleut, je prends mon parapluie.',['pleut','prends']],['Le soleil se couche et les oiseaux rentrent au nid.',['se couche','rentrent']],['Je voudrais apprendre à nager.',['voudrais'],2],['Elle ouvre la porte, regarde dehors et sourit.',['ouvre','regarde','sourit'],2],['Quand la nuit tombe, les chouettes sortent.',['tombe','sortent']],['Les enfants aiment jouer dans le jardin.',['aiment'],2],['Nous avons visité le château de Chambord.',['avons visité'],2],['Le randonneur, épuisé par la montée, s’assoit sur un rocher.',['s’assoit'],3],['J’ai fini mes devoirs, mais je n’ai pas rangé ma chambre.',['ai fini','ai rangé'],3],['Mon frère lit pendant que ma sœur dessine.',['lit','dessine']],['Le marin observe le ciel, car une tempête approche.',['observe','approche']],['Pour réussir, il faut travailler régulièrement.',['faut'],3],['Le professeur explique la leçon ; les élèves prennent des notes.',['explique','prennent'],2],['Tom court, saute, plonge et nage jusqu’à la bouée.',['court','saute','plonge','nage'],3],['Je pense que tu as raison.',['pense','as'],2],['Les feuilles tombent en automne.',['tombent']],['Après le repas, nous irons nous promener au bord du lac.',['irons'],3],['Le chien aboie dès qu’un inconnu s’approche de la maison.',['aboie','s’approche'],2],['Elle a trouvé une vieille carte et elle l’a montrée à ses amis.',['a trouvé','a montrée'],3],['Lire des contes fait rêver les enfants.',['fait'],3],['Le train partira à midi.',['partira']],['Si tu viens demain, nous jouerons aux échecs.',['viens','jouerons'],2],['Les vagues frappaient la coque, le vent hurlait et les marins priaient.',['frappaient','hurlait','priaient'],2],['Au loin brillaient les lumières du port.',['brillaient'],2]];
  const lst=v=>v.map(x=>'« '+x+' »').join(', ');
  const gN=d=>{const [s,v]=lvPick(L,d,2);return num(`Combien de propositions la phrase « ${s} » contient-elle ?`,v.length,{expl:`Verbe${v.length>1?'s':''} conjugué${v.length>1?'s':''} : ${lst(v)} → <b>${v.length} proposition${v.length>1?'s':''}</b>.${/(nager|jouer|réussir|travailler|promener|Lire|rêver|épuisé)/.test(s)?' Les infinitifs et les participes employés seuls ne comptent pas.':''}`,hint:'Compte uniquement les verbes conjugués.'});};
  const gS=d=>{const [s,v]=lvPick(L,d,2);const a=v.length>1?'une phrase complexe':'une phrase simple';return ch(`« ${s} » est…`,a,['une phrase simple','une phrase complexe','une phrase sans verbe'].filter(x=>x!==a),{expl:`${v.length} verbe${v.length>1?'s':''} conjugué${v.length>1?'s':''} (${lst(v)}) : <b>${a}</b>.`,hint:'Compte les verbes conjugués.'});};
  const gV=d=>{const [s,v]=lvPick(L.filter(x=>x[1].length>1||x[2]>=2),d,2);const good=v.join(' / ');const bad=[];const w=s.replace(/[.,;]/g,'').split(' ');
    bad.push(v.slice(0,-1).join(' / ')||w[0]);bad.push([...v,w[w.length-1]].join(' / '));bad.push(w.slice(0,2).join(' / '));
    return ch(`Quels sont les verbes conjugués de la phrase « ${s} » ?`,good,bad,{expl:`Verbes conjugués : <b>${good}</b>.`,hint:'Un verbe conjugué change si l’on change le temps ou la personne.'});};
  const B=bank([['Une proposition s’organise autour…','d’un verbe conjugué',['d’un nom propre','d’un adjectif','d’une virgule'],'Le verbe conjugué est le noyau de la proposition.'],
   ['« Nous avons visité » compte pour…','un seul verbe conjugué (auxiliaire + participe passé)',['deux verbes conjugués','aucun verbe conjugué','trois propositions'],'Un temps composé forme un seul noyau verbal.',2],
   ['Dans « Il aime chanter », combien de verbes conjugués ?','un seul : « aime »',['deux : « aime » et « chanter »','aucun','trois'],'« chanter » est à l’infinitif.']]);
  return mix([gN,4],[gS,2],[gV,2],[B,1]);})()},

{id:'fr6o',name:'Juxtaposition, coordination et subordination',icon:'🧷',domain:'Grammaire et orthographe grammaticale',
 refs:[REF+' — « Approfondir les notions de juxtaposition, de coordination, de subordination ; distinguer le rôle de la conjonction de coordination et celui de la conjonction de subordination »',GRAM],
 tip:'Regarde ce qui sépare les deux propositions : un signe de ponctuation seul (juxtaposition), mais/ou/et/or/ni/car (coordination), ou un mot comme quand, parce que, si, que (subordination).',
 c:C(`« Il pleut, je reste. » « Je reste, car il pleut. » « Je reste parce qu’il pleut. » Trois phrases, un même sens, trois constructions différentes. Pour relier deux propositions, on peut utiliser une <b>ponctuation</b>, une <b>conjonction de coordination</b> ou une <b>conjonction de subordination</b>.`,
  [T('Trois façons de relier des propositions',`<ul class="lst"><li><b>Juxtaposition</b> : les propositions sont séparées par un signe de ponctuation (virgule, point-virgule, deux-points), sans mot de liaison. « Je reste à la maison : il pleut. »</li><li><b>Coordination</b> : elles sont reliées par une <b>conjonction de coordination</b> (mais, ou, et, or, ni, car). Elles restent indépendantes. « Je reste à la maison, car il pleut. »</li><li><b>Subordination</b> : une proposition <b>subordonnée</b>, introduite par une <b>conjonction de subordination</b> (quand, lorsque, parce que, puisque, si, que…), dépend d’une proposition <b>principale</b>. « Je reste à la maison parce qu’il pleut. »</li></ul>`),
   T('Le sens du lien',`<p>Les conjonctions expriment un rapport logique : <b>et</b> (addition, succession), <b>ou</b> (choix), <b>mais, or</b> (opposition), <b>car</b> (cause), <b>ni</b> (négation de plusieurs éléments) ; <b>quand, lorsque</b> (temps) ; <b>parce que, puisque</b> (cause).</p><p>Dans la juxtaposition, le lien n’est pas dit : c’est au lecteur de le comprendre (« Il pleut, je reste » : cause). « Donc » est un <b>adverbe</b> selon la terminologie officielle : il exprime la conséquence mais ne fait pas partie des six conjonctions de coordination.</p>`)],
  [{q:'« Il pleut, je prends mon parapluie. » Quel lien entre les propositions ?',s:['Deux verbes conjugués : « pleut » et « prends » → deux propositions.','Elles sont séparées par une virgule, sans mot de liaison : elles sont juxtaposées.','Le sens suggère un rapport de cause : je prends mon parapluie parce qu’il pleut.']}],
  ['Je repère les verbes conjugués et la frontière entre les propositions.','Je cherche le signe ou le mot de liaison.','Je nomme le lien (juxtaposition, coordination, subordination) et j’explique le rapport de sens.'],
  ['Croire qu’une virgule signifie toujours coordination.','Confondre « car » (conjonction de coordination) et « parce que » (conjonction de subordination), qui ont pourtant le même sens.','Oublier l’élision devant une voyelle : on écrit « parce qu’il », « parce qu’elle ».'],
  ['Juxtaposition = ponctuation seule.','Coordination = mais, ou, et, or, ni, car.','Subordination = proposition dépendante introduite par un subordonnant (quand, parce que, si…).']),
 g:(()=>{
  const CAU=[['Je reste à la maison','il pleut'],['Le match est reporté','le terrain est inondé'],['Léa met son manteau','il fait froid'],['Le chien aboie','il entend un bruit'],['Tom est fatigué','il s’est couché tard'],['Nous rentrons vite','l’orage approche'],['La route est fermée','des arbres sont tombés'],['Inès sourit','elle a réussi son contrôle']];
  const TPS=[['les oiseaux chantent','le soleil se lève'],['nous rentrons en classe','la cloche sonne'],['les chouettes sortent','la nuit tombe'],['le public applaudit','le rideau se ferme'],['les enfants courent dehors','la pluie s’arrête']];
  const OPP=[['Il fait froid','nous sortons quand même'],['Le chemin était long','personne ne se plaignait'],['Tom a beaucoup révisé','il a oublié une règle'],['La mer est agitée','le pêcheur part en mer']];
  const que=s=>VOW.test(s)?'qu’'+s:'que '+s;
  const LAB=['juxtaposées','coordonnées','subordonnées (une principale et une subordonnée)'];
  const make=()=>{const f=P(['c','c','t','o']);
    if(f==='c'){const [a,b]=P(CAU);return P([{s:`${a} : ${b}.`,k:0,w:null,r:'la cause'},{s:`${a}, car ${b}.`,k:1,w:'car',r:'la cause'},{s:`${a} parce ${que(b)}.`,k:2,w:'parce que',r:'la cause'}]);}
    if(f==='t'){const [m,s]=P(TPS);return P([{s:`${cap(s)}, ${m}.`,k:0,w:null,r:'le temps'},{s:`${cap(s)} et ${m}.`,k:1,w:'et',r:'le temps'},{s:`${cap(m)} quand ${s}.`,k:2,w:'quand',r:'le temps'}]);}
    const [a,b]=P(OPP);return P([{s:`${a} ; ${b}.`,k:0,w:null,r:'l’opposition'},{s:`${a}, mais ${b}.`,k:1,w:'mais',r:'l’opposition'}]);};
  const EK=['Elles sont séparées par un signe de ponctuation, sans mot de liaison.','Elles sont reliées par une conjonction de coordination.','L’une, introduite par une conjonction de subordination, dépend de l’autre.'];
  const gL=d=>{const x=make();return ch(`Dans « ${x.s} », comment les propositions sont-elles reliées ?`,LAB[x.k],LAB.filter((_,j)=>j!==x.k),{expl:`${EK[x.k]}${x.w?' Mot de liaison : « '+x.w+' ».':''} Elles sont <b>${LAB[x.k]}</b>.`,hint:'Y a-t-il un mot de liaison ? Lequel ?'});};
  const gW=d=>{let x=make();for(let k=0;k<10&&!x.w;k++)x=make();if(!x.w)x={s:'Je reste à la maison, car il pleut.',k:1,w:'car'};const a=x.k===1?'une conjonction de coordination':'une conjonction de subordination';
    return ch(`Dans « ${x.s} », quelle est la classe du mot de liaison « ${x.w} » ?`,a,['une conjonction de coordination','une conjonction de subordination','une préposition','un adverbe'].filter(y=>y!==a),{expl:x.k===1?`« ${x.w} » fait partie des six conjonctions de coordination (mais, ou, et, or, ni, car) : <b>${a}</b>.`:`« ${x.w} » introduit une proposition subordonnée : <b>${a}</b>.`,hint:'Mais, ou, et, or, ni, car : coordination.'});};
  const gR=d=>{const x=make();return ch(`Quel rapport de sens unit les propositions de la phrase « ${x.s} » ?`,x.r,['la cause','le temps','l’opposition','le choix'].filter(y=>y!==x.r),{expl:`Le rapport exprimé est <b>${x.r}</b>${x.w?' (mot de liaison « '+x.w+' »)':' : il n’est pas dit par un mot, on le déduit du sens'}.`,hint:'Pose-toi la question : pourquoi ? quand ? malgré quoi ?'});};
  const gT=d=>{const [a,b]=P(CAU);const g=`${a} parce ${que(b)}.`;return ch(`Relie par <b>subordination</b> les propositions « ${a} » et « ${b} ».`,g,[`${a}, car ${b}.`,`${a} : ${b}.`,`${a}, mais ${b}.`],{expl:`La conjonction de subordination « parce que » introduit la cause : <b>${g}</b>`,hint:'Il faut un subordonnant (parce que, quand, si…).'});};
  const B=bank([['Quelles sont les conjonctions de coordination selon la terminologie officielle ?','mais, ou, et, or, ni, car',['mais, ou, et, donc, or, ni, car, quand','quand, lorsque, si, que','avec, sans, pour, dans'],'Six conjonctions de coordination ; « donc » est classé parmi les adverbes.'],
   ['« car » et « parce que » ont le même sens. Quelle est leur différence ?','« car » coordonne deux propositions indépendantes ; « parce que » introduit une subordonnée.',['Il n’y en a aucune.','« car » est une préposition.','« parce que » ne peut jamais commencer une phrase.'],'Même rapport de cause, construction différente.',2],
   ['Quel mot est une conjonction de subordination ?','lorsque',['mais','ou','car'],'quand, lorsque, parce que, puisque, si, que… introduisent une subordonnée.'],
   ['Dans « Il pleut, je reste », comment appelle-t-on le lien entre les propositions ?','la juxtaposition',['la coordination','la subordination','l’énumération'],'Une simple virgule sépare les propositions.']]);
  return mix([gL,4],[gW,2],[gR,2],[gT,1],[B,1]);})()},

/* ===================== ORTHOGRAPHE GRAMMATICALE ET CONJUGAISON ===================== */
{id:'fr6p',name:'Accords dans le groupe nominal',icon:'✅',domain:'Orthographe grammaticale',
 refs:[REF+' — « Maîtriser la chaîne d’accords dans le groupe nominal, en lien avec l’analyse grammaticale »',GRAM],
 tip:'Trouve d’abord le nom noyau, donne-lui son genre et son nombre, puis fais passer la marque à chaque mot du groupe : déterminant, adjectifs.',
 c:C(`« Des petit cheval noir » ? Il manque des marques partout ! Dans le groupe nominal, le <b>nom noyau</b> donne son genre et son nombre au déterminant et aux adjectifs : c’est la <b>chaîne d’accords</b>.`,
  [T('La chaîne d’accords',`<p>Le nom noyau est le <b>donneur d’accord</b>. Le déterminant et les adjectifs épithètes sont des <b>receveurs</b> : ils prennent son genre (masculin / féminin) et son nombre (singulier / pluriel).</p><p>« un petit cheval noir » → « des petit<b>s</b> chev<b>aux</b> noir<b>s</b> » ; « une petite jument noire » → « des petite<b>s</b> jument<b>s</b> noire<b>s</b> ».</p><p>Le féminin de l’adjectif se forme souvent en ajoutant -e (petit → petite), avec parfois une modification : blanc → blanche, doux → douce, beau → belle, vieux → vieille, gentil → gentille, heureux → heureuse, actif → active, ancien → ancienne, long → longue.</p>`),
   T('Les pluriels particuliers',`<ul class="lst"><li>Noms en <b>-al</b> → <b>-aux</b> (cheval → chevaux, journal → journaux) ; sauf bal, carnaval, chacal, festival, récital, régal (-als).</li><li>Noms en <b>-eau</b>, <b>-au</b>, <b>-eu</b> → <b>-x</b> (bateau → bateaux, jeu → jeux) ; sauf pneu, bleu, landau (-s).</li><li>Noms en <b>-ou</b> → <b>-ous</b> ; sauf bijou, caillou, chou, genou, hibou, joujou, pou (-oux).</li><li>Noms en <b>-ail</b> → <b>-ails</b> ; sauf travail, corail, émail, vitrail, bail, soupirail, vantail (-aux).</li><li>Noms terminés par <b>-s, -x, -z</b> : invariables (souris, voix, nez).</li><li>Adjectifs : -al → -aux (national → nationaux) ; beau → beaux ; les adjectifs en -s ou -x ne changent pas au masculin pluriel (gros, vieux).</li></ul>`)],
  [{q:'Mets au pluriel : « ce petit cheval noir ».',s:['Nom noyau : cheval (masculin singulier) → pluriel en -aux : chevaux.','Déterminant : ce → ces.','Adjectifs : petit → petits ; noir → noirs.','Réponse : « ces petits chevaux noirs ».']}],
  ['Je repère le nom noyau.','Je détermine son genre et son nombre.','Je contrôle chaque déterminant et chaque adjectif qui lui est relié.','Je vérifie les pluriels et les féminins particuliers.'],
  ['Accorder seulement le nom et oublier les autres mots du groupe.','Écrire « des chevals » ou « des bijous » : ces pluriels sont irréguliers.','Accorder l’adjectif avec le nom le plus proche au lieu du noyau (« un pull de laine bleu » : c’est le pull qui est bleu).'],
  ['Le nom noyau est le donneur d’accord.','Déterminant + nom + adjectifs portent les mêmes marques.','-al → -aux ; bijou, caillou, chou, genou, hibou, joujou, pou → -oux.']),
 g:(()=>{
  const A={petit:['petit','petits','petite','petites',1],grand:['grand','grands','grande','grandes',1],noir:['noir','noirs','noire','noires'],blanc:['blanc','blancs','blanche','blanches'],beau:['beau','beaux','belle','belles',1],nouveau:['nouveau','nouveaux','nouvelle','nouvelles',1],vieux:['vieux','vieux','vieille','vieilles',1],gros:['gros','gros','grosse','grosses',1],doux:['doux','doux','douce','douces'],précieux:['précieux','précieux','précieuse','précieuses'],ancien:['ancien','anciens','ancienne','anciennes'],national:['national','nationaux','nationale','nationales'],long:['long','longs','longue','longues',1],rond:['rond','ronds','ronde','rondes'],gris:['gris','gris','grise','grises'],sauvage:['sauvage','sauvages','sauvage','sauvages'],bleu:['bleu','bleus','bleue','bleues'],gentil:['gentil','gentils','gentille','gentilles']};
  const N=[['cheval','chevaux','m',['petit','grand','beau','vieux','blanc','noir','gris','sauvage']],['bijou','bijoux','m',['petit','beau','ancien','précieux']],['hibou','hiboux','m',['petit','gros','vieux','gris','blanc']],['caillou','cailloux','m',['petit','gros','blanc','gris','rond']],['journal','journaux','m',['vieux','ancien','national','gros']],['bateau','bateaux','m',['petit','grand','beau','vieux','blanc','bleu']],['jeu','jeux','m',['nouveau','ancien','beau']],['festival','festivals','m',['grand','nouveau','national']],['chou','choux','m',['gros','beau']],['travail','travaux','m',['long','gros','nouveau']],['clou','clous','m',['petit','gros','long']],['pneu','pneus','m',['gros','vieux','nouveau','noir']],['gâteau','gâteaux','m',['gros','beau','petit','rond']],['nez','nez','m',['petit','gros','long','rond']],['chien','chiens','m',['petit','gros','gentil','noir','vieux']],['souris','souris','f',['petit','gris','blanc']],['voix','voix','f',['doux','beau']],['fleur','fleurs','f',['petit','beau','bleu','blanc','sauvage']],['maison','maisons','f',['grand','vieux','petit','beau','blanc','ancien']],['robe','robes','f',['long','beau','nouveau','bleu','blanc']]];
  const DET={m:[['le','les'],['un','des'],['ce','ces'],['mon','mes']],f:[['la','les'],['une','des'],['cette','ces'],['ma','mes']]};
  const form=(a,g,pl)=>A[a][(g==='f'?2:0)+(pl?1:0)];
  const gn=(dt,n,adjs,g,pl)=>{const pre=adjs.filter(a=>A[a][4]),post=adjs.filter(a=>!A[a][4]);return [dt,...pre.map(a=>form(a,g,pl)),n,...post.map(a=>form(a,g,pl))].join(' ');};
  const pick=d=>{const [s,p,g,L]=P(N);const adjs=pickN(L,d===1?1:R(1,2));const pre=adjs.filter(a=>A[a][4]);if(adjs.length===2&&pre.length!==1)adjs.pop();const dt=P(DET[g]);return {s,p,g,adjs,dt};};
  const gPl=d=>{const x=pick(d);const sg=gn(x.dt[0],x.s,x.adjs,x.g,false),good=gn(x.dt[1],x.p,x.adjs,x.g,true);
    const bad=[gn(x.dt[0],x.p,x.adjs,x.g,true),gn(x.dt[1],x.s,x.adjs,x.g,true),gn(x.dt[1],x.p,x.adjs,x.g,false)];
    if(x.p!==x.s+'s'&&!/[sxz]$/.test(x.s))bad.push(gn(x.dt[1],x.s+'s',x.adjs,x.g,true));
    x.adjs.forEach(a=>{const sgA=form(a,x.g,false),plA=form(a,x.g,true);if(plA!==sgA+'s'&&!/[sx]$/.test(sgA))bad.push(gn(x.dt[1],x.p,x.adjs,x.g,true).replace(plA,sgA+'s'));});
    if(d>=3&&Math.random()<.5)return txt(`Écris au pluriel : « ${sg} »`,[good],{strict:true,lang:'fr',chips:CHIPS,expl:`Nom noyau « ${x.s} » → « ${x.p} » ; le déterminant et les adjectifs s’accordent : <b>${good}</b>.`,hint:'Accorde chaque mot du groupe avec le nom noyau.'});
    return ch(`Mets au pluriel : « ${sg} »`,good,bad,{expl:`Nom noyau « ${x.s} » → « ${x.p} »${x.p===x.s?' (invariable)':''} ; le déterminant et les adjectifs s’accordent : <b>${good}</b>.`,hint:'Accorde chaque mot du groupe avec le nom noyau.'});};
  const gAdj=d=>{const x=pick(d);const a=P(x.adjs);const pl=Math.random()<.6;const dt=pl?x.dt[1]:x.dt[0],n=pl?x.p:x.s;const good=form(a,x.g,pl);
    const ph=A[a][4]?`${dt} (${a}) ${n}`:`${dt} ${n} (${a})`;
    return ch(`Accorde l’adjectif entre parenthèses : « ${ph} »`,good,[A[a][0],A[a][1],A[a][2],A[a][3]],{expl:`« ${n} » est ${x.g==='f'?'féminin':'masculin'} ${pl?'pluriel':'singulier'} : l’adjectif s’écrit <b>${good}</b>.`,hint:'Quel est le genre et le nombre du nom ?'});};
  const B=bank([['Quel est le pluriel de « un bal » ?','des bals',['des baux','des bales','des bal'],'Exception : bal, carnaval, chacal, festival, récital, régal font leur pluriel en -als.',2],
   ['Quel est le pluriel de « un genou » ?','des genoux',['des genous','des genou','des genoues'],'bijou, caillou, chou, genou, hibou, joujou, pou prennent un x.'],
   ['Quel est le pluriel de « un œil » ?','des yeux',['des œils','des œuils','des yeuxs'],'Pluriel très irrégulier à mémoriser.',2],
   ['Quel est le pluriel de « un vitrail » ?','des vitraux',['des vitrails','des vitrailes','des vitrail'],'Comme travail, corail, émail : -aux.',3],
   ['Quel est le pluriel de « un détail » ?','des détails',['des détaux','des détail','des détailx'],'La plupart des noms en -ail prennent un s.',2],
   ['Quel est le pluriel de « un pneu » ?','des pneus',['des pneux','des pneu','des pneues'],'Exception : pneu, bleu, landau prennent un s.',2],
   ['Choisis la bonne orthographe : « des chaussures (marron) »','marron',['marrons','marronnes','marronne'],'Un adjectif de couleur qui vient d’un nom (marron, orange, cerise) reste invariable.',3],
   ['Accorde : « un pull de laine (bleu) »','bleu',['bleue','bleus','bleues'],'C’est le pull (masculin singulier) qui est bleu, pas la laine.',3]]);
  return mix([gPl,4],[gAdj,4],[B,2]);})()},

{id:'fr6q',name:'Accord sujet-verbe',icon:'🤝',domain:'Orthographe grammaticale',
 refs:[REF+' — « Identifier le groupe sujet et raisonner sur l’accord sujet/verbe » ; sujets inversés ; chaîne sujet/attribut',GRAM],
 tip:'Encadre le sujet par « c’est… qui » puis remplace-le par il, elle, ils ou elles : la terminaison du verbe devient évidente.',
 c:C(`« La troupe de musiciens <b>joue</b> » ou « <b>jouent</b> » ? Le mot le plus proche du verbe est « musiciens »… mais ce n’est pas lui qui commande l’accord. Le verbe s’accorde avec le <b>noyau du sujet</b>, même quand il est loin ou placé après lui.`,
  [T('La règle et les pièges',`<p>Le verbe s’accorde en <b>personne</b> et en <b>nombre</b> avec son sujet.</p><ul class="lst"><li><b>Sujet avec complément du nom</b> : « La troupe <i>de musiciens</i> jou<b>e</b> » (noyau : troupe).</li><li><b>Sujet éloigné</b> : « Les touristes, fatigués par la marche, rentr<b>ent</b>. »</li><li><b>Pronom complément devant le verbe</b> : « Le chat <i>les</i> observ<b>e</b> » (sujet : le chat).</li><li><b>Sujet inversé</b> : « Au loin brill<b>aient</b> les lumières du port. »</li><li><b>Plusieurs sujets</b> : « Tom et Léa prépar<b>ent</b>… » ; « Toi et moi finiss<b>ons</b> » (= nous) ; « Ton frère et toi choisiss<b>ez</b> » (= vous).</li><li><b>on</b> se conjugue comme « il ».</li></ul>`),
   T('Sujet et attribut',`<p>L’attribut du sujet s’accorde lui aussi avec le sujet : « Les routes deviennent glissant<b>es</b>. » Si le sujet réunit un nom masculin et un nom féminin, l’accord se fait au <b>masculin pluriel</b> : « Ma tante et mon oncle sont gentil<b>s</b>. »</p>`)],
  [{q:'Choisis : « La troupe de musiciens joue / jouent sur la place. »',s:['Je cherche le sujet : c’est la troupe qui joue.','Le noyau du sujet est « troupe », singulier ; « de musiciens » est un complément du nom.','Je remplace par « elle » : elle joue → « La troupe de musiciens joue sur la place. »']}],
  ['Je repère le verbe conjugué.','Je cherche le sujet avec « c’est… qui » ou « qui est-ce qui ? ».','J’identifie son noyau et je le remplace par un pronom (il, elle, ils, elles, nous, vous).','J’écris la terminaison qui correspond à ce pronom.'],
  ['Accorder le verbe avec le nom le plus proche (« les musiciens » dans « la troupe de musiciens »).','Prendre un pronom complément (le, la, les, leur) pour le sujet.','Oublier le pluriel quand le sujet est inversé.'],
  ['Le verbe s’accorde avec le noyau du sujet.','La distance ou l’inversion ne changent pas la règle.','Toi et moi = nous ; toi et lui = vous ; on = il.']),
 g:(()=>{
  const S=[['La troupe de musiciens (V) sur la place.',2,'jouer','Le noyau du sujet est « troupe » (singulier) ; « de musiciens » est un complément du nom.'],['Le chef des pompiers (V) les consignes.',2,'donner','Le noyau est « chef » (singulier).'],['La boîte de crayons (V) par terre.',2,'tomber','Le noyau est « boîte » (singulier).'],['Le groupe d’élèves (V) le musée.',2,'visiter','Le noyau est « groupe » (singulier).'],['Le chant des oiseaux (V) le village.',2,'réveiller','Le noyau est « chant » (singulier).'],['Les élèves de la classe (V) un spectacle.',5,'préparer','Le noyau est « élèves » (pluriel) ; « de la classe » est un complément du nom.'],['Les fenêtres de la maison (V) au soleil.',5,'briller','Le noyau est « fenêtres » (pluriel).'],['Les amis de mon frère (V) à la gare.',5,'arriver','Le noyau est « amis » (pluriel).'],['Les branches du vieux chêne (V) sous le vent.',5,'plier','Le noyau est « branches » (pluriel).'],
   ['Au loin (V) les lumières du port.',5,'briller','Le sujet est inversé : ce sont « les lumières du port » qui brillent.',2],['Sur la colline (V) de vieux oliviers.',5,'pousser','Sujet inversé : « de vieux oliviers ».',2],['Dans cette cabane (V) un vieux pêcheur.',2,'habiter','Sujet inversé : « un vieux pêcheur ».',2],['Dans le ciel (V) des oiseaux migrateurs.',5,'passer','Sujet inversé : « des oiseaux migrateurs ».',2],['Où (V) tes cousins ?',5,'aller','Dans la question, le sujet « tes cousins » est placé après le verbe.',2],
   ['Ma tante leur (V) une histoire.',2,'raconter','« leur » est un pronom complément : le sujet est « ma tante ».',2],['Mes parents me (V) avec fierté.',5,'regarder','« me » est complément : le sujet est « mes parents ».',2],['Le chat les (V) depuis la fenêtre.',2,'observer','« les » est COD : le sujet est « le chat », singulier.',2],
   ['Tom et Léa (V) le goûter.',5,'préparer','Deux sujets coordonnés : pluriel.'],['Toi et moi (V) ce puzzle.',3,'finir','Toi et moi = nous.',3],['Ton frère et toi (V) le film.',4,'choisir','Ton frère et toi = vous.',3],['On (V) au cinéma ce soir.',2,'aller','« on » se conjugue comme « il ».',2],['Le vent et la pluie (V) les volets.',5,'frapper','Deux sujets : pluriel.'],['Les touristes, épuisés par la longue marche, (V) à l’hôtel.',5,'rentrer','Le sujet « les touristes » est éloigné du verbe.',3],['Chaque matin, les enfants du village (V) le car.',5,'prendre','Le noyau est « enfants » (pluriel).',2]];
  const gA=d=>{const [s,i,v,n]=lvPick(S,d,4);const t=d===1?'pr':P(d===2?['pr','imp']:['pr','imp','fut']);const good=H.conj(v,t,i);
    const bad=[0,1,2,3,4,5].map(k=>H.conj(v,t,k)).filter(x=>x!==good);const opp=H.conj(v,t,i===2?5:2);const bads=[opp,...pickN(bad.filter(x=>x!==opp),2)];
    const q=s.replace('(V)',`(<b>${v}</b>)`);
    if(d===3&&Math.random()<.35)return txt(`Écris le verbe ${H.auT(t)} : « ${q} »`,[good],{strict:true,lang:'fr',chips:CHIPS,expl:`${n} → <b>${good}</b>.`,hint:'Cherche le noyau du sujet.'});
    return ch(`Complète avec le verbe ${H.auT(t)} : « ${q} »`,good,bads,{expl:`${n} → <b>${good}</b>.`,hint:'Cherche le noyau du sujet avec « c’est… qui ».'});};
  const B=bank([['Accorde : « Les routes deviennent (glissant). »','glissantes',['glissants','glissante','glissant'],'L’attribut s’accorde avec le sujet « les routes » (féminin pluriel).',2],
   ['Accorde : « Ma tante et mon oncle sont (gentil). »','gentils',['gentilles','gentil','gentille'],'Masculin + féminin → masculin pluriel.',2],
   ['Accorde : « Ces fleurs semblent (fané). »','fanées',['fané','fanés','fanée'],'« fleurs » : féminin pluriel.',2],
   ['Accorde : « Léa et Zoé paraissent (content). »','contentes',['contents','contente','content'],'Deux noms féminins : féminin pluriel.',3],
   ['Quel est le sujet de « Au fond du jardin poussent des roses » ?','des roses',['le jardin','au fond','poussent'],'Ce sont les roses qui poussent : sujet inversé.',2]]);
  return mix([gA,5],[B,1]);})()},

{id:'fr6r',name:'Présent, imparfait et futur',icon:'⏱️',domain:'Conjugaison et valeurs des temps',
 refs:[REF+' — « Connaître les marques des temps étudiés au CM1 et CM2 ; maîtriser les variations du radical pour certains verbes du 1er groupe »',GRAM],
 tip:'Découpe la forme : radical + marque de temps + marque de personne. Imparfait : -ai- ou -i- (chant-ai-s, chant-i-ons) ; futur : -r- (chante-r-ons).',
 c:C(`« Nous chantons », « nous chantions », « nous chanterons » : une seule lettre ou une syllabe change… et l’action passe du présent au passé, puis au futur. Une forme verbale porte une <b>marque de temps</b> et une <b>marque de personne</b>.`,
  [T('Les terminaisons',`<table class="ptable"><tr><th></th><th>présent</th><th>imparfait</th><th>futur</th></tr><tr><td>je</td><td>chante / finis / prends</td><td>chantais</td><td>chanterai</td></tr><tr><td>tu</td><td>chantes / finis</td><td>chantais</td><td>chanteras</td></tr><tr><td>il, elle, on</td><td>chante / finit</td><td>chantait</td><td>chantera</td></tr><tr><td>nous</td><td>chantons / finissons</td><td>chantions</td><td>chanterons</td></tr><tr><td>vous</td><td>chantez / finissez</td><td>chantiez</td><td>chanterez</td></tr><tr><td>ils, elles</td><td>chantent / finissent</td><td>chantaient</td><td>chanteront</td></tr></table><p><b>Imparfait</b> : marque -ai- ou -i- + personne (-s, -s, -t, -ons, -ez, -ent). <b>Futur</b> : marque -r- (souvent l’infinitif entier) + -ai, -as, -a, -ons, -ez, -ont.</p>`),
   T('Radicaux à connaître',`<p>Verbes irréguliers fréquents : être (je suis, j’étais, je serai), avoir (j’ai, j’avais, j’aurai), aller (je vais, j’allais, j’irai), faire (je fais, nous faisons, vous faites, je ferai), dire (vous dites), venir (je viendrai), pouvoir (je pourrai), voir (je verrai), vouloir (je voudrai), prendre (ils prennent).</p><p>Variations du 1er groupe : manger → nous mang<b>e</b>ons ; commencer → nous commen<b>ç</b>ons ; appeler → j’appe<b>ll</b>e ; jeter → je je<b>tt</b>e ; acheter → j’ach<b>è</b>te ; lever → je l<b>è</b>ve ; nettoyer → je netto<b>i</b>e, je netto<b>i</b>erai.</p>`),
   T('Valeurs des temps',`<p>Le <b>présent</b> exprime ce qui se passe au moment où l’on parle (« Il pleut »), une habitude (« Je me lève à 7 h ») ou une vérité générale (« L’eau bout à 100 °C »). L’<b>imparfait</b> exprime une action passée qui dure, une habitude passée ou une description. Le <b>futur</b> exprime une action à venir.</p>`)],
  [{q:'Conjugue « venir » avec « nous » au futur.',s:['Radical du futur de « venir » : viendr-.','Marque de personne pour « nous » : -ons.','Réponse : « nous viendrons ».']}],
  ['J’identifie l’infinitif, le groupe du verbe et le sujet.','Je choisis le temps selon le sens (maintenant, avant, après).','Je construis radical + marque du temps + marque de personne, en pensant aux radicaux irréguliers.'],
  ['Ajouter une terminaison régulière à un verbe irrégulier (« il venira » au lieu de « il viendra »).','Oublier le « e » ou la cédille : « nous mangons », « nous commencons ».','Confondre « je chanterai » (futur) et « je chantais » (imparfait).'],
  ['Forme verbale = radical + marque de temps + marque de personne.','Imparfait : -ai-/-i- ; futur : -r-.','Les verbes fréquents irréguliers se mémorisent.']),
 g:(()=>{
  const V=[...H.ER,...H.IR2,...Object.keys(H.IRR)];
  const gC=H.conjGen(V,['pr','imp','fut'],{text:.4,textFrom:2});
  const NAME={pr:'présent',imp:'imparfait',fut:'futur'};
  const gId=d=>{for(let k=0;k<20;k++){const v=P(V),t=P(['pr','imp','fut']),i=R(0,5);const f=H.conj(v,t,i);const others=['pr','imp','fut'].filter(x=>x!==t).flatMap(x=>[0,1,2,3,4,5].map(j=>H.conj(v,x,j)));if(others.includes(f))continue;
    const lab=sj(i,f)+f;return ch(`« ${lab} » : à quel temps le verbe <b>${v}</b> est-il conjugué ?`,NAME[t],['présent','imparfait','futur','conditionnel présent'].filter(x=>x!==NAME[t]),{expl:`« ${lab} » est au <b>${NAME[t]}</b>${t==='imp'?' : on reconnaît la marque -ai- ou -i-':t==='fut'?' : on reconnaît la marque -r- suivie de -ai, -as, -a, -ons, -ez, -ont':''}.`,hint:'Cherche la marque de temps.'});}
    return ch('« nous chantions » : à quel temps ?','imparfait',['présent','futur','conditionnel présent'],{expl:'Marque -i- de l’imparfait : nous chant-i-ons.'});};
  const B=bank([['Complète au présent : « Nous (manger) à la cantine. »','mangeons',['mangons','mangeont','mangions'],'On garde le « e » pour conserver le son [ʒ] devant « o ».'],
   ['Complète au présent : « Nous (commencer) la leçon. »','commençons',['commencons','commencont','commenceons'],'La cédille conserve le son [s] devant « o ».'],
   ['Complète au présent : « J’(appeler) mon chien. »','appelle',['appele','apelle','appel'],'appeler double le « l » devant un « e » muet : j’appelle.',2],
   ['Complète au présent : « Je (jeter) les papiers. »','jette',['jete','jète','jettes'],'jeter double le « t » devant un « e » muet.',2],
   ['Complète au présent : « J’(acheter) du pain. »','achète',['achette','achete','achéte'],'acheter prend un accent grave devant un « e » muet.',2],
   ['Complète au présent : « Il (lever) la main. »','lève',['leve','lèvre','lévé'],'lever : e → è devant une syllabe muette.',2],
   ['Complète au futur : « Je (nettoyer) ma chambre. »','nettoierai',['nettoyerai','nettoirai','nettoyrai'],'Les verbes en -oyer changent y en i devant un « e » muet : je nettoierai.',3],
   ['Complète à l’imparfait : « Nous (manger) des crêpes. »','mangions',['mangeions','mangeons','mangiont'],'Devant « i », pas besoin du « e » : nous mangions.',3],
   ['Complète au présent : « Vous (faire) du bruit. »','faites',['faisez','faitent','faisiez'],'Forme irrégulière : vous faites.'],
   ['Complète au présent : « Vous (dire) la vérité. »','dites',['disez','ditent','disiez'],'Forme irrégulière : vous dites.',2],
   ['Complète au futur : « Elle (venir) demain. »','viendra',['venira','viendrai','venait'],'Radical du futur : viendr-.',2],
   ['Complète au futur : « Nous (voir) la mer. »','verrons',['voirons','voyerons','verions'],'Radical du futur : verr-.',2],
   ['« L’eau gèle à 0 °C. » Quelle est la valeur du présent ?','une vérité générale',['une action en cours','une habitude personnelle','un futur proche'],'C’est vrai en tout temps.',3],
   ['« Le dimanche, je fais du vélo. » Quelle est la valeur du présent ?','une habitude',['une vérité générale','une action passée','un ordre'],'L’action se répète.',3],
   ['Dans « nous chanterons », quelle est la marque du futur ?','-r-',['-ons','chant-','-ai-'],'chante-r-ons : -r- marque le futur, -ons la personne.',2]]);
  return mix([gC,5],[gId,2],[B,3]);})()},

{id:'fr6s',name:'Passé composé et plus-que-parfait',icon:'⏮️',domain:'Conjugaison et valeurs des temps',
 refs:[REF+' — « Consolider la maîtrise des temps composés (passé composé et plus-que-parfait) ; accorder le participe passé avec être, et avec le COD (pronom personnel antéposé) pour les verbes conjugués avec avoir »',GRAM],
 tip:'Repère l’auxiliaire : avec être, le participe s’accorde avec le sujet ; avec avoir, il ne s’accorde qu’avec un COD placé avant (souvent l’, la, les).',
 c:C(`« Elle est partie », « Elles ont mangé », « Ces fleurs, je les ai cueillies »… Pourquoi un « e » ici, un « s » là, et rien ailleurs ? Les <b>temps composés</b> suivent des règles précises d’auxiliaire et d’accord.`,
  [T('Former les temps composés',`<p>Un temps composé = <b>auxiliaire</b> (être ou avoir) + <b>participe passé</b>.</p><ul class="lst"><li><b>Passé composé</b> : auxiliaire au présent → j’ai chanté, elle est partie.</li><li><b>Plus-que-parfait</b> : auxiliaire à l’imparfait → j’avais chanté, elle était partie.</li></ul><p>Le plus-que-parfait exprime une action <b>antérieure</b> à une autre action passée : « Quand nous sommes arrivés, le film <b>avait commencé</b>. »</p><p>Participes à connaître : été, eu, allé, fait, dit, venu, pu, vu, voulu, pris, fini, choisi.</p>`),
   T('Être ou avoir ?',`<p>La plupart des verbes se conjuguent avec <b>avoir</b>. Se conjuguent avec <b>être</b> : aller, venir, arriver, partir, entrer, sortir, monter, descendre, tomber, rester, naître, mourir, devenir, rentrer, retourner… et les verbes pronominaux (se lever).</p><p>À la forme négative, la négation encadre l’auxiliaire : « Il <b>n’</b>avait <b>pas</b> compris. »</p>`),
   T('L’accord du participe passé',`<p>Avec <b>être</b> : accord avec le <b>sujet</b>. « Mes cousines sont arrivé<b>es</b>. »</p><p>Avec <b>avoir</b> : pas d’accord avec le sujet. « Elles ont mangé des fraises. » Le participe s’accorde seulement avec le <b>COD placé avant le verbe</b>, par exemple un pronom : « Ces fraises, elles <b>les</b> ont mangé<b>es</b>. » « La tarte, je <b>l’</b>ai préparé<b>e</b>. »</p>`)],
  [{q:'Transforme « Elle termine son travail » au plus-que-parfait.',s:['« terminer » se conjugue avec l’auxiliaire avoir.','Avoir à l’imparfait avec « elle » : avait.','Participe passé : terminé (COD placé après : pas d’accord).','Réponse : « Elle avait terminé son travail. »']}],
  ['Je repère l’auxiliaire : être ou avoir.','Je conjugue l’auxiliaire au bon temps (présent → passé composé ; imparfait → plus-que-parfait).','J’ajoute le participe passé et je vérifie l’accord (sujet avec être ; COD placé avant avec avoir).'],
  ['Accorder le participe passé avec le sujet quand l’auxiliaire est avoir (« elles ont mangées »).','Oublier l’accord avec être (« elles sont arrivé »).','Conjuguer le participe comme un verbe simple (« il a prit »).'],
  ['Temps composé = auxiliaire + participe passé.','Passé composé : auxiliaire au présent ; plus-que-parfait : auxiliaire à l’imparfait.','Être : accord avec le sujet ; avoir : accord avec le COD placé avant.']),
 g:(()=>{
  const V=[...H.ER,...H.IR2,...Object.keys(H.IRR)];
  const gC=H.conjGen(V,['pc','pqp'],{text:.4,textFrom:2});
  const SU=[['Léa','f',2],['Tom','m',2],['Mes cousines','f',5],['Les garçons','m',5],['Elles','f',5],['Ma sœur','f',2],['Nos voisins','m',5],['Les filles','f',5]];
  const VE=[['arriver','en retard'],['tomber','dans la boue'],['rentrer','à la maison'],['rester','au chalet'],['entrer','dans la grotte'],['monter','au grenier'],['aller','au marché'],['venir','à la fête']];
  const agree=(pp,g,pl)=>pp+(g==='f'?'e':'')+(pl?(g==='m'&&pp.endsWith('s')?'':'s'):'');
  const four=pp=>[pp,pp+'e',pp.endsWith('s')?pp:pp+'s',pp+'es'];
  const gE=d=>{const [s,g,i]=P(SU),[v,r]=P(VE);const t=d===1?'pc':P(['pc','pqp']);const aux=t==='pc'?H.IRR['être'].pr[i]:H.imparfait('être')[i];const pp=H.participe(v);const good=agree(pp,g,i===5);
    return ch(`Accorde le participe passé : « ${s} ${aux} (<b>${v}</b>) ${r}. »`,good,four(pp),{expl:`Auxiliaire <b>être</b> : le participe s’accorde avec le sujet « ${s} » (${g==='f'?'féminin':'masculin'} ${i===5?'pluriel':'singulier'}) → <b>${good}</b>.`,hint:'Quel est l’auxiliaire ?'});};
  const CO=[['la lettre','f',0,['apporter','poster','prendre']],['les gâteaux','m',1,['préparer','goûter','apporter']],['les fleurs','f',1,['arroser','apporter','choisir']],['le dessin','m',0,['terminer','finir','montrer','faire']],['ces chansons','f',1,['chanter','écouter','choisir']],['ce film','m',0,['regarder','voir','choisir']],['la porte','f',0,['fermer']],['tes cahiers','m',1,['ranger','prendre','remplir']],['la tarte','f',0,['préparer','faire','goûter','couper']]];
  const SP=[[0,'je'],[1,'tu'],[2,'il'],[2,'elle'],[3,'nous'],[4,'vous'],[5,'ils'],[5,'elles']];
  const gAv=d=>{const [cod,g,pl,vs]=P(CO);const v=P(vs);const [i,lab]=P(SP);const t=P(['pc','pqp']);const A=t==='pc'?H.IRR['avoir'].pr[i]:H.imparfait('avoir')[i];const pp=H.participe(v);
    if(d>=2&&Math.random()<.65){const pr=pl?'les':'l’';const good=agree(pp,g,pl);const s=`${cap(cod)}, ${lab} ${pr}${pl?' ':''}${A} (<b>${v}</b>).`;
      return ch(`Accorde le participe passé : « ${s} »`,good,four(pp),{expl:`Auxiliaire <b>avoir</b>, mais le COD « ${pr} » (= ${cod}) est placé <b>avant</b> le verbe : accord avec lui (${g==='f'?'féminin':'masculin'} ${pl?'pluriel':'singulier'}) → <b>${good}</b>.`,hint:'Cherche un COD placé avant le verbe.'});}
    const sub=(lab==='je')?'j’':lab+' ';return ch(`Accorde le participe passé : « ${cap(sub)}${A} (<b>${v}</b>) ${cod}. »`,pp,four(pp),{expl:`Auxiliaire <b>avoir</b> et COD « ${cod} » placé <b>après</b> le verbe : pas d’accord → <b>${pp}</b>.`,hint:'Avec avoir, on n’accorde jamais avec le sujet.'});};
  const AUX=sort({'auxiliaire être':['aller','venir','partir','tomber','rester','naître','arriver','devenir'],'auxiliaire avoir':['manger','finir','voir','prendre','avoir','être','faire','courir']},{q:'Aux temps composés, le verbe « %s » se conjugue avec…',e:(x,c)=>`Aux temps composés, « ${x} » se conjugue avec l’<b>${c}</b>.`});
  const B=bank([['« Quand nous sommes arrivés, le film avait commencé. » Que montre le plus-que-parfait ?','que le film a commencé avant notre arrivée',['que le film commencera plus tard','que le film commence maintenant','que le film n’a jamais commencé'],'Le plus-que-parfait marque l’antériorité par rapport à une autre action passée.',2],
   ['« Ils avaient fini. » À quel temps est le verbe ?','plus-que-parfait',['passé composé','imparfait','passé simple'],'Auxiliaire avoir à l’imparfait (avaient) + participe passé : plus-que-parfait.'],
   ['« Elle est partie. » À quel temps est le verbe ?','passé composé',['plus-que-parfait','présent','imparfait'],'Auxiliaire être au présent + participe passé : passé composé.'],
   ['Quel est le participe passé de « prendre » ?','pris',['prit','prendu','prie'],'Participe passé : pris (au féminin : prise).'],
   ['Quel est le participe passé de « faire » ?','fait',['fais','fai','faisé'],'Participe passé : fait (féminin : faite).'],
   ['Mets à la forme négative : « Nous avions compris. »','Nous n’avions pas compris.',['Nous n’avions compris pas.','Nous avions pas compris.','Nous ne pas avions compris.'],'La négation encadre l’auxiliaire.',2]]);
  return mix([gC,3],[gE,2],[gAv,3],[AUX,1],[B,1]);})()},

{id:'fr6t',name:'Passé simple et temps du récit',icon:'📚',domain:'Conjugaison et valeurs des temps',
 refs:[REF+' — conjugaisons du passé simple (CM2) ; en 6e : « Initier à la notion de valeurs des temps : des temps du discours, puis des temps du récit »',GRAM],
 tip:'Dans un récit au passé, demande-toi : est-ce le décor, une habitude, une action qui dure (imparfait) ? ou une action brève qui fait avancer l’histoire (passé simple) ?',
 c:C(`« La nuit <b>était</b> calme quand une porte <b>claqua</b>. » Deux temps du passé, deux rôles différents : l’un installe le décor, l’autre fait surgir l’événement. Le <b>passé simple</b> est le temps des actions de premier plan dans les récits écrits.`,
  [T('Les terminaisons du passé simple',`<table class="ptable"><tr><th></th><th>chanter</th><th>finir</th><th>prendre</th><th>vouloir</th><th>venir</th></tr><tr><td>je</td><td>chantai</td><td>finis</td><td>pris</td><td>voulus</td><td>vins</td></tr><tr><td>il, elle</td><td>chant<b>a</b></td><td>fin<b>it</b></td><td>pr<b>it</b></td><td>voul<b>ut</b></td><td>v<b>int</b></td></tr><tr><td>nous</td><td>chantâmes</td><td>finîmes</td><td>prîmes</td><td>voulûmes</td><td>vînmes</td></tr><tr><td>ils, elles</td><td>chant<b>èrent</b></td><td>fin<b>irent</b></td><td>pr<b>irent</b></td><td>voul<b>urent</b></td><td>v<b>inrent</b></td></tr></table><p>Autres : être → il fut, ils furent ; avoir → il eut, ils eurent ; aller → il alla ; faire → il fit ; dire → il dit ; voir → il vit ; pouvoir → il put.</p>`),
   T('Imparfait et passé simple dans le récit',`<p>L’<b>imparfait</b> sert à l’<b>arrière-plan</b> : décor, description, habitude, action en train de se dérouler. Le <b>passé simple</b> sert au <b>premier plan</b> : actions brèves, soudaines, successives, qui font avancer l’histoire. Les mots « soudain », « tout à coup », « alors » annoncent souvent un passé simple.</p><p>Les <b>temps du récit</b> (passé simple, imparfait, plus-que-parfait) racontent des faits coupés du moment présent ; les <b>temps du discours</b> (présent, passé composé, futur) sont liés au moment où l’on parle, comme dans un dialogue ou une lettre.</p>`)],
  [{q:'« La nuit était calme quand une porte claqua. » Explique les temps.',s:['« était » est à l’imparfait : il installe le décor (arrière-plan).','« claqua » est au passé simple : c’est un événement bref et soudain (premier plan).','L’alternance crée une rupture : le calme est brisé par l’événement.']}],
  ['Je repère ce qui constitue le décor ou une habitude (imparfait).','Je repère les actions soudaines ou successives (passé simple).','Je conjugue en vérifiant le groupe du verbe : -a/-èrent ; -it/-irent ; -ut/-urent.'],
  ['Confondre « il chanta » (passé simple) et « il chantait » (imparfait).','Écrire « ils chantèrent » sans accent grave ou « il finit » avec un « t » qui manque (« il fini »).','Croire qu’un temps n’a qu’une seule valeur : c’est le contexte qui décide.'],
  ['Passé simple : premier plan, actions brèves.','Imparfait : arrière-plan, décor, habitude, durée.','1er groupe : il -a, ils -èrent ; 2e groupe : il -it, ils -irent.']),
 g:(()=>{
  const V=[...H.ER,...H.IR2,...Object.keys(H.IRR)];
  const gC=H.conjGen(V,['ps'],{text:.4,textFrom:2});
  const Q=[['Il (faire) nuit noire.','faisait','fit','le décor'],['La pluie (tomber) doucement depuis des heures.','tombait','tomba','une action qui dure'],['Soudain, un cri (déchirer) le silence.','déchira','déchirait','une action soudaine'],['Tout à coup, le chevalier (sortir) son épée.','sortit','sortait','une action soudaine'],['Chaque matin, le berger (conduire) ses moutons au pré.','conduisait','conduisit','une habitude'],['Le château (être) immense et sombre.','était','fut','une description'],['Alors, la princesse (ouvrir) la porte.','ouvrit','ouvrait','une action du premier plan'],['Les oiseaux (chanter) dans les arbres quand l’orage éclata.','chantaient','chantèrent','une action en cours, à l’arrière-plan'],['Le loup (bondir) brusquement sur sa proie.','bondit','bondissait','une action brève'],['À cette époque, les enfants (aller) à l’école à pied.','allaient','allèrent','une habitude'],['Le marin (regarder) la mer quand une voile apparut.','regardait','regarda','une action en cours, à l’arrière-plan'],['Ils (entrer) dans la grotte, (allumer) une torche et (avancer).','entrèrent… allumèrent… avancèrent','entraient… allumaient… avançaient','des actions successives'],['Un vent glacé (souffler) sur la lande.','soufflait','souffla','le décor'],['Brusquement, la porte (s’ouvrir).','s’ouvrit','s’ouvrait','une action soudaine']];
  const gV=d=>{const [p,a,b,why]=P(Q);const isImp=/ai(t|ent)?$|aient$|ait$/.test(a.split('…')[0].trim());return ch(`Choisis le bon temps : « ${p} »`,a,[b],{expl:`Il s’agit d’${why.replace(/^une /,'une ').replace(/^le /,'un élément du ').replace(/^des /,'une série d’')} : ${isImp?'l’imparfait (arrière-plan)':'le passé simple (premier plan)'} → <b>${a}</b>.`,hint:'Décor/habitude ou action brève ?'});};
  const gId=d=>{const v=P(H.ER.filter(x=>x!=='nager')),i=P([2,5]);const t=P(['ps','imp','pr']);const f=H.conj(v,t,i);const lab=(i===2?P(['il','elle']):P(['ils','elles']))+' '+f;const N={ps:'passé simple',imp:'imparfait',pr:'présent'};
    return ch(`« ${lab} » : à quel temps est conjugué le verbe <b>${v}</b> ?`,N[t],['passé simple','imparfait','présent','futur'].filter(x=>x!==N[t]),{expl:`« ${lab} » : <b>${N[t]}</b>${t==='ps'?' (terminaisons -a / -èrent du 1er groupe)':t==='imp'?' (marque -ai- de l’imparfait)':''}.`,hint:'-a/-èrent : passé simple ; -ait/-aient : imparfait.'});};
  const B=bank([['Dans un récit, le passé simple sert surtout à…','raconter les actions brèves qui font avancer l’histoire (premier plan)',['décrire le décor','exprimer une habitude','parler de l’avenir'],'Premier plan = passé simple.'],
   ['Dans un récit, l’imparfait sert surtout à…','décrire le décor, les habitudes, les actions qui durent (arrière-plan)',['raconter une action soudaine','donner un ordre','exprimer une vérité générale'],'Arrière-plan = imparfait.'],
   ['Quel mot annonce souvent un passé simple ?','soudain',['chaque jour','autrefois','toujours'],'« Soudain » introduit une action brève.'],
   ['Lequel de ces temps est un temps du discours (lié au moment où l’on parle) ?','le passé composé',['le passé simple','le plus-que-parfait','aucun'],'Présent, passé composé et futur sont les temps du discours.',3],
   ['« Hier, j’ai rencontré ton frère », dit Léa. Pourquoi le passé composé ?','parce que Léa parle : c’est un temps du discours, lié au moment de la parole',['parce que c’est une description','parce que l’action dure longtemps','parce que c’est une erreur'],'Dans un dialogue, on emploie les temps du discours.',3],
   ['Quel est le passé simple de « venir » avec « ils » ?','ils vinrent',['ils venirent','ils vinèrent','ils venaient'],'venir : il vint, ils vinrent.',2]]);
  return mix([gC,4],[gV,3],[gId,2],[B,1]);})()},

{id:'fr6u',name:'Impératif et conditionnel présent',icon:'🎛️',domain:'Conjugaison et valeurs des temps',
 refs:[REF+' — « Conjugaisons à mémoriser et à maîtriser : impératif présent, conditionnel présent des verbes être et avoir, des 1er et 2e groupes, et de faire, aller, dire, venir, pouvoir, voir, vouloir, prendre »',GRAM],
 tip:'Conditionnel = radical du futur + terminaisons de l’imparfait (je chanter-ais). Impératif : trois personnes, sans sujet, et pas de « s » pour les verbes en -er avec « tu ».',
 c:C(`« <b>Prends</b> ton cahier. » « <b>Pourrais</b>-tu prendre ton cahier ? » La même demande, mais pas le même ton ! L’<b>impératif</b> donne un ordre ou un conseil ; le <b>conditionnel</b> permet d’être poli, d’imaginer ou de souhaiter.`,
  [T('L’impératif présent',`<p>Il se conjugue à <b>trois personnes</b>, <b>sans sujet</b> : 2e personne du singulier, 1re et 2e du pluriel.</p><table class="ptable"><tr><th>chanter</th><th>finir</th><th>faire</th><th>aller</th><th>être</th><th>avoir</th></tr><tr><td>chante</td><td>finis</td><td>fais</td><td>va</td><td>sois</td><td>aie</td></tr><tr><td>chantons</td><td>finissons</td><td>faisons</td><td>allons</td><td>soyons</td><td>ayons</td></tr><tr><td>chantez</td><td>finissez</td><td>faites</td><td>allez</td><td>soyez</td><td>ayez</td></tr></table><p>Les verbes en -er (et « aller ») n’ont <b>pas de s</b> à la 2e personne du singulier : « Range ta chambre ! », « Va au lit ! » (sauf devant en et y : « Vas-y ! »). Valeurs : ordre, conseil, consigne, interdiction (à la forme négative).</p>`),
   T('Le conditionnel présent',`<p>Formation : <b>radical du futur + terminaisons de l’imparfait</b> (-ais, -ais, -ait, -ions, -iez, -aient) : je chanter<b>ais</b>, nous finir<b>ions</b>, ils ser<b>aient</b>, tu aur<b>ais</b>, j’ir<b>ais</b>, il fer<b>ait</b>, nous dir<b>ions</b>, je viendr<b>ais</b>, tu pourr<b>ais</b>, il verr<b>ait</b>, je voudr<b>ais</b>, vous prendr<b>iez</b>.</p><p>Valeurs : <b>politesse</b> (« Je voudrais un renseignement »), <b>souhait</b> (« J’aimerais voyager »), <b>conseil</b> (« À ta place, je partirais »), <b>imaginaire ou hypothèse</b> (« Si j’avais des ailes, je volerais »).</p><p>Attention : « je chanterai » (futur, -ai) ≠ « je chanterais » (conditionnel, -ais).</p>`)],
  [{q:'Transforme « Tu prends ton cahier » en consigne, puis en demande polie.',s:['Consigne à l’impératif : « Prends ton cahier. » (pas de sujet).','Demande polie au conditionnel : « Pourrais-tu prendre ton cahier ? »','Le conditionnel de « pouvoir » (pourr- + -ais) adoucit la demande : le mode change l’effet produit.']}],
  ['J’identifie l’intention : ordonner, conseiller, demander poliment, souhaiter, imaginer.','Je choisis le mode : impératif (ordre, consigne) ou conditionnel (politesse, souhait, hypothèse).','Je vérifie la formation : radical du futur + -ais… ; impératif sans sujet ni « s » pour -er.'],
  ['Écrire un sujet devant un impératif (« Tu range ta chambre ! »).','Mettre un « s » à l’impératif des verbes en -er (« Ranges ta chambre ! »).','Confondre futur et conditionnel à la 1re personne (« je viendrai » / « je viendrais »).'],
  ['Impératif : 3 personnes, sans sujet ; consigne, ordre, conseil.','Conditionnel = radical du futur + terminaisons de l’imparfait.','Si + imparfait → conditionnel dans la principale.']),
 g:(()=>{
  const VC=['être','avoir','aller','faire','dire','venir','pouvoir','voir','vouloir','prendre','chanter','jouer','parler','regarder','écouter','danser','aimer','travailler','finir','choisir','grandir','réussir','remplir','obéir'];
  const gCond=d=>{const v=P(VC),i=R(0,5);const good=condit(v,i);const lab=sj(i,good);const bad=new Set([H.futur(v)[i],H.imparfait(v)[i],...[0,1,2,3,4,5].filter(k=>k!==i).map(k=>condit(v,k))]);bad.delete(good);
    const expl=`Radical du futur « ${futRad(v)}- » + terminaison de l’imparfait : <b>${lab}${good}</b>.`;
    if(d>=2&&Math.random()<.4)return txt(`Conjugue <b>${v}</b> au <b>conditionnel présent</b> : ${lab}<span class="gap">…</span>`,[good],{strict:true,lang:'fr',chips:CHIPS,expl,hint:'Radical du futur + -ais, -ais, -ait, -ions, -iez, -aient.'});
    return ch(`Conjugue <b>${v}</b> au <b>conditionnel présent</b> : ${lab}<span class="gap">…</span>`,good,pickN([...bad],3),{expl,hint:'Radical du futur + terminaisons de l’imparfait.'});};
  const VI=['être','avoir','aller','faire','dire','venir','voir','prendre','chanter','écouter','regarder','fermer','finir','choisir','remplir','obéir'];
  const PS=['2e personne du singulier','1re personne du pluriel','2e personne du pluriel'];
  const gImp=d=>{const v=P(VI),k=R(0,2);const f=imperatif(v),good=f[k];const pr=H.present(v);const bad=new Set([f[(k+1)%3],f[(k+2)%3],[pr[1],pr[3],pr[4]][k],k===0&&good.endsWith('e')?good+'s':null].filter(Boolean));bad.delete(good);
    const expl=`Impératif présent de « ${v} », ${PS[k]} : <b>${good}</b>${k===0&&(v.endsWith('er')&&v!=='aller'||v==='aller')?' (pas de « s » : verbe en -er ou « aller »)':''}. Pas de sujet exprimé.`;
    if(d===3&&Math.random()<.4)return txt(`Écris le verbe <b>${v}</b> à l’impératif présent, ${PS[k]} :`,[good],{strict:true,lang:'fr',chips:CHIPS,expl,hint:'Pas de sujet ; attention au « s ».'});
    return ch(`Conjugue <b>${v}</b> à l’impératif présent, ${PS[k]} :`,good,[...bad],{expl,hint:'Pas de sujet ; pas de « s » pour les verbes en -er avec tu.'});};
  const FC=[['Si j’avais un vélo, je (aller) à l’école à vélo.','aller',0,'c','« Si » + imparfait : la suite se met au conditionnel.'],['Demain, je (aller) à la piscine.','aller',0,'f','« Demain » : action à venir certaine, futur.'],['Je (vouloir) un chocolat chaud, s’il vous plaît.','vouloir',0,'c','Demande polie : conditionnel.'],['Quand je serai grand, je (être) pilote.','être',0,'f','« Quand je serai grand » : projet dans l’avenir, futur.'],['Si tu m’aidais, nous (finir) plus vite.','finir',3,'c','« Si » + imparfait : conditionnel.'],['L’été prochain, nous (voir) la mer.','voir',3,'f','« L’été prochain » : futur.'],['À ta place, je (prendre) le train.','prendre',0,'c','Conseil : conditionnel.'],['Si elles avaient le temps, elles (venir) avec nous.','venir',5,'c','« Si » + imparfait : conditionnel.'],['La semaine prochaine, vous (faire) un exposé.','faire',4,'f','« La semaine prochaine » : futur.'],['J’(aimer) tant voyager au Japon !','aimer',0,'c','Souhait : conditionnel.'],['Dans une heure, je (finir) mes devoirs.','finir',0,'f','Action à venir : futur.'],['Si j’étais un oiseau, je (voler) au-dessus des nuages.','voler',0,'c','Situation imaginaire : conditionnel.']];
  const gFC=d=>{const [s,v,i,m,e]=P(FC);const good=m==='c'?condit(v,i):H.futur(v)[i];const other=m==='c'?H.futur(v)[i]:condit(v,i);
    const q=s.replace(/\((\S+)\)/,'(<b>$1</b>)').replace('J’(<b>','Je (<b>');const bads=[other,H.imparfait(v)[i],H.present(v)[i]];
    return ch(`Futur ou conditionnel ? Complète : « ${q} »`,good,bads,{expl:`${e} → <b>${good}</b> (${m==='c'?'conditionnel : -ais':'futur : -ai'}).`,hint:'Futur (-ai) pour une action à venir ; conditionnel (-ais) pour la politesse, le souhait, l’imaginaire.'});};
  const B=bank([['« Ferme la fenêtre, s’il te plaît. » Quel mode ?','l’impératif',['le conditionnel','l’indicatif présent','l’infinitif'],'Verbe sans sujet qui donne une consigne : impératif.'],
   ['« Je voudrais un renseignement. » Quelle valeur du conditionnel ?','la politesse',['l’ordre','le futur certain','l’habitude'],'Le conditionnel adoucit la demande.'],
   ['« Si j’étais magicien, je transformerais ce livre en oiseau. » Quelle valeur du conditionnel ?','l’imaginaire (l’hypothèse)',['la politesse','l’ordre','l’habitude passée'],'La situation est imaginée.',2],
   ['« Mélangez la farine et les œufs. » Quelle est la valeur de l’impératif ?','une consigne (une étape de recette)',['un souhait','une hypothèse','une politesse au conditionnel'],'Dans une recette, l’impératif donne les consignes.',2],
   ['« Ne traverse pas au feu rouge ! » Quelle valeur ?','une interdiction (impératif à la forme négative)',['une hypothèse','un souhait poli','une vérité générale'],'L’impératif négatif interdit.',2],
   ['Quelle phrase est correctement écrite ?','Range ta chambre !',['Ranges ta chambre !','Tu range ta chambre !','Rangent ta chambre !'],'Impératif d’un verbe en -er : pas de « s », pas de sujet.'],
   ['Quelle est la formation du conditionnel présent ?','radical du futur + terminaisons de l’imparfait',['radical du présent + terminaisons du futur','auxiliaire + participe passé','radical de l’infinitif + -a, -èrent'],'je finir-ais, nous ser-ions, ils voudr-aient.',2],
   ['Quel est l’impératif de « avoir », 2e personne du singulier ?','aie',['as','ais','ait'],'avoir : aie, ayons, ayez.',3],
   ['Quel est l’impératif présent de « être », 2e personne du pluriel ?','soyez',['êtes','soyiez','seriez'],'être : sois, soyons, soyez.',3]]);
  return mix([gCond,3],[gImp,3],[gFC,2],[B,2]);})()},

/* ===================== VOCABULAIRE ET ORTHOGRAPHE LEXICALE ===================== */
{id:'fr6v',name:'Former les mots et enrichir son vocabulaire',icon:'🧬',domain:'Vocabulaire et orthographe lexicale',
 refs:[REF+' — « Établir des relations entre les mots » : composer et décomposer, mots simples, dérivés et composés, synonymes et antonymes de même classe, étymologie ; « Réemployer le vocabulaire » (registre de langue, polysémie)',EX6],
 tip:'Devant un mot inconnu, cherche le mot simple caché dedans, puis le sens du préfixe ou du suffixe : « in-cass-able » = qu’on ne peut pas casser.',
 c:C(`Tu n’as jamais rencontré le mot « inoubliable » ? Pourtant, tu peux le comprendre : « in- » (ne… pas) + « oubli » + « -able » (qu’on peut). Connaître la <b>formation des mots</b> et les <b>relations de sens</b> permet de comprendre et d’utiliser des milliers de mots.`,
  [T('Mots simples, dérivés et composés',`<p>Un mot <b>simple</b> ne peut pas être décomposé (fleur, mer). Un mot <b>dérivé</b> est formé d’un <b>radical</b> auquel on ajoute un <b>préfixe</b> (avant) et/ou un <b>suffixe</b> (après) : re-lire, fleur-iste, im-poli-tesse. Un mot <b>composé</b> réunit plusieurs mots : porte-monnaie, arc-en-ciel, pomme de terre.</p><table class="ptable"><tr><th>Préfixe</th><th>Sens</th><th>Suffixe</th><th>Sens</th></tr><tr><td>in-, im-, il-, ir-</td><td>ne… pas</td><td>-ette</td><td>petit (fillette)</td></tr><tr><td>re-</td><td>de nouveau</td><td>-eur, -euse</td><td>celui qui fait (nageur)</td></tr><tr><td>dé-, dés-</td><td>action inverse</td><td>-able</td><td>qui peut être (lavable)</td></tr><tr><td>pré-</td><td>avant</td><td>-ier</td><td>arbre fruitier (pommier)</td></tr><tr><td>sur-</td><td>au-dessus, en excès</td><td>-ment</td><td>adverbe de manière (doucement)</td></tr></table><p>Les mots d’une même <b>famille</b> partagent le même radical : terre, terrain, atterrir, souterrain.</p>`),
   T('Relations de sens',`<p><b>Synonymes</b> : sens proche et <b>même classe grammaticale</b> (peureux / craintif). <b>Antonymes</b> : sens contraire (monter / descendre). <b>Homonymes</b> : même prononciation, sens différent (ver, verre, vert, vers). Un mot <b>polysémique</b> a plusieurs sens selon le contexte (la souris de l’ordinateur / la souris grise). Le <b>sens propre</b> est le sens premier, concret ; le <b>sens figuré</b> est imagé (« un cœur de pierre »).</p><p><b>Registres de langue</b> : familier (bouquin), courant (livre), soutenu (ouvrage).</p>`),
   T('L’étymologie',`<p>Beaucoup de mots français viennent du <b>latin</b> ou du <b>grec</b>. Latin : <i>aqua</i> (eau → aquarium), <i>manus</i> (main → manuel), <i>pes, pedis</i> (pied → pédestre). Grec : <i>hydro</i> (eau → hydravion), <i>bio</i> (vie → biologie), <i>géo</i> (terre → géographie), <i>graphein</i> (écrire → calligraphie), <i>phone</i> (voix, son → téléphone), <i>chronos</i> (temps → chronomètre), <i>micro</i> (petit), <i>télé</i> (loin), <i>auto</i> (soi-même).</p>`)],
  [{q:'Que peux-tu déduire de « impossible » ?',s:['Je cherche le mot simple : « possible ».','Le préfixe « im- » (forme de « in- » devant p, b, m) exprime la négation.','« impossible » signifie « qui n’est pas possible » ; son antonyme est « possible ».']}],
  ['Je cherche le radical (le mot simple caché).','Je repère les éléments ajoutés (préfixe, suffixe) et leur sens.','Je vérifie le sens dans le contexte, puis dans un dictionnaire si nécessaire.'],
  ['Découper un mot au hasard sans vérifier le sens des morceaux (« terrible » ne vient pas de « terre »).','Proposer un synonyme d’une autre classe grammaticale (« peur » n’est pas synonyme de « peureux »).','Oublier que le contexte décide du sens d’un mot polysémique.'],
  ['Mot dérivé = préfixe et/ou suffixe + radical ; mot composé = plusieurs mots.','Synonymes et antonymes : même classe grammaticale.','Le latin et le grec éclairent le sens et l’orthographe de nombreux mots.']),
 g:mix([pairs([['in- / im- (inconnu, impossible)','ne… pas (la négation)'],['re- (relire, refaire)','de nouveau (la répétition)'],['dé- (défaire, décoller)','l’action inverse'],['pré- (préhistoire, prévoir)','avant'],['sur- (survoler, surpeuplé)','au-dessus ou en excès'],['co- / con- (copilote, compatriote)','avec'],['bi- (bicyclette, bimensuel)','deux'],['tri- (tricycle, triangle)','trois'],['télé- (télescope, téléphone)','loin'],['auto- (autoportrait)','soi-même']],{q:'Que signifie le préfixe %s ?',rq:'Quel préfixe signifie « %s » ?'}),2],
  [pairs([['-ette (fillette, maisonnette)','petit (diminutif)'],['-eur / -euse (nageur, danseuse)','personne qui fait l’action'],['-able (lavable, mangeable)','qui peut être…'],['-ier (pommier, cerisier)','arbre qui porte le fruit'],['-ment (doucement, rapidement)','adverbe de manière'],['-age (lavage, nettoyage)','action de…'],['-esse (tendresse, politesse)','qualité (nom formé sur un adjectif)'],['-ière (théière, salière)','récipient']],{q:'Quel est le sens du suffixe %s ?',rq:'Quel suffixe exprime : %s ?'}),2],
  [sort({'mot simple':['table','mer','chanter','fleur','loup'],'mot dérivé':['relire','fleuriste','impoli','lavage','chaton','dépasser'],'mot composé':['porte-monnaie','arc-en-ciel','chou-fleur','pomme de terre','tire-bouchon']},{q:'« %s » est…',e:(x,c)=>`« ${x} » : ${c}${c==='mot dérivé'?' (radical + préfixe ou suffixe)':c==='mot composé'?' (plusieurs mots réunis)':' (impossible à décomposer)'}.`}),2],
  [bank([['Quel mot simple a servi à former « fleuriste » ?','fleur',['fleurir','fleuve','iste'],'fleur + suffixe -iste (métier).'],['Quel mot simple a servi à former « atterrir » ?','terre',['terrible','atterrissage','air'],'a- + terre + -ir.'],['Quel mot simple a servi à former « agrandir » ?','grand',['grandir','agrandissement','dire'],'a- + grand + -ir.'],['Quel mot simple a servi à former « embarquer » ?','barque',['barrer','quer','embarquement'],'em- + barque + -er.',2],['Quel mot simple a servi à former « refroidir » ?','froid',['froisser','roi','refroidissement'],'re- + froid + -ir.'],['Quel mot simple a servi à former « gentillesse » ?','gentil',['gentiment','tille','gens'],'gentil + suffixe -esse (qualité).'],['Quel mot simple a servi à former « incassable » ?','casser',['cassette','casse-tête','incassablement'],'in- (ne… pas) + casser + -able (qui peut être).',2],
   ['Quel mot n’appartient pas à la famille de « terre » ?','terrible',['terrain','atterrir','souterrain'],'« terrible » vient du latin terribilis (« qui fait peur »), pas de terra.',2],['Quel mot n’appartient pas à la famille de « fleur » ?','fleuve',['fleuriste','fleurir','floral'],'« fleuve » vient du latin fluvius (« cours d’eau »).',2],['Quel mot n’appartient pas à la famille de « mer » ?','mairie',['marin','maritime','amerrir'],'« mairie » vient de « maire ».',2],['Quel mot n’appartient pas à la famille de « main » ?','maison',['manuel','manier','menottes'],'« maison » vient du latin mansio ; « manuel » et « manier » viennent de manus, la main.',3],['Quel mot n’appartient pas à la famille de « jour » ?','jouet',['journal','journée','ajourner'],'« jouet » vient de « jouer ».',2],['Quel mot n’appartient pas à la famille de « pied » ?','pieuvre',['piéton','piétiner','pédestre'],'« pieuvre » n’a aucun lien avec le pied ; « pédestre » vient du latin pes, pedis.',3],
   ['Quel est le synonyme de « peureux » ?','craintif',['peur','courageux','craindre'],'Un synonyme garde la même classe : adjectif → adjectif.'],['Quel est le synonyme de « commencer » ?','débuter',['début','finir','commencement'],'Verbe → verbe.'],['Quel est le synonyme de « la joie » ?','la gaieté',['joyeux','la tristesse','se réjouir'],'Nom → nom.',2],['Quel est l’antonyme de « monter » ?','descendre',['grimper','montée','escalier'],'Verbe de sens contraire.'],['Quel est l’antonyme de « généreux » ?','avare',['gentil','avarice','donner'],'Adjectif de sens contraire.',2],['Quel est l’antonyme de « le courage » ?','la lâcheté',['lâche','la bravoure','courageux'],'Nom de sens contraire : on garde la classe grammaticale.',3],
   ['« Elle a un cœur de pierre. » Le mot « pierre » est employé au…','sens figuré',['sens propre','sens scientifique','sens familier'],'Son cœur n’est pas en pierre : elle est insensible.'],['« Le maçon taille la pierre. » Le mot « pierre » est employé au…','sens propre',['sens figuré','sens imagé','registre soutenu'],'Sens concret, premier.'],['« Il brûle d’impatience. » Le verbe « brûler » est employé au…','sens figuré',['sens propre','registre familier','sens scientifique'],'Il ne brûle pas réellement : il est très impatient.'],['Dans « Clique avec la souris », le mot « souris » désigne…','l’appareil qui commande l’ordinateur',['le petit rongeur','un sourire','une couleur'],'Le mot est polysémique : le contexte décide du sens.'],
   ['Du grec « hydro » (eau) vient…','hydravion',['hypermarché','hibou','hymne'],'Un hydravion se pose sur l’eau.',2],['Du grec « chronos » (temps) vient…','chronomètre',['chromosome','chronique sportive au sens de « colonne »','chrysanthème'],'Le chronomètre mesure le temps.',2],['Le mot « géographie » est formé de deux éléments grecs qui signifient…','terre + écrire (décrire la Terre)',['vie + étude','loin + voir','eau + peur'],'géo = terre ; graphein = écrire.',3],['Du latin « aqua » (eau) vient…','aquarium',['agrafe','arbre','aquilon'],'Un aquarium est un bassin rempli d’eau.',2]]),5],
  [sort({'registre familier':['un bouquin','bosser','une bagnole','les fringues','se marrer'],'registre courant':['un livre','travailler','une voiture','les vêtements','rire'],'registre soutenu':['un ouvrage','œuvrer','une automobile','une tenue','s’esclaffer']},{q:'« %s » appartient au…'}),1])},

{id:'fr6w',name:'Orthographe lexicale et dictée raisonnée',icon:'✍️',domain:'Vocabulaire et orthographe lexicale',
 refs:[REF+' — « Mémoriser l’orthographe des mots : écrire correctement les mots fréquents en situation autonome » ; orthographe grammaticale en production d’écrits et dictées',EX6],
 tip:'Avant d’écrire un mot dont la fin est muette, cherche un mot de la même famille : « galop » → galoper. Pour un homophone, essaie de le remplacer (a → avait ; et → et puis ; son → mon).',
 c:C(`« Il a » ou « il à » ? « Un tapis » ou « un tapi » ? Pour écrire juste, on ne devine pas : on <b>raisonne</b>. La famille du mot, la règle et le remplacement par un autre mot permettent de <b>justifier</b> chaque choix.`,
  [T('Les stratégies de l’orthographe lexicale',`<ul class="lst"><li><b>Lettre muette finale</b> : un mot de la famille la fait entendre (grand → grande, lait → laitage, galop → galoper, tapis → tapisser, bavard → bavarder, sirop → siroter).</li><li><b>m devant m, b, p</b> : ombre, jambe, emporter, immense (exceptions : bonbon, bonbonne, néanmoins).</li><li><b>Le son [s] entre deux voyelles</b> s’écrit « ss » : poisson (et non poison, qui se prononce [z]).</li><li><b>ç</b> devant a, o, u : garçon, leçon, reçu ; <b>ge</b> devant a, o : pigeon, nageoire ; <b>gu</b> devant e, i : guitare, guerre.</li><li>Noms féminins en [e] : souvent <b>-ée</b> (une dictée, l’année), mais <b>-té</b> et <b>-tié</b> sans e (la liberté, l’amitié).</li></ul>`),
   T('Les homophones grammaticaux',`<table class="ptable"><tr><th>Homophones</th><th>Test</th></tr><tr><td>a / à</td><td>a (verbe avoir) → « avait »</td></tr><tr><td>et / est</td><td>et → « et puis » ; est (être) → « était »</td></tr><tr><td>son / sont</td><td>son → « mon » ; sont (être) → « étaient »</td></tr><tr><td>on / ont</td><td>on → « il » ; ont (avoir) → « avaient »</td></tr><tr><td>ou / où</td><td>ou → « ou bien » ; où = lieu ou moment</td></tr><tr><td>ces / ses</td><td>ces → « ces… -là » ; ses → « les siens »</td></tr><tr><td>c’est / s’est</td><td>c’est → « cela est » ; s’est devant un participe (il s’est levé)</td></tr><tr><td>la / l’a / là</td><td>l’a → « l’avait » ; là = lieu (« là-bas »)</td></tr><tr><td>leur / leurs</td><td>leur devant un verbe : invariable ; leurs devant un nom pluriel</td></tr></table>`),
   T('La dictée raisonnée',`<p>Pendant et après la dictée, je <b>justifie</b> chaque choix difficile : « J’écris “sont” car je peux dire “étaient” », « J’écris “arrivées” car l’auxiliaire est être et le sujet est féminin pluriel ».</p><p>Je relis en plusieurs passages : les <b>accords</b> (sujet-verbe, groupe nominal, participes), les <b>homophones</b>, puis les <b>mots</b> eux-mêmes (accents, lettres muettes).</p>`)],
  [{q:'Pourquoi « terrain » prend-il deux r ?',s:['Je le relie à un mot de sa famille : « terre ».','La famille de mots conserve le radical « terr- » : terre, terrain, terrasse, atterrir.','Je mémorise le radical, puis je vérifie dans le dictionnaire si j’hésite encore.']}],
  ['Je repère les mots que je connais et ceux dont je doute.','Pour chaque hésitation, je formule une hypothèse (famille du mot, règle, remplacement).','Je vérifie avec la règle, la famille ou un dictionnaire, puis je relis par passages.'],
  ['Recopier dix fois un mot sans chercher de stratégie de mémorisation.','Écrire « à » à la place de « a » sans faire le test « avait ».','Écrire « leurs » devant un verbe (« je leurs parle ») : le pronom « leur » est invariable.'],
  ['Une lettre muette se retrouve grâce à un mot de la famille.','Chaque homophone grammatical se vérifie par un remplacement.','Dictée raisonnée : je justifie avant de vérifier.']),
 g:(()=>{
  const MU=[['grand','grande'],['lait','laitage'],['bord','border'],['sirop','siroter'],['tapis','tapisser'],['chant','chanter'],['galop','galoper'],['retard','retarder'],['bavard','bavarder'],['dos','dossier'],['camp','camper'],['rang','ranger'],['accroc','accrocher'],['tricot','tricoter'],['gris','grise'],['sport','sportif'],['fusil','fusillade'],['outil','outillage']];
  const gMu=d=>{const [w,f]=P(MU);const root=w.slice(0,-1),last=w.slice(-1);const vars=['t','s','d','p','x',''].filter(c=>c!==last).map(c=>root+c);
    return ch(`Quelle est la bonne orthographe ? (Pense à un mot de la même famille.)`,w,pickN(vars,3),{expl:`On entend la lettre finale dans « ${f} » : on écrit <b>${w}</b>.`,hint:'Cherche un mot de la famille où la lettre finale s’entend.'});};
  const HO=[['Il (a / à) mangé une pomme.','a',['à'],'Je peux dire « il avait mangé » : verbe avoir.'],['Nous allons (a / à) la piscine.','à',['a'],'On ne peut pas dire « avait la piscine » : préposition à.'],['Le chat (et / est) sur le toit.','est',['et'],'On peut dire « le chat était » : verbe être.'],['Le chat (et / est) le chien jouent.','et',['est'],'On peut dire « et puis » : conjonction de coordination.'],['Ils (son / sont) partis tôt.','sont',['son'],'On peut dire « ils étaient partis » : verbe être.'],['Tom range (son / sont) cartable.','son',['sont'],'On peut dire « mon cartable » : déterminant possessif.'],['(On / Ont) entend la mer.','On',['Ont'],'On peut dire « il entend » : pronom.'],['Les élèves (on / ont) fini.','ont',['on'],'On peut dire « avaient fini » : verbe avoir.'],['Veux-tu du thé (ou / où) du café ?','ou',['où'],'On peut dire « ou bien » : choix.'],['La ville (ou / où) je suis né est petite.','où',['ou'],'« où » indique le lieu.'],['Léa range (ses / ces / c’est / s’est) affaires dans son sac.','ses',['ces','c’est','s’est'],'Ce sont les affaires de Léa (les siennes) : possessif « ses ».',2],['Regarde (ces / ses / c’est / s’est) nuages, là-bas !','ces',['ses','c’est','s’est'],'On peut dire « ces nuages-là » : démonstratif.',2],['Il (s’est / c’est / ses / ces) levé tôt.','s’est',['c’est','ses','ces'],'Devant un participe passé d’un verbe pronominal (se lever) : « s’est ».',2],['(C’est / S’est / Ces / Ses) une belle journée.','C’est',['S’est','Ces','Ses'],'On peut dire « cela est une belle journée » : « c’est ».',2],['Cette lettre, il (l’a / la / là) écrite hier.','l’a',['la','là'],'On peut dire « il l’avait écrite » : pronom + verbe avoir.',2],['Pose ton sac (là / la / l’a), près de la porte.','là',['la','l’a'],'« là » indique un lieu (on peut dire « là-bas »).',2],['Je ferme (la / l’a / là) fenêtre.','la',['l’a','là'],'Devant le nom « fenêtre » : article « la ».',2],['Les enfants (leur / leurs) parlent souvent.','leur',['leurs'],'Devant un verbe, le pronom « leur » est invariable.',3],['Ils rangent (leur / leurs) jouets.','leurs',['leur'],'Devant un nom pluriel (plusieurs jouets) : déterminant « leurs ».',3],['Le facteur (leur / leurs) apporte une lettre.','leur',['leurs'],'« leur » est un pronom placé devant le verbe : invariable.',3],['Elle (a / à) rendu (a / à) son frère le livre.','a … à',['à … a','a … a','à … à'],'« elle avait rendu » (avoir) ; « à son frère » (préposition).',3],['On (a / à) toujours le choix.','a',['à'],'On peut dire « on avait toujours le choix ».'],['Mes amis (son / sont) dans le jardin.','sont',['son'],'On peut dire « étaient dans le jardin ».'],['Ils (on / ont) peur du noir.','ont',['on'],'On peut dire « ils avaient peur ».']];
  const gH=d=>{const it=lvPick(HO,d,4);const [s,a,b,e]=it;return ch(`Choisis le bon homophone : « ${s} »`,a,b,{expl:`${e} → <b>${a}</b>.`,hint:'Essaie de remplacer : avait, était, et puis, mon, il, ou bien…'});};
  const DI=[['Les enfants jouent dans le jardin.',1],['Ma grand-mère prépare une tarte aux pommes.',1],['Le chat noir dort sur le canapé.',1],['Nous avons visité un vieux château.',1],['Elle a trouvé un caillou blanc.',1],['Les hiboux chassent pendant la nuit.',2],['Mes cousines sont arrivées hier soir.',2],['Ils ont rangé leurs affaires avant de partir.',2],['Le vent souffle et la mer est agitée.',2],['Où as-tu mis les clés de la maison ?',2],['Ces fleurs, je les ai cueillies dans le champ.',3],['La troupe de musiciens joue sur la place du village.',3],['Au loin brillaient les lumières du port.',3],['Quand la cloche sonna, les élèves se précipitèrent dehors.',3],['Les journaux annoncent une tempête pour demain.',3]];
  const gD=d=>{const [w]=lvPick(DI,d,1);return txt('🎧 Écoute et écris la phrase (dictée) :',[w],{audio:say(w),strict:true,lang:'fr',chips:CHIPS,expl:`On écrit : <b>${w}</b>`,hint:'Relis les accords (sujet-verbe, groupe nominal, participes), puis les homophones.'});};
  const B=bank([['Quelle est la bonne orthographe ?','une jambe',['une janbe','une jembe','une jamble'],'On écrit « m » devant b, p, m.'],['Quelle est la bonne orthographe ?','un poisson rouge',['un poison rouge','un poisont rouge','un poiçon rouge'],'Le son [s] entre deux voyelles s’écrit « ss » ; « poison » se lit [z].'],['Quelle est la bonne orthographe ?','un garçon',['un garcon','un garsson','un garçonn'],'La cédille donne le son [s] devant o.'],['Quelle est la bonne orthographe ?','la liberté',['la libertée','la libertè','la libertés'],'Les noms féminins en -té s’écrivent sans e final (sauf quelques exceptions comme la dictée, la jetée, la montée).',2],['Quelle est la bonne orthographe ?','une nageoire',['une nagoire','une nageoir','une najoire'],'« ge » devant o pour garder le son [ʒ].',2],['Quelle est la bonne orthographe ?','une guitare',['une gitare','une guittare','une ghitare'],'« gu » devant i pour garder le son [g].'],['Quelle est la bonne orthographe ?','emporter',['enporter','amporter','emportter'],'« m » devant p.']]);
  return mix([gMu,2],[gH,4],[gD,3],[B,1]);})()},

/* ===================== ÉCRITURE ===================== */
{id:'fr6x',name:'Écrire un récit et une description',icon:'📝',domain:'Écriture',
 refs:[REF+' — « Produire des écrits variés » : écrit narratif, cohérence textuelle, brouillon, révision à partir de l’autoévaluation',EX6],
 tip:'Avant d’écrire, note au brouillon : qui ? où ? quand ? quel problème ? comment ça finit ? Puis choisis deux ou trois détails précis qui font appel aux sens.',
 c:C(`Tu dois raconter l’entrée d’un personnage dans un château abandonné. Par où commencer ? Comment donner envie de lire la suite ? Écrire un récit ou une description, cela se <b>prépare</b>, se <b>rédige</b> puis s’<b>améliore</b>.`,
  [T('Construire un récit cohérent',`<p>Un récit enchaîne une <b>situation</b>, des <b>événements</b> et l’<b>évolution</b> des personnages (schéma narratif). Les <b>connecteurs</b> organisent le temps : d’abord, ensuite, puis, soudain, alors, enfin, le lendemain, quelques heures plus tard.</p><p>Les <b>temps</b> restent cohérents : récit au passé = imparfait (décor, description) + passé simple (actions). Les <b>reprises</b> évitent les répétitions : « le chevalier » → « il » → « le jeune homme » → « ce guerrier ».</p><p>Dans un dialogue : guillemets ou tirets, un tiret à chaque changement de personnage, verbes de parole précis (murmurer, s’écrier, répondre), sujet inversé dans l’incise : « Viens ! » <b>cria-t-il</b>.</p>`),
   T('Décrire',`<p>Une description <b>sélectionne</b> quelques détails significatifs (et non une longue liste d’adjectifs) et les <b>organise</b> : de près à loin, de haut en bas, de gauche à droite. Les <b>organisateurs spatiaux</b> guident le lecteur : au premier plan, à gauche, au fond, au-dessus, à l’horizon.</p><p>Les détails font appel aux <b>cinq sens</b> : la vue (une lueur tremblante), l’ouïe (le grincement d’une porte), l’odorat (une odeur de moisi), le toucher (la pierre glacée), le goût. Le vocabulaire précis et les comparaisons créent une atmosphère.</p>`),
   T('Brouillon, premier jet, révision',`<p>1. Lire le sujet et repérer les consignes. 2. Chercher des idées au brouillon. 3. Faire un plan rapide. 4. Rédiger un premier jet. 5. Relire une fois pour le <b>sens</b> (cohérence, répétitions, temps). 6. Relire pour la <b>langue</b> (accords, homophones, ponctuation) et corriger.</p>`)],
  [{q:'Raconter l’entrée dans un château abandonné : comment organiser le paragraphe ?',s:['Je situe le personnage et le lieu (qui, où, quand).','Je choisis deux ou trois détails sensoriels : la porte qui grince, l’odeur de moisi, le froid des murs.','Je fais survenir un événement qui relance l’action (« Soudain, une lumière s’alluma à l’étage »).','Je relis les temps (imparfait / passé simple) et les reprises du personnage.']}],
  ['Je prépare au brouillon un plan très court (situation, problème, événements, fin).','J’écris un premier jet sans chercher la perfection.','Je relis une fois pour le sens, puis une fois pour la langue, et j’améliore.'],
  ['Empiler des adjectifs sans choisir les détails utiles.','Mélanger les temps sans raison (passer du passé simple au présent).','Répéter sans cesse le même nom au lieu d’utiliser des reprises variées.'],
  ['Le brouillon est un outil pour penser.','Un détail précis vaut mieux qu’une longue liste.','Connecteurs, temps cohérents et reprises font la cohérence d’un récit.']),
 g:mix([sort({'la vue':['la lueur tremblante d’une bougie','les reflets dorés du lac','une ombre immense sur le mur'],'l’ouïe':['le grincement d’une porte','le murmure du ruisseau','le craquement du plancher'],'l’odorat':['une odeur de moisi','le parfum des lilas','l’odeur du pain chaud'],'le toucher':['la pierre glacée sous ses doigts','la douceur d’une fourrure','l’écorce rugueuse du chêne'],'le goût':['la saveur sucrée des fraises','l’amertume du café','le goût salé des larmes']},{q:'À quel sens fait appel le détail « %s » ?',e:(x,c)=>`« ${x} » : un détail qui fait appel au sens suivant, ${c}.`}),3],
  [bank([['Le héros entendit un craquement. <span class="gap">…</span>, une ombre surgit derrière lui. Quel connecteur convient ?','Soudain',['Chaque jour','Autrefois','Pourtant'],'« Soudain » introduit un événement brusque.'],
   ['Quelle phrase de dialogue est correctement ponctuée ?','« Viens ici ! » cria-t-il.',['« Viens ici ! » cria t-il.','« Viens ici ! » il cria-t-il.','« Viens ici ! » cria-il.'],'Dans l’incise, le sujet est inversé et relié par « -t- » quand le verbe finit par une voyelle.',2],
   ['Que marque un tiret au début d’une ligne de dialogue ?','le changement de personnage qui parle',['la fin du récit','une description','un titre'],'Chaque nouvelle réplique commence par un tiret.'],
   ['« Le chevalier entra dans la forêt. Le chevalier avançait prudemment. » Quelle reprise évite la répétition ?','Le jeune homme',['La forêt','Le cheval noir du roi','Ce château'],'Une reprise nominale doit désigner le même personnage.',2],
   ['« “Au secours !” dit-il. » Quel verbe de parole est plus précis ?','hurla-t-il',['murmura-t-il','répondit-il calmement','chuchota-t-il'],'Un appel au secours se crie : « hurla-t-il ».'],
   ['Quel organisateur indique un élément très éloigné ?','à l’horizon',['au premier plan','sous ses pieds','à côté de lui'],'« à l’horizon » : le plus loin possible du regard.'],
   ['Dans un récit au passé, quels temps utilise-t-on surtout ?','l’imparfait et le passé simple',['le présent et le futur','le conditionnel et l’impératif','le futur et le passé composé'],'Imparfait pour le décor, passé simple pour les actions.'],
   ['Quelle description est la mieux construite ?','Au premier plan, une barque usée dormait sur le sable ; plus loin, la mer grise se confondait avec le ciel.',['Il y avait une barque, la mer, le sable, le ciel, des mouettes, des rochers, du vent, des nuages.','La barque était belle, belle, très belle, vraiment très belle.','Une barque. La mer. Voilà.'],'Elle sélectionne des détails et les organise du proche au lointain.',2],
   ['« Il marchait dans le couloir. Soudain, une porte claque. » Quelle erreur faut-il corriger ?','le changement de temps : « claqua » au lieu de « claque »',['l’emploi de « Soudain »','le mot « couloir »','il n’y a pas d’erreur'],'Le récit est au passé : l’action soudaine se met au passé simple.',3],
   ['Quel verbe est le plus précis pour remplacer « faire » dans « faire un gâteau » ?','préparer',['avoir','être','mettre'],'Un verbe précis rend le texte plus riche.']]),4],
  [seq(['lire le sujet et repérer les consignes','chercher des idées au brouillon','faire un plan rapide','rédiger le premier jet','relire pour le sens (cohérence, temps, reprises)','relire pour la langue et corriger'],{nq:'Pour écrire un texte, quelle étape vient juste après « %s » ?',pq:'Pour écrire un texte, quelle étape vient juste avant « %s » ?',oq:'Remets dans l’ordre les étapes de l’écriture :'}),2],
  [sort({'narration':['Le garçon ouvrit la porte et courut vers la mer.','Ils montèrent dans la barque et ramèrent jusqu’à l’île.'],'description':['La maison était grande, ses volets bleus pendaient de travers.','Un brouillard épais couvrait la vallée endormie.'],'dialogue':['« Où vas-tu ? » demanda sa mère.','— Je reviens dans une heure, répondit-il.']},{q:'Le passage « %s » relève surtout…',e:(x,c)=>`C’est ${c==='narration'?'de la narration : il raconte des actions':c==='description'?'une description : il montre un lieu ou un personnage':'un dialogue : il rapporte des paroles'}.`}),1])},

{id:'fr6y',name:'Répondre, justifier et résumer',icon:'🧠',domain:'Écriture',
 refs:[REF+' — « Écrire pour réfléchir, apprendre et mémoriser » : écrire pour résumer et synthétiser, écrits réflexifs courts pour argumenter et justifier, hiérarchiser des idées',EX6],
 tip:'Une réponse complète suit la formule R-P-E : Réponse (avec les mots de la question) + Preuve (citation courte ou indice) + Explication (ce que la preuve montre).',
 c:C(`« Pourquoi le personnage a-t-il peur ? » Répondre « parce que » ne suffit pas, recopier tout un paragraphe non plus ! Une bonne réponse est <b>claire</b>, <b>prouvée</b> et <b>expliquée</b>. Et un bon résumé garde l’<b>essentiel</b>.`,
  [T('Répondre et justifier',`<p>1. <b>Je comprends la question</b> : « Pourquoi » attend une cause ; « Comment » une manière ; « Que ressent » un sentiment ; « Relève » une copie exacte d’un mot du texte ; « Justifie » une preuve.</p><p>2. <b>Je réponds</b> par une phrase complète qui reprend les mots de la question.</p><p>3. <b>Je prouve</b> : citation courte entre guillemets, recopiée exactement (avec la ligne : « l. 4 »), ou reformulation précise.</p><p>4. <b>J’explique</b> le lien entre la preuve et ma réponse. Connecteurs utiles : car, en effet, parce que, ce qui montre que.</p>`),
   T('Résumer',`<p>Un <b>résumé</b> est beaucoup plus court que le texte. Il garde les <b>informations essentielles</b> (qui ? quoi ? où ? pourquoi ? comment ça finit ?), respecte l’<b>ordre</b> des événements, utilise ses <b>propres mots</b>, sans citation, sans détail secondaire et <b>sans donner son avis</b>.</p><p><b>Hiérarchiser</b>, c’est distinguer l’idée principale des détails : « Le renard essaie de voler les poules » est essentiel ; « Il a une queue rousse » est un détail.</p>`)],
  [{q:'Question : « Pourquoi le personnage a-t-il peur ? » Le texte dit qu’il « se retourne sans cesse ».',s:['Réponse : « Le personnage a peur parce qu’il se croit suivi. »','Preuve : le texte indique qu’il « se retourne sans cesse ».','Explication : ce geste répété montre qu’il guette un danger derrière lui.']}],
  ['Je repère le mot interrogatif et ce que la question attend.','Je réponds clairement par une phrase complète.','J’ajoute une preuve (citation courte ou indice) et j’explique ce qu’elle montre.'],
  ['Donner seulement une citation sans expliquer ce qu’elle prouve.','Recopier le texte au lieu de résumer.','Ajouter son avis personnel dans un résumé.'],
  ['Réponse + preuve + explication.','Une citation est courte, exacte, entre guillemets.','Résumer : l’essentiel, dans l’ordre, avec ses mots.']),
 g:mix([pairs([['Pourquoi… ?','une cause, une raison'],['Comment… ?','une manière, un moyen'],['Quand… ?','un moment'],['Que ressent… ?','un sentiment, une émotion'],['Relève…','un mot ou une expression recopiés exactement'],['Justifie…','une preuve tirée du texte'],['Explique avec tes mots…','une reformulation personnelle']],{q:'Que doit-on donner quand une question commence par « %s » ?',rq:'Quelle consigne attend : %s ?',e:(a,b)=>`La consigne « ${a} » attend ${b}.`}),2],
  [onText([
   ['Le vieux pêcheur regardait le ciel noir. « Nous ne sortirons pas aujourd’hui », dit-il en rangeant ses filets. Les autres marins, eux, préparaient déjà leurs barques.',[
    ['Pourquoi le pêcheur ne sort-il pas ? Quelle réponse est la mieux construite ?','Il ne sort pas car il craint une tempête : il regarde « le ciel noir » et range ses filets, signe qu’il renonce à pêcher.',['Il ne sort pas.','« le ciel noir »','Il ne sort pas parce que moi non plus je n’aime pas la pluie.'],'La bonne réponse donne la réponse, une preuve et une explication.'],
    ['Quel passage prouve que le pêcheur renonce à partir ?','« en rangeant ses filets »',['« Les autres marins »','« préparaient déjà leurs barques »','« Le vieux pêcheur »'],'Ranger ses filets montre qu’il ne pêchera pas.'],
    ['Que peut-on déduire des autres marins ?','Ils sont moins prudents que le vieux pêcheur.',['Ils sont malades.','Ils ont déjà fini de pêcher.','Ils ne savent pas nager.'],'Ils se préparent malgré le ciel noir : ils prennent un risque.',2]]],
   ['Chaque soir, Nour cachait une lampe sous sa couverture pour lire. Un matin, sa mère trouva le livre ouvert sur l’oreiller et la lampe encore chaude.',[
    ['Que comprend la mère de Nour ? Quelle réponse est la mieux justifiée ?','Elle comprend que Nour lit la nuit, car la lampe est « encore chaude » et le livre est ouvert sur l’oreiller.',['Elle comprend tout.','Nour lit la nuit.','« la lampe encore chaude »'],'Réponse + preuves + lien logique.',2],
    ['Quelle est l’idée principale de ce passage ?','Nour lit en cachette la nuit, et sa mère le découvre.',['La lampe de Nour est jaune.','Nour a un oreiller.','La mère se lève le matin.'],'Les autres propositions sont des détails.',2]]]]),3],
  [bank([['Quel est le meilleur résumé de : « Un renard affamé aperçoit des raisins. Il saute plusieurs fois pour les attraper, sans succès. Vexé, il s’éloigne en disant qu’ils sont trop verts. » ?','Un renard qui ne parvient pas à attraper des raisins prétend qu’il n’en voulait pas.',['Un renard voit des raisins verts très jolis et c’est une belle histoire.','« Un renard affamé aperçoit des raisins. »','Un renard saute, saute, saute encore plusieurs fois.'],'Le résumé garde l’essentiel, avec ses mots, sans avis ni détail inutile.',2],
   ['Que ne doit-on pas mettre dans un résumé ?','son avis personnel',['les personnages principaux','l’événement principal','la fin de l’histoire'],'Un résumé reste objectif.'],
   ['Comment présente-t-on une citation ?','entre guillemets, recopiée exactement, courte',['sans guillemets, avec ses propres mots','en majuscules','en recopiant tout le paragraphe'],'La citation est la preuve exacte, donc fidèle au texte.'],
   ['Quel connecteur introduit une justification ?','car',['donc','ensuite','enfin'],'« car » introduit la cause, la raison qui justifie.'],
   ['Quel connecteur introduit une conséquence ?','c’est pourquoi',['parce que','car','en effet'],'« c’est pourquoi » annonce une conséquence.',2],
   ['Dans un résumé, l’ordre des événements…','est respecté',['est inversé','n’a aucune importance','est remplacé par l’ordre alphabétique'],'Le résumé suit le déroulement du texte.'],
   ['« Relève un adjectif qui décrit le monstre. » Que dois-tu faire ?','recopier exactement l’adjectif du texte, entre guillemets',['inventer un adjectif','expliquer toute l’histoire','donner ton avis sur le monstre'],'Relever = copier exactement.',2],
   ['Synthétiser deux documents, c’est…','rassembler en quelques phrases les informations essentielles des deux documents',['recopier le premier document','choisir le document le plus long','donner seulement son avis'],'La synthèse combine et hiérarchise les informations.',3]]),3],
  [sort({'idée essentielle':['Le héros doit traverser la forêt pour sauver sa sœur.','La sorcière lui tend un piège.','Il libère sa sœur grâce à une ruse.'],'détail secondaire':['Le héros porte une cape verte.','La forêt compte beaucoup de chênes.','La sorcière a un chat noir.']},{q:'Dans un résumé de conte, « %s » est…',e:(x,c)=>`« ${x} » : ${c}${c==='idée essentielle'?', à garder dans le résumé':', à supprimer dans un résumé'}.`}),2])},

/* ===================== ORAL ===================== */
{id:'fr6z',name:'Prendre la parole, écouter et débattre',icon:'🎙️',domain:'Oral',
 refs:[REF+' — « Écouter pour comprendre », « Dire pour être compris dans toutes les disciplines », « Participer à des échanges verbaux »',EX6],
 tip:'Avant de répondre dans un débat, reformule l’idée de l’autre (« Si je comprends bien, tu penses que… ») : tu montres que tu as écouté et ta réponse devient plus juste.',
 c:C(`Présenter un livre à la classe, défendre une idée dans un débat, rendre compte d’un reportage écouté : à l’oral, il faut être <b>clair</b>, <b>organisé</b> et <b>à l’écoute</b> des autres. Cela s’apprend comme l’écrit.`,
  [T('Prendre la parole',`<p>Un oral clair a une <b>idée directrice</b>, un <b>ordre</b> annoncé (introduction, deux ou trois parties, conclusion) et un <b>vocabulaire adapté</b>. On prépare <b>des mots-clés</b>, pas un texte entier à lire.</p><p>La voix et le corps comptent : parler assez fort et lentement, articuler, faire des pauses, <b>regarder l’auditoire</b>, se tenir droit, éviter les tics (« euh », « du coup »). On adapte le <b>registre</b> à la situation : courant ou soutenu en classe, devant un jury, avec un adulte qu’on ne connaît pas.</p>`),
   T('Écouter et débattre',`<p><b>Écouter activement</b> : savoir pourquoi on écoute, noter les mots-clés, repérer les informations explicites et implicites, puis <b>reformuler</b> avec ses mots.</p><p>Dans un <b>débat</b> : on demande la parole, on respecte les tours de parole, on s’appuie sur des <b>arguments</b> (des raisons) et des <b>exemples</b>, on tient compte de ce qui a été dit avant. On critique les idées, jamais les personnes. Formules utiles : « Je suis d’accord avec toi, car… » ; « Je ne partage pas ton avis, parce que… » ; « Tu as raison sur ce point, mais… ».</p>`)],
  [{q:'Présente un livre en une minute.',s:['Je donne le titre, l’auteur ou l’autrice et le genre.','Je présente brièvement le sujet sans révéler la fin.','J’explique ce que j’ai aimé ou non, avec un exemple précis.','Je termine par une recommandation claire (« Je le conseille à ceux qui aiment… »).']}],
  ['Je prépare trois idées-clés et quelques mots-clés, pas un texte entier.','Je regarde l’auditoire, je parle assez fort et lentement.','Pour répondre, je reformule d’abord l’idée de l’autre, puis je donne mon argument et un exemple.'],
  ['Lire entièrement ses notes sans regarder l’auditoire.','Couper la parole ou critiquer la personne au lieu de son idée.','Donner son avis sans le justifier par un argument.'],
  ['Oral = structure + voix + écoute.','Une opinion se justifie par un argument et un exemple.','Le débat n’est pas une dispute : on respecte les tours de parole.']),
 g:mix([sort({'exprimer son accord':['Je suis tout à fait d’accord avec toi.','Je partage ton avis.','Tu as raison de dire que…'],'exprimer son désaccord':['Je ne suis pas d’accord, car…','Je ne partage pas ton point de vue.','Je pense au contraire que…'],'nuancer':['Tu as raison sur ce point, mais…','C’est vrai en partie, cependant…','Je suis d’accord, sauf pour…'],'reformuler':['Si je comprends bien, tu penses que…','Autrement dit, tu veux dire que…','Tu affirmes donc que…']},{q:'La formule « %s » sert à…',e:(x,c)=>`« ${x} » sert à ${c}.`}),3],
  [sort({'un fait':['Le collège compte 450 élèves.','La cantine ouvre à 11 h 30.','Le roman a été publié en 1883.'],'une opinion':['Ce roman est passionnant.','La cantine est trop bruyante.','Je préfère le théâtre au cinéma.'],'une opinion justifiée par un argument':['Il faut lire chaque jour, car la lecture enrichit le vocabulaire.','Le vélo est utile, parce qu’il ne pollue pas.']},{q:'« %s » est…',e:(x,c)=>`C’est ${c} : ${c==='un fait'?'cela peut se vérifier':c==='une opinion'?'c’est un avis personnel, sans justification':'l’avis est suivi d’une raison (car, parce que)'}.`}),2],
  [seq(['saluer et annoncer le sujet','présenter le plan','développer les parties avec des exemples','conclure en résumant l’essentiel','répondre aux questions du public'],{nq:'Dans un exposé oral, qu’est-ce qui vient juste après « %s » ?',pq:'Dans un exposé oral, qu’est-ce qui vient juste avant « %s » ?',oq:'Remets dans l’ordre les étapes d’un exposé :'}),2],
  [pairs([['une interview','des questions posées à une personne pour recueillir ses réponses'],['un reportage','une enquête sur le terrain, avec des images, des sons et des témoignages'],['un débat','un échange organisé où plusieurs personnes défendent des avis différents'],['un exposé','une présentation organisée de connaissances devant un public'],['un témoignage','le récit de ce qu’une personne a vu ou vécu']],{q:'Que désigne %s ?',rq:'Quel genre de discours oral est %s ?'}),2],
  [bank([['Pendant un oral, que faut-il faire de ses notes ?','s’en servir comme aide-mémoire, en levant souvent les yeux vers le public',['les lire mot à mot sans lever la tête','les cacher et improviser tout','les distribuer au public'],'Des mots-clés permettent de parler en regardant l’auditoire.'],
   ['Dans un débat, quelle attitude est correcte ?','attendre son tour et répondre à l’idée de l’autre avec un argument',['couper la parole pour gagner du temps','se moquer de celui qui n’est pas d’accord','répéter son avis plus fort'],'On critique les idées, pas les personnes.'],
   ['Quel registre choisir pour présenter son exposé à la classe ?','le registre courant',['le registre familier','le langage SMS','l’argot'],'La situation scolaire demande un registre courant ou soutenu.'],
   ['Pourquoi reformuler l’idée de l’autre avant de répondre ?','pour vérifier qu’on l’a bien comprise et lui montrer qu’on l’écoute',['pour gagner du temps','pour se moquer','pour éviter de répondre'],'La reformulation rend l’échange plus juste.',2],
   ['Quelle phrase justifie une opinion ?','J’ai aimé ce livre, car le héros est attachant et le suspense dure jusqu’à la fin.',['J’ai aimé ce livre.','Ce livre, c’est trop bien.','Je ne sais pas.'],'L’opinion est suivie d’arguments (« car… »).',2],
   ['En écoutant un reportage, que noter en priorité ?','les mots-clés et les informations essentielles',['toutes les phrases mot à mot','la couleur des vêtements du journaliste','rien, il suffit d’écouter'],'Prendre des notes rapides aide à reformuler ensuite.',2],
   ['Pour présenter un livre, que faut-il éviter ?','révéler toute la fin',['donner le titre et l’auteur','dire ce qu’on a aimé','recommander le livre'],'Il faut donner envie de lire sans tout dévoiler.']]),3])}
]);
})();
